    {"id": 0x0079, "text": "\x1A\x13P\x08Du kreeg \x05AGoronens Armband\x05@!\x09\x01Nú du kan trekken op Bomb \x01Flowers. Stá näst til ain und\x01Bruk \x05C\x9F\x05@ til trekken et op!\x02", "box_type": 2},
    {"id": 0x007A, "text": "\x13\x1D\x08Du zetten ain \x05AMaðk \x05@in flaska!\x09\x01Du kan Los et af pressing\x01\x05F¡\x05@. Þet kind de Maðk prefers til\x01live in klein holar in grúnd.\x02", "box_type": 2},
    {"id": 0x007B, "text": "\x1A\x13p\x08Du obténed \x05AGerudos \x01Membership Card\x05@!\x09\x01Du kan kregen inn Gerudos\x01tréning grúnd in ser hideút.\x02", "box_type": 2},
