    {"id": 0x0080, "text": "\x1A\x13l\x08Du kreeg \x05BKokiris Smaragd\x05@!\x09\x01Þet ist Andlig Stein de \x01 Skog, nú entrusted til \x01du af Stór Deku Trä.\x02", "box_type": 2},
    {"id": 0x0081, "text": "\x1A\x13m\x08Du obténed \x05AGoronens Rubin\x05@!\x09\x01Þet ist Andlig Stein de \x01Fyr passed ned af Gorons!\x02", "box_type": 2},
