    {"id": 0x0096, "text": "\x08Ik am sorri...Ik ne kan seljen þet til\x01du unless du havst ain flaska til \x01zetten et in.\x09\x0A\x02", "box_type": 0},
    {"id": 0x0097, "text": "\x13 \x08Du kaught ain \x05APoe \x05@in ain flaska!\x09\x01Einwat gut might happen!\x02", "box_type": 2},
    {"id": 0x0098, "text": "\x13\x1A\x08Du kreeg \x05ALon Lon Mjolk\x05@!\x09\x01Þet mjolk ist meir nutritiús!\x01Bruk et mit \x05F¡ \x05@til rekover dín \x01líf energi!\x04\x13\x1ADu skal rekover \x05Afim hertar\x05@\x01per drink. Þar sin twei\x01drinks per flaska.\x04\x13\x1AAuf \x05FValting Underskerm\x05@,\x01du kan sette et til \x05F§\x05@, \x05F¦ \x05@oder \x05F¨\x05@,\x01und dan Bruk det \x05F¡ \x05@til nim \x01ain drink.\x02", "box_type": 2},
    {"id": 0x0099, "text": "\x1A\x13\x1B\x08Du kreeg ain \x05ATom Flaska\x05@!\x09\x01Zetten einwat innan und \x01Drukk \x05F¡ \x05@til Bruk et... Wat?\x01Einwats alrédi innan!?\x02", "box_type": 2},
    {"id": 0x009A, "text": "\x1A\x13!\x08Du kreeg ain \x05AVreid Egg\x05@!\x09\x01Fült als þars einwat\x01moving innan! Sette et til \x05F¡ \x05@und \x01séen wat happens!\x04\x1A\x13!Auf \x05FValting Underskerm\x05@,\x01du kan sette et til \x05F§\x05@, \x05F¦ \x05@oder \x05F¨\x05@,\x01und dan Drukk \x05F¡ \x05@til Bruk et.\x02", "box_type": 2},
    {"id": 0x009B, "text": "\x08pilar 30 styk 60 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x009C, "text": "Mís kurrent hot seller ist  \x01\x05DHylia-Skjold\x05@, aber et might vesen ok \x01grós für du, kind.\x0B\x02", "box_type": 0},
    {"id": 0x009D, "text": "Wir moved hér frá kastel \x01stad. Ik weten tidar sin túgh, aber\x01Ik hope du skal vesen ain stédi \x01kustomer für uns!\x0B\x02", "box_type": 0},
    {"id": 0x009E, "text": "\x08\x06GWelcome!\x09\x0B\x02", "box_type": 0},
    {"id": 0x009F, "text": "\x08\x05ADeku-Skjold 40 Rubinar\x01\x05@Aingång eqipped, du kan defend \x01mit \x05D£\x05@. Wenn sette auf fyr, et skal\x01burn!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A0, "text": "\x08\x05Apil (10 styk) 20 Rubinar\x01\x05@Du mos haven ain boge til skjúten sen.\x01Du ne kan Kaup sen unless du\x01have ain boge.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A1, "text": "\x08\x05ADeku-Stav (1 del) 10 Rubinar\x01\x05@Ain lang brank gaþered frá \x01Stór Deku Trä. Du kan Bruk et\x01als ain vápn, aber et skal breken.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A2, "text": "\x08\x05ADeku-Nötter (10 styk) 30 Rubinar\x01\x05@Werfen sen til stunnen dín fiendar.\x01Du kan Kaup nur amúnt du\x01kan aktualli tragen.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A3, "text": "\x08\x05ABombar (5 styk) 25 Rubinar\x01\x05@Nim et út mit \x05F¡\x05@ und druk \x01\x05F¡\x05@ til werfen et. Du kan Kaup sen\x01nur wenn du havst ain Bombarekk.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A4, "text": "\x1A\x13;\x08Du kreeg \x05BKokiri-Sverd\x05@!\x09\x01Auf \x05CUtrust Underskerm\x05@,\x01val et mit kursor und\x01utruste et mit \x05C\x9F\x05@.\x04\x1A\x13;Þet ist ain skjult skatt de\x01 Kokiri, aber du kan línen et\x01gegn ain meðan. Vesen viss til praktike \x01mit et för du sannlig fight!\x02", "box_type": 2},
    {"id": 0x00A5, "text": "\x08\x05ARöd Trank 30 Rubinar\x01\x05@Drink til rekover dín líf energi.\x01Þet ist bara ain single dose.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A6, "text": "\x08\x05AGrän Trank 30 Rubinar\x01\x05@Drink til rekover dín Magikkraft.\x01Þet ist bara ain single dose.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A7, "text": "\x1A\x13\x01\x08Nú du kan tragen\x01manig \x05ADeku-Nötter\x05@!\x01Du kan halten op til \x05F30\x05@ nötar!\x09\x02", "box_type": 2},
    {"id": 0x00A8, "text": "\x1A\x13\x01\x08Du kan nú tragen ok\x01meir \x05ADeku-Nötter\x05@! Du kan tragen\x01op til \x05F40\x05A \x05@nötar!\x09 \x02", "box_type": 2},
    {"id": 0x00A9, "text": "\x08\x05AHylia-Skjold 80 Rubinar\x01\x05@Þet ist ain grós, tung skjold bara \x01als ainar Hylian Knights bruken.\x01Et kan stá op til flame angrept!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AA, "text": "\x08\x05AGoron-Tunika 200 Rubinar\x01\x05@Ain tunik gemakt af Gorons. Voksen\x01size. Protects du frá hét\x01damage.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AB, "text": "\x08\x05AZora-Tunika 300 Rubinar\x01\x05@Ain tunik gemakt af Zoras. Voksen size.\x01Prevents du frá dróning\x01underwater.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AC, "text": "\x08\x05AHelingshert 10 Rubinar\x01\x05@Þet skal instantli refill ain\x01Hertkar.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AD, "text": "\x1A\x13\x05\x08Du kreeg \x05ADins Fyr\x05@!\x09\x01Es fireball engulfs everiþing!\x01Et ist angrepen magik du kan bruken\x01mit \x05F¡\x05@.\x02", "box_type": 2},
    {"id": 0x00AE, "text": "\x1A\x13\x0D\x08Du kreeg \x05BFarores Vind\x05@!\x09\x01Þet ist varp magik du kan bruken \x01mit \x05F¡\x05@. Varp wenn du sin in \x01danger!\x04\x1A\x13\x0DDu skal teleport til \x05BVarp\x01Punkt\x05@. Wenn du fyrst Bruk \x01magik, du skal kréte ain Varp\x01Punkt.\x04\x1A\x13\x0DWenn du Bruk magik \x01aftur, du kan eiþer dispel\x01 Varp Punkt du kréted last\x01tid oder varp til det punkt.\x02", "box_type": 2},
    {"id": 0x00AF, "text": "\x1A\x13\x13\x08Du kreeg \x05CNayrus Líbe\x05@!\x09\x01Kasten þet til kréte ain póerful\x01protektive barrier. Et ist vern \x01magik du kan Bruk mit \x05F¡\x05@.\x02", "box_type": 2},
    {"id": 0x00B0, "text": "\x08\x05Apilar (50 styk) 90 Rubinar\x01\x05@Skjúten þese mit ain boge. Du ne kan\x01Kaup sen unless du havst ain boge.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B1, "text": "\x08\x05ABombar (10 styk) 50 Rubinar\x01\x05@Nim et út mit \x05F¡\x05@ und druk \x01\x05F¡\x05@ aftur, til et an werfen. Du ne kan\x01Kaup sen óne ain Bombarekk.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B2, "text": "\x08\x05ADeku-Nötter (5 styk) 15 Rubinar\x01\x05@Werfen sen til stunnen dín fiendar.\x01Du kan tragen nur ain limited \x01amúnt de sen.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B3, "text": "\x08\x05AFisk 200 Rubinar\x01\x05@Bara kaught und so frisk!\x01Du kan halten et in ain flaska.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B4, "text": "Du zerstört ain \x05AGyll Skulltula\x05@.\x01Du kreeg ain tegn proving du \x01zerstört et!\x02", "box_type": 2},
    {"id": 0x00B5, "text": "Du zerstört ain \x05AGyll Skulltula\x05@.\x01Du kreeg ain tegn proving du \x01zerstört et!\x02", "box_type": 2},
    {"id": 0x00B6, "text": "\x08Féas Ande 50 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x00B7, "text": "\x08\x05AFéas Ande 50 Rubinar\x01\x05@Du mos haven ain Tom Flaska til zetten\x01et in. Ne Gáe inn battle \x01óne et!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B8, "text": "\x08Blá Fyr 300 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x00B9, "text": "\x08\x05ABlá Fyr 300 Rubinar\x01\x05@Du mos haven ain Tom Flaska til zetten\x01þet in. Bruk et til füle \x01refreşing kúlness.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BA, "text": "\x08Flaska Maðk 50 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x00BB, "text": "\x08\x05AFlaska Maðk 50 Rubinar\x01\x05@Du mos haven ain Tom Flaska til zetten\x01et in. Et sýnt als bara ain\x01ordinari bug...\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BC, "text": "\x08\x05ABombchu (10 styk) 100 Rubinar\x01\x05@Þet sýnt als ain toi múse, aber\x01et ist aktualli ain self-propelled tid\x01bomb!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BD, "text": "\x08\x05AWir sin temporarili út de\x01stok auf det ting.\x05@\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BE, "text": "K'mon, mar! Du sin ok alt für \x01þet spel!\x0B\x02", "box_type": 0},
    {"id": 0x00BF, "text": "\x06@Huh? Wha--!\x04\x08\x06PUh-ó!\x09\x04\x08\x06>Ain kustomer!\x09\x0B\x02", "box_type": 0},
    {"id": 0x00C0, "text": "\x069zzzzz...zzzzz...\x0B\x02", "box_type": 0},
    {"id": 0x00C1, "text": "\x08\x05Apilar (30 styk) 60 Rubinar\x01\x05@Du mos haven ain boge til skjúten sen.\x01Bruk sen, und du skal rennen út.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00C2, "text": "\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Samlen fér styk total til kregen\x01ander Hertkar. Meir\x01karar mén meir líf energi!\x02", "box_type": 2},
    {"id": 0x00C3, "text": "\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01So fjarr, du havst gesamlt twei \x01styk. Mit twei meir styk, \x01du skal gén meir líf energi!\x02", "box_type": 2},
    {"id": 0x00C4, "text": "\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Nú du havst gesamlt þri \x01styk! Mit ander del, dín \x01líf energi skal vesen póered op!\x02", "box_type": 2},
    {"id": 0x00C5, "text": "\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Du havst geendet ander Hert\x01Kar! Dín maximum líf\x01energi ist inkrésed!\x02", "box_type": 2},
    {"id": 0x00C6, "text": "\x13r\x08Du kreeg ain \x05AHertkar\x05@!\x09\x01Dín maximum líf energi ist \x01inkrésed af ain hert. Dín líf\x01energi skal vesen totalli filled.\x02", "box_type": 2},
    {"id": 0x00C7, "text": "\x13t\x08Du kreeg \x05AHerrelykl\x05@!\x09\x01Nú du kan kregen innan  \x01kamber var Herre lurks.\x02", "box_type": 2},
    {"id": 0x00C8, "text": "Non, du ne have enúgh\x01Rubinar!\x0B\x02", "box_type": 0},
    {"id": 0x00C9, "text": "\x08\x06$Rétt vel, du sin ferdig!\x09\x01Bitte warten útan meðan Ik sette \x01op dín näst kallenge!\x0B\x02", "box_type": 0},
    {"id": 0x00CA, "text": "\x08Bombar 5 styk 35 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x00CB, "text": "\x08\x05ABombar (5 styk) 35 Rubinar\x01\x05@Nim et út mit \x05F¡\x05@ und druk \x01\x05F¡\x05@ aftur, til et an werfen. Du ne kan\x01Kaup sen óne ain Bombarekk.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00CC, "text": "\x08Du kreeg ain \x05CBlá Rubin\x05@!\x01Det ist \x05Cfim Rubinar\x05@!\x09\x02", "box_type": 2},
    {"id": 0x00CD, "text": "\x1A\x13S\x08Du kreeg \x05CSilfrskal\x05@!\x09\x01Jump inn vatn und druk \x01\x05C\x9F\x05@. Du kan dive díper dan du\x01konde för.\x02", "box_type": 2},
    {"id": 0x00CE, "text": "\x1A\x13T\x08Du kreeg \x05CGyllskal\x05@!\x09\x01Jump inn vatn und druk \x01\x05C\x9F\x05@. Nú du kan dive meir\x01díper dan du konde för!\x02", "box_type": 2},
    {"id": 0x00CF, "text": "\x08\x05DEt sýnt als þet ting dót ne \x01verk hér...\x05@\x09\x02", "box_type": 0},
    {"id": 0x00D0, "text": "\x08\x05DEt ne opnar pas!\x05@\x09\x02", "box_type": 0},
    {"id": 0x00D1, "text": "\x1A\x06\x14Du havst lérned \x05BSarias Sang\x05@!\x02", "box_type": 2},
    {"id": 0x00D2, "text": "\x1A\x06\x11Du havst lérned \x05AEponas Sang\x05@!\x02", "box_type": 2},
    {"id": 0x00D3, "text": "\x1A\x06\x0BDu havst lérned \x05FSóls Sang\x05@!\x02", "box_type": 2},
    {"id": 0x00D4, "text": "\x1A\x06\x15Du havst lérned \x05CZeldas Vísesang\x05@!\x02", "box_type": 2},
    {"id": 0x00D5, "text": "\x1A\x06\x05Du havst lérned \x05DSang de Tids\x05@!\x02", "box_type": 2},
    {"id": 0x00D6, "text": "\x1ADu havst lérned \x05ESang de Storms\x05@!\x02", "box_type": 2},
    {"id": 0x00D7, "text": "\x1AWelcome \x0F!\x01Ik am Stór Féa de Kraft!\x04\x1AIk am sker til grant du ain \x05Bsverd\x01tekniqe\x05@.\x04\x1AKregen et nú!\x02", "box_type": 0},
    {"id": 0x00D8, "text": "\x1AWelcome \x0F!\x01Ik am Stór Féa de Wisdom!\x04\x1AIk am sker til enhanke dín \x05Bmagik \x01kraft\x05@.\x04\x1AKregen et nú!\x02", "box_type": 0},
    {"id": 0x00D9, "text": "\x1AWelcome \x0F!\x01Ik am Stór Féa de Courage!\x04\x1AIk am sker til enhanke dín \x01\x05Dverns kraft\x05@.\x04\x1AKregen et nú!\x02", "box_type": 0},
    {"id": 0x00DA, "text": "Wenn du sin wéri de battle,\x01bitte komen zurück til Besoek mik!\x0B\x02", "box_type": 0},
    {"id": 0x00DB, "text": "Welcome \x0F!\x01Ik skal súþe dín wúnds.\x0B\x02", "box_type": 0},
    {"id": 0x00DC, "text": "\x13X\x08Du kreeg \x05ADeku-Frä\x05@!\x09\x01Þese sin klein, hard frä\x01det du kan Bruk als kular\x01für dín Slinga.\x02", "box_type": 2},
    {"id": 0x00DD, "text": "\x08\x1ADu mastered geheimnis sverd\x01tekniqe de \x05ADrejangrep\x05@!\x09\x04\x1AHalten \x05B \x05@ til karge dín vápn!\x01Los \x05B \x05@ til loslaten ain wave\x01de energi mit dín spin!\x04\x1AWenn du vollen til Los energi\x01óne karging dín vápn, bara \x01\x05Drotate ª aingång \x05@und druk \x05B  \x05@für\x05B\x01\x05@ain meir effektive snel spin!\x02", "box_type": 2},
    {"id": 0x00DE, "text": "\x08Deku-Frä 30 styk 30 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x00DF, "text": "\x08\x05ADeku-Frä (30 styk) 30 Rubinar\x01\x05@Du kan Bruk sen als kular für\x01dín Slinga. Du ne kan Kaup \x01sen unless du havst ain Slinga.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00E0, "text": "\x05DDu vollen til talen til Saria, rétt?\x01\x05@\x01\x1B\x05BTalen til Saria\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x00E1, "text": "\x05DSannlig? Dan dó du vollen til talen \x01til mik?\x01\x05@\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x00E2, "text": "\x06<\x0F...?\x01\x06\x0DÞet ist \x05BSaria\x05@. Kan du hören mik?\x0B\x02", "box_type": 2},
    {"id": 0x00E3, "text": "\x05DDó du vollen til talen til Saria\x01aftur?\x05@\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 2},
    {"id": 0x00E4, "text": "\x1A\x08Dín \x05BMagikmeter\x05@ ist enhanked!\x09\x02", "box_type": 2},
    {"id": 0x00E5, "text": "\x1A\x08Dín \x05Dverns kraft\x05@ ist enhanked!\x09\x02", "box_type": 2},
    {"id": 0x00E6, "text": "\x1A\x08Du kreeg ain \x05Fbundle de pilar\x05@!\x09\x02", "box_type": 2},
    {"id": 0x00E7, "text": "\x1AWenn du karge kraft gegn ain Spin\x01Angrepen, Magikkraft skal vesen\x01konsumed. Betalen attençion til dín\x01grän \x05BMagikmeter\x05@!\x04\x1AHé, dreng! Du sin ain messenger de\x01 Konglig Família, sin ne du?\x04\x1ANäst tid du sin in ser\x01neighborhúd, du skold drop in\x01auf ain friend de mís wer lives af\x01Hyrule Kastel.\x04\x1AŞe'll sureli grant du ander\x01nüv kraft!\x02", "box_type": 0},
    {"id": 0x00E8, "text": "\x1ADín Magikkraft havt gevesen \x01enhanked! Nú du havst twike\x01als meir \x05AMagikkraft\x05@!\x02", "box_type": 0},
    {"id": 0x00E9, "text": "\x1ADín verns kraft havt gevesen \x01enhanked! Damage inflikted af \x01fiendar skal vesen \x05Areduked af half\x05@.\x02", "box_type": 0},
    {"id": 0x00EA, "text": "\x1AWelcome \x0F!\x01Ik am Stór Féa de Magik!\x04\x1AIk skal geven du ain \x05Amagikformel\x05@.\x01Bitte nim et.\x02", "box_type": 0},
    {"id": 0x00EB, "text": "\x08Ik am sorri, aber du ne kan línen\x01þet mask iet.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00EC, "text": "\x1ADu kan bruken \x05ADins Fyr\x05@ ne nur til\x01angrepen aber ok til burn tingar!\x02", "box_type": 0},
    {"id": 0x00ED, "text": "\x1AErinnern, du kan bruken \x05BFarores\x01Wind\x05@ nur in dýpkastelar det have\x01ain Dýpkastels Kart skjult innan, OK?\x02", "box_type": 0},
    {"id": 0x00EE, "text": "\x1A\x05CNayrus Líbe\x05D \x05@ist in effekt für nur\x01ain limited tid, so Bruk et karefulli.\x02", "box_type": 0},
    {"id": 0x00EF, "text": "Wenn battle havt gemakt du wéri,\x01bitte komen zurück til séen mik.\x02", "box_type": 0},
    {"id": 0x00F0, "text": "\x08Du kreeg ain \x05ARöd Rubin\x05@!\x01Det ist \x05Atwentig Rubinar\x05@!\x09\x02", "box_type": 2},
    {"id": 0x00F1, "text": "\x08Du kreeg ain \x05EPurple Rubin\x05@!\x01Det ist \x05Efimtig Rubinar\x05@!\x09\x02", "box_type": 2},
    {"id": 0x00F2, "text": "\x08Du kreeg ain \x05FHuge Rubin\x05@!\x01Þet Rubin ist worþ ain whopping\x01\x05Ftwei hunder Rubinar\x05@!\x09\x02", "box_type": 2},
    {"id": 0x00F3, "text": "\x13w\x08Du kreeg ain \x05ADyrlykl\x05@!\x09\x01Bruk þet lykl til kontinue til \x01näst rúm. Val ain skatt \x01kest und séen hú luki du sin!\x02", "box_type": 2},
    {"id": 0x00F4, "text": "\x05DTapar!\x05@\x04\x08Du fand nur \x05Bain Rubin\x05@.\x01Du sin ne meir luki.\x09\x02", "box_type": 2},
    {"id": 0x00F5, "text": "\x05DTapar!\x05@\x04\x08Du fand \x05Cfim Rubinar\x05@.\x01Ok so, du sin ne meir luki.\x09\x02", "box_type": 2},
    {"id": 0x00F6, "text": "\x05DTapar!\x05@\x04\x08Du fand \x05Atwentig Rubinar\x05@.\x01Dín last selekçion var ain mistake,\x01wasn't et! Hú frustrating!\x09\x02", "box_type": 2},
    {"id": 0x00F7, "text": "\x05AVinner!\x05@\x04\x08Du fand \x05Ffimtig Rubinar\x05@.\x01Du sin ain genuineli luki mar!\x09\x02", "box_type": 2},
    {"id": 0x00F9, "text": "\x13\x1E\x08Du zetten ain \x05AGrós Poe \x05@in ain flaska!\x09\x01lat uns seljen et an \x05AAndebúð\x05@!\x01Einwat gut might happen!\x02", "box_type": 2},
    {"id": 0x00FA, "text": "\x06I\x05AVinner\x05@!\x04\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Samlen fér styk total til kregen\x01ander Hertkar. Meir\x01karar mén meir líf energi!\x02", "box_type": 2},
    {"id": 0x00FB, "text": "\x06I\x05AVinner\x05@!\x04\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01So fjarr, du havst gesamlt twei \x01styk. Mit twei meir styk, \x01du skal gén meir líf energi!\x02", "box_type": 2},
    {"id": 0x00FC, "text": "\x06I\x05AVinner\x05@!\x04\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Du havst gesamlt þri styk!\x01Mit ander del, dín líf \x01energi skal vesen póered op!\x02", "box_type": 2},
    {"id": 0x00FD, "text": "\x06I\x05AVinner\x05@!\x04\x13s\x08Du kreeg ain \x05AHertdel\x05@!\x09\x01Du havst geendet ander Hert\x01Kar! Dín maximum líf\x01energi ist inkrésed!\x02", "box_type": 2},
    {"id": 0x00FE, "text": "Sé für sen ne nur út in \x01opnen, aber ok innan dýpkastelar.\x04De kúrse, þet ist bara unser drém...\x01Du ne have til dó et wenn du\x01ne vollen til...\x07\x00'\x02", "box_type": 0},
    {"id": 0x0100, "text": "\x05DWat ist þet?\x05@\x02", "box_type": 0},
    {"id": 0x0101, "text": "\x1A\x05DSé, sé, \x0F!\x01Du kan séen ned beló þet \x05@web\x05D\x01brukend \x05F¥\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0102, "text": "\x1A\x05DSé an þet vegg! vines\x01gróing auf et geven et ain rúgh\x01surfake... Kannski du kan klimb \x01et, \x0F!\x05@\x02", "box_type": 0},
    {"id": 0x0103, "text": "\x1A\x05DDu kanst opnen ain \x05@dyr\x05D af standing\x01in front de et und pressing \x05C\x9F\x05D.\x05@\x04\x1A\x05DBetalen attençion til wat \x01\x05CAction\x05D \x05CIkon\x05D segt.\x01Det ist \x05Cblá ikon\x05D an topp de\x01 skerm!\x05@\x02", "box_type": 0},
    {"id": 0x0104, "text": "\x1A\x05DSé! Einwat ist hanging op\x01þar! Et sýnt als ain alt \x05@ladder\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0105, "text": "\x1A\x05DHé...\x01Ist ne det sam design det ist\x01auf \x05@Dyr de Tid\x05D?\x05@\x02", "box_type": 0},
    {"id": 0x0106, "text": "\x1A\x05DEt sýnt als det tork var\x01burning ne ok lang ago...\x05@\x02", "box_type": 0},
    {"id": 0x0107, "text": "\x1A\x05DFrá hér auf, wir skal vesen sker\x01dur sum npil pasvísmen!\x01Wenn du nim et sló, kannski du\x01kan snék op auf sum fiendar.\x04\x05@\x1A\x05DBruk \x05@¤ Målning \x05Dtil alwés sé\x01in proper direkçion. Sette dín\x01view so du kan séen ned näst\x01korridor för du turn ain korner.\x04\x05@\x1A\x05DAingång dín view ist sette, halt ned\x01\x05@¤ \x05Dtil \x05@sidestep \x05Dkring korner.\x01Det veg du skal ne vesen surprised\x01af ain fiend wéting in ambuş.\x05@\x02", "box_type": 0},
    {"id": 0x0108, "text": "\x1A\x05DStá ná þesem \x05@blok\x05D und grab\x01halten de et mit \x05C\x9F\x05D. Meðan haltend\x01\x05C\x9F\x05D, du kan puş oder trekken et.\x04\x05@\x1A\x05DWenn du stáest ná \x05@blok\x05D\x01und druk \x05C\x9F\x05D meðan pressing \x05@ª\x05D\x01móti \x05@blok\x05D, du kan klimb\x01auf topp de et.\x04\x05@\x1A\x05DBetalen attençion til wat \x05CAction\x01Ikon \x05D segt!\x05@\x02", "box_type": 0},
    {"id": 0x010C, "text": "\x1A\x05DEftir Du havst inn vatn, wenn\x01du halt ned\x05C \x9F\x05D, du kan dive!\x01Ik bet þar sin sum interesting\x01tingar underwater!\x05@\x02", "box_type": 0},
    {"id": 0x0114, "text": "\x1A\x05DWow! Sé an alle de \x01\x05@Bomb Flowers\x05D!\x05@\x04\x1A\x05DIst þar ein veg du kan sette\x01sen alle fram an aingång?\x05@\x02", "box_type": 0},
    {"id": 0x0115, "text": "\x1A\x05DEt sýnt, dat þar sin manig \x05@lava\x01pits \x05Dkring hér, so watk dín\x01step!\x05@\x02", "box_type": 0},
    {"id": 0x0116, "text": "\x1A\x05DMit det switk auf, moving\x01\x05@platfórm \x05Dgáet higher. Nú du kan\x01snellig rék sekond flúr!\x05@\x02", "box_type": 0},
    {"id": 0x0119, "text": "\x1A\x05DDu aldrei weten wat skal vesen \x01kring korner in þese npil\x01paþs....\x04\x05@\x1A\x05DBruk \x05@¤ Målning \x05Dtil alwés sé\x01in proper direkçion. Þet ist ain\x01useful tekniqe, ist ne et?\x05@\x02", "box_type": 0},
    {"id": 0x011F, "text": "\x1A\x05D\x0F, wat sin du \x01séend an?\x05@\x02", "box_type": 0},
    {"id": 0x0124, "text": "\x1A\x05D Desert Colossuss ansikt...et \x01viss sýnt ond!\x05@\x02", "box_type": 0},
    {"id": 0x0126, "text": "\x1A\x05DIk kan hören andear whispering \x01in þet rúm...\x04\x05@\x1A\"Sé gegn aug de sannheit...\"\x01\x05DÞet ist, wat sei sagen!\x05@\x02", "box_type": 0},
    {"id": 0x0128, "text": "\x1A\x05DHér...Ik kan hören andear\x01whispering in þet rúm...\x05@\x04\x1A\"De wer have \x05Ahélag fít \x05@\x01skold lat wind guide sen.\x01Dan, sei skal vesen led til  \x01skjult paþ.\"\x04\x05DÞet ist, wat sei sagen!\x05@\x02", "box_type": 0},
    {"id": 0x0129, "text": "\x1A\x05DÞet vegg...et segt einwat hér...\x01\x05@\"Danger above...\"\x05D\x01Þet ist, wat et segt.\x05@\x02", "box_type": 0},
    {"id": 0x012A, "text": "\x1A\x05DÞet vegg...et segt einwat hér...\x01\x05@\"Danger beló...\"\x01\x05DÞet ist, wat et segt.\x05@\x02", "box_type": 0},
    {"id": 0x012B, "text": "\x1A\x05D vatn flóing út de þet \x01statue ist flúding hel flúr.\x05@\x02", "box_type": 0},
    {"id": 0x012F, "text": "\x1A\x05DWatch út, \x0F!\x01Electricity ist rennend dur\x01þet \x05Bgrän slimi ting\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0131, "text": "\x1A\x05DWatch út \x0F!\x01Electricity ist rennend dur\x01þet \x05Aröd slimi ting\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0132, "text": "\x1A\x05DWatch út \x0F!\x01Electricity ist rennend dur\x01þet \x05Cblá slimi ting\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0133, "text": "\x1A\x05DÞet \x05@switk\x05D...\x01Et dót ne sé als du kan Drukk\x01et ned mit dín weight alone,\x01\x0F...\x05@\x02", "box_type": 0},
    {"id": 0x0137, "text": "\x1A\x05D \x05Aröd slimi ting \x05Dist gangen! \x01Det mos vesen bekabruk du kut \x01\x05Aröd tél\x05D! Skal det verk mit \x01 ander ainar ok?\x05@\x02", "box_type": 0},
    {"id": 0x0139, "text": "\x1A\x05DÞars ain switk beiond þet \x01vegg!\x05@\x02", "box_type": 0},
    {"id": 0x013A, "text": "\x1A\x05DEt sýnt als þar ist einwat\x01op þar auf topp de platfórm!\x05@\x02", "box_type": 0},
    {"id": 0x013D, "text": "\x1A\x06B\x05DWHAAAT!?\x04\x05@\x1A\x05DSé an alle de \x05@flags\x05D!\x01Kan du figure út welk ainar sin\x01rél?\x05@\x02", "box_type": 0},
    {"id": 0x0140, "text": "\x05D \x05@Stór Deku Trä\x05A \x05Dhavt \x01summoned du!\x01Bitte komen mit mik!\x05@\x02", "box_type": 0},
    {"id": 0x0141, "text": "\x05DK'mon! Vesen brave!\x01lat uns Gáe inn  \x01Stór Deku Trä!\x05@\x02", "box_type": 0},
    {"id": 0x0142, "text": "\x05D Stór Deku Trä vold uns\x01til Gáe til Besoek prinsess an\x01\x05@Hyrule Kastel\x05D.... Şúldn't wir\x01kregen sker?\x05@\x02", "box_type": 0},
    {"id": 0x0143, "text": "\x05D fraua frá hestgarð asked uns\x01til vinden elar \x05@faþer\x05D...Ik wonder var\x01er ist?\x05@\x02", "box_type": 0},
    {"id": 0x0144, "text": "\x05DIk wonder var wir skal vinden  \x01\x05@prinsess \x05Din þet grós alt kastel?\x05@\x02", "box_type": 0},
    {"id": 0x0145, "text": "\x05DWat vold \x05@Saria\x05A \x05Dsagen wenn wir sagde\x01elar wir sin sker til redden Hyrule?\x05@\x02", "box_type": 0},
    {"id": 0x0146, "text": "Impa \x05Dsagde det Andlig Stein\x01de Fyr ist somewhere auf \x05@Dauð\x01Fjall\x05D.\x05@\x02", "box_type": 0},
    {"id": 0x0147, "text": "\x05Dlat uns Gáe innan Dodongos\x01Cavern brukend ain \x05@Bomb Flower\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0148, "text": "\x05DDarunia sagde det ain \x05@Féa\x01\x05Dlives auf topp de Dauðfjall,\x01didn't er?\x05@\x02", "box_type": 0},
    {"id": 0x0149, "text": "\x05DIk wonder wenn \x05@Saria \x05Dwet aniþing\x01om ander Andlig Stein?\x05@\x02", "box_type": 0},
    {"id": 0x014A, "text": "\x05DEt síms \x05@Prinsess Ruto \x05Dsomehó \x05@\x01\x05Dkreeg innan Jabu-Jabus Buk...\x05@\x02", "box_type": 0},
    {"id": 0x014B, "text": "\x05DDu gesamlt þri Andlig\x01Steinar! lat uns Gáe zurück til \x05@Hyrule\x01Kastel\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x014C, "text": "\x05DDe folk auf white hest...\x01sei varen Zelda und Impa, weren't\x01sei? Et lúked als sei warf \x01einwat inn \x05@moat\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x014D, "text": "\x05Dlat uns Gáe brev innan  \x01\x05@Tempel de Tid\x05D.\x05@\x02", "box_type": 0},
    {"id": 0x014E, "text": "\x05DSkold wir believe wat Sheik sagde \x01und Gáe til \x05@Kakariko By\x05D?\x05@\x02", "box_type": 0},
    {"id": 0x0150, "text": "\x05DIk wonder wat sker in \x01skog rétt nú... Ik am worried\x01om \x05@Saria\x05D, ok!\x05@\x02", "box_type": 0},
    {"id": 0x0151, "text": "\x05DDet klúd yfir \x05@Dauðfjall\x05D...\x01þar ist einwat strange om \x01et...\x05@\x02", "box_type": 0},
    {"id": 0x0152, "text": "\x05DAin arktik wind ist blóing frá\x01\x05@Zoras River\x05D...dó du füle et?\x05@\x02", "box_type": 0},
    {"id": 0x0153, "text": "\x05DDe \x05@Járnstívl \x05Dsé als\x01sei weigh ain ton! Wenn du drage\x01de búts, du möge vesen able til\x01walk an bottom de ain sjó.\x05@\x02", "box_type": 0},
    {"id": 0x0154, "text": "\x05Dlat uns sé für einwer wer might\x01weten einwat om ander\x01\x05@Vísmen\x05D!\x05@\x02", "box_type": 0},
    {"id": 0x0155, "text": "\x05DDet monster! Et kom út de  \x01\x05@vel in by\x05D! lat uns Gáe \x01brev út vel!\x05@\x02", "box_type": 0},
    {"id": 0x0156, "text": "\x05DIk wonder wer built \x05@Ande\x05D\x01\x05@Tempel\x05D, und für wat purpose?\x05@\x02", "box_type": 0},
    {"id": 0x0157, "text": "\x05DHave du ever pléed  \x01\x05ENocturne de Skuggs\x05D det Sheik\x01taught du?\x05@\x02", "box_type": 0},
    {"id": 0x0158, "text": "\x05D \x05@desert\x05D...det ist var\x01Ganondorf Ond Kong var born.\x01Wenn wir Gáe þar, wir might vinden\x01einwat...\x05@\x02", "box_type": 0},
    {"id": 0x015A, "text": "\x05DUtruste \x05@Silfrhanskar \x01\x05Dund forsöken til move tingar du \x01kúldn't budge för!\x05@\x02", "box_type": 0},
    {"id": 0x015B, "text": "\x05D ain wer ist wéting für uns an\x01 Tempel de Tid...et konde vesen...\x05@\x02", "box_type": 0},
    {"id": 0x015C, "text": "\x05DWir have til redden Prinsess Zelda\x01frá elar imprisonment in Ganons\x01Kastel!\x05@\x02", "box_type": 0},
    {"id": 0x015F, "text": "\x05D\x0F...\x01Forsöken til halten moving!!\x05@\x02", "box_type": 0},
    {"id": 0x0160, "text": "Ik ne hug talking til du \x01brukend Okarinas magik, aber\x01Ik vold sannlig als til talen til du\x01ansikt-til-ansikt!\x0B\x02", "box_type": 2},
    {"id": 0x0161, "text": "skog ist konnekted til manig \x01setzt! Wenn du kan hören mís sang,\x01du mos vesen somewhere det ist\x01konnekted til skog!\x0B\x02", "box_type": 2},
    {"id": 0x0162, "text": "Ik var so glad til hören det\x01Mr. Darunia loved mís sang so\x01meir!\x04Ik var ok happier til vinden út\x01det et helped du auf dín Quest,\x01\x0F!\x01Tee hí hí!\x0B\x02", "box_type": 2},
    {"id": 0x0163, "text": "Sin du kollekting Andlig\x01Steinar? Du havst ain meir til\x01vinden? Du mén \x05CAndlig \x01Stein de Vatn\x05@, ne du?\x04 Stór Deku Trä aingång sagde mik\x01det \x05CKong Zora, ruler de Zoras \x01Domain, \x05@havt et...\x0B\x02", "box_type": 2},
    {"id": 0x0164, "text": "Sin du kollekting Andlig\x01Steinar? Du havst ain meir til\x01vinden? Du mén \x05AAndlig \x01Stein de Fyr\x05@, ne du?\x04 Stór Deku Trä aingång sagde mik\x01det \x05AMr. Darunia de Gorons\x01\x05@havt et...\x0B\x02", "box_type": 2},
    {"id": 0x0165, "text": "\x0F...\x01Ik ne weten wat et ist...\x01Ik have þet fíling de dréd...\x04 Kastel...\x01Ja, einwat mal ist happening\x01an Kastel!\x0B\x02", "box_type": 2},
    {"id": 0x0166, "text": "Wat? Dín okarina súnds...\x01different somehó... \x01Have du gevesen praktiking ain mengd,\x01\x0F?\x0B\x02", "box_type": 2},
    {"id": 0x0167, "text": "Sin du séend gegn ain tempel?\x01Ain mistisk bird aingång sagde mik...\x04\"\x05DAugar det kan séen dur \x01darkness skal opnen in ain storm.\x05@\"\x01Dó du havst ein idé wat er \x01mént af þet?\x0B\x02", "box_type": 2},
    {"id": 0x0168, "text": "Var sin du, \x0F?\x01Sin du séend gegn ain tempel?\x01Ik aingång hérd ain mistisk bird \x01sagen...\x04\"\x05DGáe, ung mar. Gáe til \x01Desert Goddess mit ain okarina.\x05@\"\x01Dó du havst ein idé wat er\x01möge have mént af þet?\x0B\x02", "box_type": 2},
    {"id": 0x0169, "text": "Dóde du vinden alle tempelar iet?\x0B\x02", "box_type": 2},
    {"id": 0x016A, "text": "Stór! Du sin safe!\x01Ik viss Ik vold hören frá\x01du aftur!\x04Ik am in \x05BSkogtempel\x05@!\x01 skog andear varen kalling\x01für helpen, so Ik ging til brev et\x01út...\x04Aber et ist full de ond monsterar!\x01Helpen mik, \x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016B, "text": "\x0F...\x01An fyrst, Ik didn't vollen til werden \x01 \x05BVísman de Skogs\x05@....\x04Aber Ik am glad nú.\x04Bekabruk Ik am helping du til redden\x01Hyrule, \x0F!\x01Ja, Ik am!\x0B\x02", "box_type": 2},
    {"id": 0x016C, "text": "Wenn alle sex \x05AVísmen\x05@ komen togeþer, \x01wir kan imprison Ganondorf,  \x01Kong de Ond, in Hélag Rike.\x04Aber, in order til maken ain perfekt\x01sél, wir mos \x05Asevenþ \x01Sage\x05@.\x04Einwer du weten mos vesen det\x01Sage, \x0F...\x04Frá nú auf, du mos travel \x01millum past und future til\x01awaken reméning Vísmen!\x04Halten op gut verk,\x01\x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016D, "text": "Wir, Sex Vísmen, sin kanneling\x01unser kraft til du!\x04 destini de Hyrule depends \x01upon du!\x0B\x02", "box_type": 2},
    {"id": 0x0180, "text": "\x1A\x05DIk kan hören ain voike frá\x01somewhere...\x05@\x04\x1A\x05DEt ist séing:\x01\x05@\x06\x11\"Samlen fim silver Rubinar...\"\x02", "box_type": 0},
    {"id": 0x0181, "text": "\x1A\x05DÞet vegg...et ist séing einwat!\x05@\x04\x1A\x05DEt segt:\x01\x05@Wenn du vollen til séen ain ferri til \x01\x06\x1Eander verden, komen hér...\x02", "box_type": 0},
    {"id": 0x0183, "text": "\x1A\x05DWenn du vollen til ride det \x05@boat\x05D, vesen \x01vár! Et sýnt meir alt... Wer\x01wet wenn et might sink?\x05@\x02", "box_type": 0},
    {"id": 0x0184, "text": "\x1A\x05DÞar ist ain \x05@dyr \x05Dyfir hér... Ist \x01þar ein veg til kregen akross?\x05@\x02", "box_type": 0},
    {"id": 0x0186, "text": "\x1A\x05DDet \x05@röd ís\x05D...et ist so weird!\x05@\x02", "box_type": 0},
    {"id": 0x0189, "text": "\x1A\x05DÞet \x05@Blá Fyr\x05D...et dót ne sím\x01natural. Kannski du kan Bruk et für\x01einwat?\x05@\x02", "box_type": 0},
    {"id": 0x018C, "text": "\x1A\x05D \x05@fyrar auf torkes \x05Dsin gangen.\x01Seems als ghosts nám sen \x01bort!\x05@\x02", "box_type": 0},
    {"id": 0x018D, "text": "\x1A\x05DSé, \x0F! Ain \x05@tork\x05D\x01ist lit! Det ist weil\x01du bét ain ghost, ist ne et?!\x05@\x02", "box_type": 0},
    {"id": 0x018F, "text": "\x1A\x05DÞar sin \x05@pilar \x05Dpénted auf  \x01flúr!\x05@\x02", "box_type": 0},
    {"id": 0x0190, "text": "\x1A\x05DÞet \x05@korridor \x05Dist alle twisted!\x05@\x02", "box_type": 0},
    {"id": 0x0191, "text": "\x1A\x05DWatch gegn \x05@skuggar de\x01monsterar \x05Ddet hang frá \x01keiling.\x05@\x02", "box_type": 0},
    {"id": 0x0192, "text": "\x1A\x05DÞars ain \x05@skatt kest\x05D hér.\x05@\x02", "box_type": 0},
    {"id": 0x0194, "text": "\x1A\x05DÞet...þet ist sam \x05@tork\x05D wir\x01sag an entranke til tempel,\x01ist ne et?\x05@\x02", "box_type": 0},
    {"id": 0x0195, "text": "\x1A\x05DÞet \x05@tork\x05D ist lit...det méns...\x05@\x02", "box_type": 0},
    {"id": 0x0197, "text": "\x1A\x05DÞet \x05@switk\x05D ist frozen!\x05@\x02", "box_type": 0},
    {"id": 0x0198, "text": "\x1A\x05D\x0F, watk út!\x01 keiling ist falling ned!\x05@\x02", "box_type": 0},
    {"id": 0x01A3, "text": "\x1A\x05D\x0F, Ik hören \x05@Goron \x01voikes \x05Dned beló.\x05@\x02", "box_type": 0},
    {"id": 0x01A5, "text": "\x1A\x05DDu kan séen ned frá hér...\x01Ist ne det rúm var wir sag\x01\x05@Darunia\x05D?\x05@\x02", "box_type": 0},
    {"id": 0x01A7, "text": "\x1A\x05DÞet \x05@statue\x05D...haven't wir gesehen et\x01somewhere för?\x05@\x02", "box_type": 0},
    {"id": 0x01A9, "text": "\x1A\x05DÞet \x05@switk \x05Dsýnt rusted.\x05@\x02", "box_type": 0},
    {"id": 0x01AB, "text": "\x1A\x05D\x0F! Vesen vár!\x01Ne kregen swallóed af  \x01vortexes!\x05@\x02", "box_type": 0},
    {"id": 0x0200, "text": "\x06\x0FHi! Ik am ain talking dyr!\x02", "box_type": 0},
