    {"id": 0x0206, "text": "Et ist \x1F nú.\x01 \x05AGravedigging Tour\x05@ ist yfir \x01nú!\x04Ik, \x05ADampé\x05@  gravekíper, am\x01in bed!\x04Gáe bort und spelen! Kannski du skal\x01vinden ain ghost!\x02", "box_type": 2},
    {"id": 0x0207, "text": "\x08\x05DGlad Mask Búð\x01\x05@Bitte réd þet sign för du\x01Bruk þet búð.\x09\x04\x08\x05AHú Þet Búð Verkar\x01\x05@Wir ne seljen maskar an þet búð.\x01Wir bara \x05Alend\x05@ sen til du.\x09\x04\x08Du seljen loaned maskar auf dín\x01ón.\x09\x04\x08Du betalen zurück \x05Amonei\x05@ gegn\x01mask, und wir skal lend du ain \x01newer model.\x09\x04\x08Du kan línen maskar du havst\x01alrédi sold aftur; hóever, du \x01kan seljen elk model de mask nur\x01aingång.\x09\x04\x08Bitte forsöken unser búð!\x01\x06\x14--Glad Mask Búð Owner\x09\x02", "box_type": 2},
