    {"id": 0x0213, "text": "\x08Ain mit \x05Aaug de sannheit \x05@skal\x01vesen guided til Ande Tempel af\x01ain inviting ghost.\x09\x02", "box_type": 2},
    {"id": 0x0214, "text": "\x08De wer wiş til opnen paþ\x01slíping an bottom de sjó\x01mos spelen \x05Asang passed ned\x01af Konglig Família\x05@.\x09\x02", "box_type": 2},
    {"id": 0x0215, "text": "\x08De wer wiş til opnen port\x01auf fjarr heights, spelen \x05Asang\x01passed ned af Konglig Família\x05@.\x09\x02", "box_type": 2},
    {"id": 0x0216, "text": "De wer vinden ain \x05AKlein Lykl\x05@ kan\x01advanke til näst rúm. De\x01wer ne kan Gáe home!\x02", "box_type": 2},
