    {"id": 0x021B, "text": "De wer breken inn Konglig \x01Tomb skal vesen obstrukted af \x01\x05Alurkers in dark\x05@.\x02", "box_type": 2},
    {"id": 0x021C, "text": "Hé, du! Ung mar, yfir þar!\x01Sé yfir hér, innan kell!\x0B\x02", "box_type": 0},
