    {"id": 0x021E, "text": "Ó, mís dreng ist aslíp rétt nú.\x01Bitte komen zurück sum ander tid\x01til spelen mit en!\x02", "box_type": 0},
    {"id": 0x021F, "text": "\x08Wenn vatn fills sjó, \x01skjúten gegn morgn ljós.\x09\x02", "box_type": 2},
    {"id": 0x0220, "text": "\x08Wenn du vollen til travel til  \x01future, du skold teruggeven hér \x01mit \x05Ckraft de silver \x05@frá  \x01past.\x09\x02", "box_type": 2},
