    {"id": 0x0336, "text": "\x08\x05EThrust Angrepen Signs!\x01\x05@Til þrust mit dín sverd, Drukk\x01\x05Dª\x05@ móti dín mål meðan \x01\x05D¤ Målning\x05@, dan Drukk \x05B \x05@.\x09\x02", "box_type": 1},
    {"id": 0x0337, "text": "\x08\x05EHol de \"Z\"\x01\x05@lat uns Gáe dur þet klein\x01hol!\x09\x04\x08Stá in front de hol und\x01puş \x05Dª \x05@móti et. Wenn  \x01\x05CAction Ikon \x05@vist \"Enter,\" Drukk\x01\x05C\x9F \x05@til krablen inn hol.\x09\x04\x08Betalen attençion til wat \x05CAction\x01Ikon \x05@ segt!\x09\x02", "box_type": 1},
    {"id": 0x0338, "text": "\x08\x05ECut Grass Mit Dín Sverd\x01\x05@Wenn du bara svingen mit \x05B \x05@, du skal \x01kut horizontalli. Wenn du halten \x05D¤\x05@ als\x05D \x01\x05@du svingen, du skal kut vertikalli.\x09\x02", "box_type": 1},
    {"id": 0x0339, "text": "\x08\x06<\x05DHyrule Kastel\x05@\x01\x067\x05FLon Lon Hestgarð\x05@\x09\x02", "box_type": 1},
    {"id": 0x033A, "text": "\x08\x06\x13Du sin hér: \x05DHyrule Kastel\x05@\x01\x06\x16Þet veg til \x05FLon Lon Hestgarð\x05@\x09\x02", "box_type": 1},
    {"id": 0x033B, "text": "\x08\x06BBara Ahead\x01\x06)\x05CKong Zoras Chamber\x01\x05@\x06\x19Vise proper respekt!\x09\x02", "box_type": 1},
    {"id": 0x033C, "text": "\x08\x06\x19Hobruk de Stór \x05AMido\x05@\x01\x06-Herre de Kokiri\x09\x02", "box_type": 1},
    {"id": 0x033D, "text": "\x08\x06\x04Hobruk de Weten-et-Alle Bróderar\x09\x02", "box_type": 1},
    {"id": 0x033E, "text": "\x08\x067Hobruk de Twins\x09\x02", "box_type": 1},
    {"id": 0x033F, "text": "\x08\x06=\x05ASaria\x05@'s House\x09\x02", "box_type": 1},
    {"id": 0x0340, "text": "\x08\x05EView Punkt mit ¤ Målning\x01\x05@Wenn du havst non objekt til sé\x01an, du kan bara sé forward\x01mit \x05D¤\x05@.\x09\x04\x08Stoppen moving und dan kange \x01direkçion du sin faking, oder \x05Dhalten\x01ned ¤ \x05@gegn ain klein meðan.\x09\x04\x08Þet kan helpen Du havst oriented in\x01 direkçion du vollen til ansikt.\x01Et ist qite konvenient!\x09\x04\x08Wenn \x05Ddu halt ned ¤\x05@, du kan\x01\x05Awalk sidewés\x05@ meðan faking \x01stréght ahéd.\x09\x04\x08\x05AWalking sidewés\x05@ kan vesen ain meir\x01important tekniqe in dýpkastel\x01korridors. Turn kring und forsöken\x01dóend þet rétt nú.\x09\x02", "box_type": 1},
    {"id": 0x0341, "text": "\x08\x05AStepping Steinar in Pond\x01\x05@Wenn du boldli Gáe in direkçion\x01du vollen til jump, du skal lép\x01automatikalli.\x09\x04\x08Wenn du hop kring auf steinar,\x01du skal werden happier!\x09\x02", "box_type": 1},
    {"id": 0x0342, "text": "\x08\x06/\x05ANon Diving Allowed\x01\x05@\x06\x15--Et skal ne dó du ein gut!\x09\x02", "box_type": 1},
    {"id": 0x0343, "text": "\x08\x05ESwitch Målning\x01\x05@wenn du séest ain \x05B©\x05@ ikon above ain \x01objekt, du kan mål et mit \x05D¤\x05@.\x09\x04\x08In ander words, wenn du Drukk \x05D¤\x05@ \x01wenn Du séest \x05B©\x05F \x05@above ain objekt,\x01du kan lok auf til et.\x09\x04\x08Wenn du Drukk \x05D¤\x05@ aftur, lok\x01skal eiþer \x05ALos\x05@ oder et skal\x01transfer til näst objekt mit\x01 \x05B©\x05@ above et.\x09\x04\x08Wenn du havst manig fiendar in\x01dín field de view und du vollen\x01til eskape, Drukk \x05D¤ \x05@meðan haltend\x01zurück auf \x05Dª\x05@ til kankel målning.\x09\x04\x08Du kan mål \x05Asteinar\x05@ näst til\x01þet sign für praktike!\x09\x02", "box_type": 1},
    {"id": 0x0344, "text": "\x08\x06=\x05BSkog Stage\x05@\x09\x04\x08\x06\x14Wir sin wéting til séen dín\x01\x068béutiful ansikt!\x01\x06(Winnen fabulús prisar!\x09\x02", "box_type": 1},
    {"id": 0x0345, "text": "\x08\x06HBesoek \x01\x06\x04\x05AHobruk de Weten-et-Alle Bróderar\x01\x05@\x06\x17til kregen answers til alle dín\x01\x06\"ting-related qesçions!\x09\x02", "box_type": 1},
    {"id": 0x0400, "text": "Þet ist ain \x05AGossip Stein\x05@!\x02", "box_type": 2},
    {"id": 0x0401, "text": "Sei sagen det du kan swim faster\x01af kontinuúsli pressing \x05B \x05@.\x02", "box_type": 2},
    {"id": 0x0402, "text": "Sei sagen det þar ist ain geheimnis \x01nér lone trä welk ist ne\x01fjarr frá river in  \x01norþwest part de Hyrule Field.\x02", "box_type": 2},
    {"id": 0x0403, "text": "Sei sagen det þar ist ain geheimnis\x01auf road det léds til Sjó\x01Hylia.\x02", "box_type": 2},
    {"id": 0x0404, "text": "Sei sagen det Biggorons Sverd ist \x01super şarp und skal aldrei breken.\x02", "box_type": 2},
    {"id": 0x0405, "text": "Sei sagen det Medigoron didn't \x01sannlig denken om es ón size, \x01so es store ist sannlig kramped.\x02", "box_type": 2},
    {"id": 0x0406, "text": "Sei sagen det Malon sette \x01original rekord in obstakle\x01kúrse de Lon Lon Hestgarð.\x02", "box_type": 2},
    {"id": 0x0407, "text": "Sei sagen det Malon de Lon Lon \x01Hestgarð hopes ain knight in şining \x01armor skal komen und swíp elar fram \x01elar fít somedé.\x02", "box_type": 2},
    {"id": 0x0408, "text": "Sei sagen det Ruto, Zora \x01Prinsess wer ist knón für elar \x01selfisk nature, alsar ain kertén \x01dreng...\x02", "box_type": 2},
    {"id": 0x0409, "text": "Sei sagen det pléers wer val\x01 \"HALTEN\" opçion für \"Z \x01MÅLNING\" sin rél \"Zelda\x01pléers!\"\x02", "box_type": 2},
    {"id": 0x040A, "text": "Sei sagen det þar ist ain geheimnis\x01nér ain trä in Kakariko By.\x02", "box_type": 2},
    {"id": 0x040B, "text": "Sei sagen det, kontrari til elar \x01elegant image, Prinsess Zelda de \x01Hyrule Kastel ist, in fakt, ain \x01tomboi!\x02", "box_type": 2},
    {"id": 0x040C, "text": "Sei sagen det Prinsess Zeldas \x01nanni ist aktualli ain de  \x01Sheikah, wer manig þúght hadde \x01died út.\x02", "box_type": 2},
    {"id": 0x040D, "text": "Sei sagen det þar ist ain mar wer\x01kan alwés vesen fand rennend\x01kring in Hyrule Field.\x02", "box_type": 2},
    {"id": 0x040E, "text": "Sei sagen det et ist agénst \x01rules til Bruk glasses an  \x01Skatt Chest Búð in Hyrule\x01Kastel Stad Market.\x02", "box_type": 2},
    {"id": 0x040F, "text": "Sei sagen det Chicken Fraua \x01gáet til Lakeside Laboratory \x01til studi hú til bríd poket-\x01sized Kukkoar.\x02", "box_type": 2},
    {"id": 0x0410, "text": "Sei sagen det Gerudoar sometimes\x01komen til Hyrule Kastel Stad til\x01sé für boifriends.\x02", "box_type": 2},
    {"id": 0x0411, "text": "Sei sagen det þief named \x01Nabooru, wer haunts þet sted, ist\x01ain Gerudo.\x02", "box_type": 2},
    {"id": 0x0412, "text": "Sei sagen det wenn Du havst klose til ain\x01butterfli meðan haltend ain Deku\x01Stav in dín hender, einwat\x01gut skal happen.\x02", "box_type": 2},
    {"id": 0x0413, "text": "Sei sagen det du möge vinden\x01einwat nüv in dýpkastelar det\x01Du havst alrédi finişed.\x02", "box_type": 2},
    {"id": 0x0414, "text": "Sei sagen det Gerudoar worşip \x01Ganondorf nästum als ain god.\x02", "box_type": 2},
    {"id": 0x0415, "text": "Sei sagen det þar ist ain geheimnis \x01kring entranke til Gerudo \x01Valley.\x02", "box_type": 2},
    {"id": 0x0416, "text": "Sei sagen det ól named\x01Kaepora Gaebora ist \x01reinkarnaçion de ain ankient Sage.\x02", "box_type": 2},
    {"id": 0x0417, "text": "Sei sagen det strange ól,\x01Kaepora Gaebora, möge sé grós und\x01tung, aber es karakter ist raþer \x01lighþérted.\x02", "box_type": 2},
    {"id": 0x0418, "text": "Sei sagen det hest\x01Ganondorf rides ist ain solid blak\x01Gerudo stallion.\x02", "box_type": 2},
    {"id": 0x0419, "text": "Sei sagen det Ganondorf ist ne \x01satisfied mit ruling nur \x01Gerudo und målt til konqer alle\x01de Hyrule!\x02", "box_type": 2},
    {"id": 0x041A, "text": "Sei sagen det skatt du\x01kan érn in Gerudos Training\x01Ground ist ne als stór als du\x01vold expekt, given es diffikulti!\x02", "box_type": 2},
    {"id": 0x041B, "text": "Sei sagen det þar ist ain switk \x01det du kan aktivate nur af\x01brukend Drejangrep.\x02", "box_type": 2},
    {"id": 0x041C, "text": "Sei sagen det et ist mulig til vinden\x01ain total de 100 Gyll Skulltulaar\x01þrúghút Hyrule.\x02", "box_type": 2},
    {"id": 0x041D, "text": "Sei sagen det wenn non-Féa\x01folk enter Verloren Skogar, sei\x01werden monsterar!\x02", "box_type": 2},
    {"id": 0x041E, "text": "Sei sagen det klein holar in\x01 grúnd det du kan vinden alle\x01yfir Hyrule maken perfekt bríding\x01grúnd für bugs.\x02", "box_type": 2},
    {"id": 0x041F, "text": "Sei sagen det Kokiri sin \x01alwés follóed af klein féries.\x02", "box_type": 2},
    {"id": 0x0420, "text": "Sei sagen det ain Kokiri havt lét\x01 skog, aber er ist still\x01alive!\x02", "box_type": 2},
    {"id": 0x0600, "text": "\x08\x05AWat ist þet?\x05@\x09\x02", "box_type": 2},
    {"id": 0x0601, "text": "\x08Gohma\x01\x05DEt ist ain de parasitik monsterar\x01innan Deku Trä! Es \x05@aug\x05D ist\x01vulnerable wenn et ist röd!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0602, "text": "\x08Gohma Egg\x01\x05DWenn þet egg hatkes, ain Gohma\x01Larva skal vesen born.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0603, "text": "\x08Gohma Larva\x01\x05DSé út wenn et kregenar Klar til\x01púnke!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0604, "text": "\x08Skulltula\x01\x05DEs mjúk \x05@belli\x05D ist es wék punkt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0605, "text": "\x08Grós Skulltula\x01\x05DEs mjúk \x05@belli\x05D ist es wék punkt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0606, "text": "\x08Tailpasaran\x01\x05DEs \x05@tél \x05Dist es wék punkt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0607, "text": "\x08Deku Baba\x01\x05DTreffen et wenn et lunges an du, und \x01et skal stá upright. Cut et\x01snellig til kregen ain \x05@Deku-Stav\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0608, "text": "\x08Grós Deku Baba\x01\x05DTreffen et wenn et lunges an du, und \x01et skal stá upright. Cut et\x01snellig til kregen ain \x05@Deku-Stav\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0609, "text": "\x08Deku Baba\x01\x05DÞótt et sýnt wiþered, et skal\x01hurt du wenn du túk et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x060A, "text": "\x08Deku Scrub\x01\x05DEt skal hide in grass wenn Du havst\x01klose til et. Bounce nötar et \x01spits zurück an et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x060C, "text": "\x08Kong Dodongo\x01\x05DÞet ist ain huge Dodongo det éts\x01aniþing! Geven et ain şok, und \x01finiş et fram mit dín \x05@sverd\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x060D, "text": "\x08Dodongo\x01\x05DWatch út für es fieri bréþ!\x01Bruk \x05@¤ Målning \x05Dtekniqes!\x05@\x09\x02", "box_type": 2},
    {"id": 0x060E, "text": "\x08Baby Dodongo\x01\x05DWatch út für es léping angrepen!\x01Et skal explode eftir et ist deféted!\x05@\x09\x02", "box_type": 2},
    {"id": 0x060F, "text": "\x08Lizalfos \x01\x05DBruk dín skjold vel und fight \x01mit \x05@¤ Målning \x05Dtekniqes!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0610, "text": "\x08Dinolfos \x01\x05DBruk dín skjold vel und fight \x01mit \x05@¤ Målning \x05Dtekniqes!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0611, "text": "\x08Fyr Keese\x01\x05DZerstöten et för et flies inn\x01du! Wenn du ne, es flames skal\x01burn op dín \x05@Deku-Skjold\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0612, "text": "\x08Keese\x01\x05Dwenn du havst klose til et, bruken \x01\x05@¤ Målning\x05D. Ok wenn et flies\x01bort, du kan still mål et.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0613, "text": "\x08Armos\x01\x05DStoppen es movement und dan\x01zerstöten et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0614, "text": "\x08Barinade\x01\x05DManig parasitik jellifisk swarm\x01kring þet monster. Mål op es\x01bodi, protekted af jellifisk!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0615, "text": "\x08Parasitic Tentacle?\x01\x05DEt síms det npil part ist \x01es wék punkt... Du mos haven ain \x01partikular ting til zerstöten et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0616, "text": "\x08Shabom\x01\x05DWenn du forsöken til kut et, et skal búnke\x01fram dín kling!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0617, "text": "\x08Biri\x01\x05DWenn du túk et, du skal vesen\x01elektrokuted!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0618, "text": "\x08Bari\x01\x05DWenn du túk et, du skal vesen \x01elektrokuted!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0619, "text": "\x08Stinger\x01\x05DZerstöten et för et flies inn du!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061A, "text": "\x08Phantom Ganon\x01\x05DEt ist ain ond ghost de Skog\x01Tempel! Er komt út de ain de\x01 piktures.\x04\x05DAnswer es magik angrepen mit ain\x01angrepen de dín ón!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061B, "text": "\x08Stalfos\x01\x05DLure et klose til du und watk es\x01movement karefulli! Angrepen et wenn \x01et dropar es vakt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061C, "text": "\x08Blá Bubble\x01\x05DVakt agénst es blá flame mit \x01dín \x05@skjold\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061D, "text": "\x08White Bubble\x01\x05DMålen für et wenn et stopt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061E, "text": "\x08Grän Bubble\x01\x05DBruk dín sverd wenn es grän\x01fyr vanişes!\x05@\x09\x02", "box_type": 2},
    {"id": 0x061F, "text": "\x08Skullwalltula\x01\x05DVesen vár ne til túk et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0620, "text": "\x08Gyll Skulltula\x01\x05DÞet ist ok knón als ain Spinder de\x01 Fluk. Wenn du defét et, du skal\x01kregen ain \x05@tegn\x05D als bevis!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0621, "text": "\x08Volvagia\x01\x05DEt ist Herre de Fyr Tempel,\x01revived af Ond Kong. Ik ne\x01weten es wék punkt...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0622, "text": "\x08Flare Dancer\x01\x05DExtinguish es \x05@flaming kloþes \x01\x05Dfyrst...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0623, "text": "\x08Torch Slug\x01\x05DWenn fyr auf es zurück ist\x01extinguişed, et skal rennen bort.\x01Zerstöten et för et relights!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0624, "text": "\x08Röd Bubble\x01\x05DVakt agénst es angrepen mit \x01dín \x05@skjold\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0625, "text": "\x08Morpha\x01\x05DMeister de Vatn Tempel. Et \x01havt absolute kontrol de vatn. Trekken\x01út es \x05@nukleus \x05Dund angrepen et!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0626, "text": "\x08Dark \x0F\x01\x05DConquer dikself!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0627, "text": "\x08Shell Kling\x01\x05DEs \x05@internal muskle \x05Dist es\x05@ \x01\x05Dwék punkt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0628, "text": "\x08Spike\x01\x05DMålen für et wenn et retrakts es\x01spikes!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0629, "text": "\x08Bongo Bongo\x01\x05DHerre de Skugg Tempel, \x01revived frá vel. Sé an et\x01mit \x05@aug de sannheit\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x062A, "text": "\x08Redéd\x01\x05DEs gaze skal paralize du. Wenn et\x01bites du, \x05@tap ein knopp\x05D til  \x01eskape!\x05@\x09\x02", "box_type": 2},
    {"id": 0x062B, "text": "\x1A\x08Phantom Ganon\x01\x05DAngrepen en\x05A \x05@wenn er komt út de\x01ain de piktures\x05D!\x01Watch út gegn fake ain!\x05@\x09\x02", "box_type": 2},
    {"id": 0x062D, "text": "\x08Gibdo\x01\x05DEs gaze skal paralize du. Wenn et\x01bites du, \x05@tap ein knopp\x05D til \x01eskape!\x05@\x09\x02", "box_type": 2},
    {"id": 0x062E, "text": "\x08Dead Hands Hender\x01\x05DWenn et grabs du, \x05@tap ein knopp \x01\x05Dtil eskape!\x05@\x09\x02", "box_type": 2},
    {"id": 0x062F, "text": "\x08Dead Hand\x01\x05DWatch út für es infinite hender!\x01Mål op es hövd!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0630, "text": "\x08Wallmaster\x01\x05DWatch út für es \x05@skugg\x05D auf \x01flúr. Zerstöten et för et gáet\x01zurück op til keiling!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0631, "text": "\x08Floormaster\x01\x05DWenn et splits op, zerstöten alle \x01styk för sei reunite!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0632, "text": "\x08Twinrova Koume\x01\x05DGanondorfs surrogate moþer.\x01Sorceress de Flame. Ela síms\x01vulnerable til \x05@ló temperature\x05D.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0633, "text": "\x08Twinrova Kotake\x01\x05DGanondorfs surrogate moþer.\x01Sorceress de Ís. Ela síms\x01vulnerable til \x05@high temperature\x05D.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0634, "text": "\x08Iron Knuckle\x01\x05DEinwats strange...\x01Þet ist ne ain ordinari fiend!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0635, "text": "\x08Iron Knuckle\x01\x05DWatch út für es ax angrepen! \x01Et hurts ain mengd! Strike wenn et\x01dropar es vakt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0636, "text": "\x08Skull Kind\x01\x05DIst þet wat happens til kinder wer\x01wander inn skog? Et sýnt\x01als er dót ne als voksne.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0637, "text": "\x08Als Als\x01\x05DAin fiend det éts \x05@skjoldar \x05Dund\x01kertén \x05@kloþes\x05D. Beat et snellig\x01til kregen dín gér zurück!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0639, "text": "\x08Beamos\x01\x05DWatch út für es sérking bém!\x01Ik bet et dót ne als \x05@smoke\x05D til \x01kregen in es aug!\x05@\x09\x02", "box_type": 2},
    {"id": 0x063A, "text": "\x08Anubis\x01\x05DEt ist vulnerable til \x05Afyr\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x063B, "text": "\x08Freezzard\x01\x05DWatch út für es frízing\x01bréþ! Zerstöten et kompleteli\x01för et revives.\x05@\x09\x02", "box_type": 2},
    {"id": 0x063D, "text": "\x08Ganondorf Ond Kong\x01\x05DIk have non idé wat es wék\x01punkt ist!\x05@\x09\x02", "box_type": 2},
    {"id": 0x063E, "text": "\x08Ganon\x01\x05DIk sannlig have non idé wat es\x01wék punkt ist!\x05@\x09\x02", "box_type": 2},
    {"id": 0x063F, "text": "\x08Skull Kind\x01\x05DIst þet wat happens til kinder wer\x01kregen verloren in skog? Er might\x01vesen unser friend wenn wir dó einwat...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0640, "text": "\x08Skull Kind\x01\x05DIst þet wat happens til kinder wer\x01kregen verloren in þet skog? Er síms\x01unhappi til have non ansikt...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0641, "text": "\x08Skull Kind\x01\x05DIst þet wat happens til kinder wer\x01kregen verloren in þet skog? Er sýnt\x01satisfied mit es skull ansikt.\x05@\x09\x02", "box_type": 2},
    {"id": 0x0642, "text": "\x08Octorok\x01\x05DBounce zurück roks sei spit\x01an du!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0643, "text": "\x08Poe de graveiard?\x01\x05DWenn du stare an et mit \x05@¤ \x01Målning\x05D, et skal disappér...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0644, "text": "\x08Poe \x01\x05DWenn du stare an et mit \x05@¤ \x01Målning\x05D, et skal disappér...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0645, "text": "\x08Röd Tektite\x01\x05DLock auf til et als et jumps mit \x05@¤\x01Målning\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0646, "text": "\x08Blá Tektite\x01\x05DEt ist hard til bét auf vatn.\x01Lure et onto land!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0647, "text": "\x08Leever\x01\x05DWatch es movements kloseli und\x01lat et Gáe af!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0648, "text": "\x08Peahat\x01\x05DEs wék punkt ist es \x05@rúts\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0649, "text": "\x08Peahat Larva\x01\x05DDefend mit dín \x05@skjold\x05D!\x05@\x09\x02", "box_type": 2},
    {"id": 0x064C, "text": "\x08Wolfos\x01\x05DDrá et klose til du und watk \x01es movement karefulli! Angrepen et \x01wenn et dropar es vakt!\x05@\x09\x02", "box_type": 2},
    {"id": 0x064D, "text": "\x08Mad Scrub\x01\x05Dwenn du havst klose til et, et skal hide \x01in grass...\x05@\x09\x02", "box_type": 2},
    {"id": 0x064E, "text": "\x08Business Scrub\x01\x05Dwenn du havst klose til et, et skal hide \x01in grass...\x05@\x09\x02", "box_type": 2},
    {"id": 0x064F, "text": "\x08Dampés Ghost\x01\x05DDet ist ghost de déd\x01gravekíper! Wenn du kase en,\x01er might geven du es \x05@kípsake\x05D...\x05@\x09\x02", "box_type": 2},
    {"id": 0x0650, "text": "\x08Meg - ain de Poe sisters\x01\x05DWenn ela splits inn multiple images,\x01Du mos haven til figure út welk ain \x01ist \x05@rél ain\x05D. Ist et þet ain?\x05@\x09\x02", "box_type": 2},
    {"id": 0x0651, "text": "\x08Joelle - ain de Poe sisters\x01\x05DMål op elar wenn ela skint!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0652, "text": "\x08Beth - ain de Poe sisters\x01\x05DMål op elar wenn ela skint!\x05@\x09\x02", "box_type": 2},
    {"id": 0x0653, "text": "\x08Amy - ain de Poe sisters\x01\x05DMål op elar wenn ela skint!\x05@\x09\x02", "box_type": 2},
