    {"id": 0x065A, "text": "\x08Grós Poe \x01\x05DÞet Poe skal ne disappér ok\x01wenn du stare an et. Et moves\x01fast despite es size!\x05@\x09\x02", "box_type": 2},
    {"id": 0x065B, "text": "\x08Twinrova\x01\x05DÞet ist kombined form de\x01Kotake und Koume. Turn ser\x01\x05@magik angrepen \x05Dzurück an sen!\x05@\x09\x02", "box_type": 2},
    {"id": 0x065C, "text": "\x08Poe \x01\x05DÞet Poe dót ne disappér ok wenn\x01du stare an et. Et dót ne spúk\x01ésili, dót et...\x05@\x09\x02", "box_type": 2},
