    {"id": 0x1000, "text": "\x1A\x05DDu finalli woke op!\x01Ik am \x05ANavi \x05D Féa!\x05@\x04\x1A\x05D Stór Deku Trä asked\x01mik til vesen dín \x05Apartner \x05Dfrá\x01nú auf! Nice til mít du!\x05@\x02", "box_type": 0},
    {"id": 0x1001, "text": "\x1A\x06\x12Yahoo! Hi, \x0F!\x02", "box_type": 0},
    {"id": 0x1002, "text": "\x1AWow! Ain Féa!!\x04\x1AFinally, ain Féa kom til du,\x01\x0F!\x07\x10\x0F\x02", "box_type": 0},
    {"id": 0x1003, "text": "Ik skal warten für du hér.\x01Kregen sker! Gáe séen Stór \x01Deku Trä!\x02", "box_type": 0},
    {"id": 0x1004, "text": "\x05C\x9F \x05@af stein, pik et op!\x01\x05C\x9F \x05@af stein, pik et op!\x04Mean alt\x05A Mido\x05@...er gemakt mik pik \x01op roks in front de es húse.\x02", "box_type": 0},
    {"id": 0x1005, "text": "\x1AÓ, du havst ain \x05DFéa\x05@ nú?!\x01Det ist stór, \x0F!\x04\x1AWat?\x04\x1ADu havst gevesen kalled af \x01\x05AStór Deku Trä\x05@? Wat ain honor!\x04\x1AEr möge geven du ain spekial gift!\x01Tee hí!\x04\x1ADet ist bekabruk Stór Deku \x01Trä ist unser faþer, skog\x01guardian, und er gav líf til alle \x01de uns Kokiri!\x02", "box_type": 0},
    {"id": 0x1006, "text": "Ik wonder wenn \x05AStór Deku Trä \x05@\x01gav líf til everiþing in \x01skog, Ik mén in addiçion til uns \x01Kokiri?\x02", "box_type": 0},
    {"id": 0x1007, "text": "Hé, lat uns verk auf sum moves!\x04til \x05Ajump sidewés \x05@meðan \x05D¤ \x01Målning\x05@, Drukk \x05C\x9F \x05@als du move\x01rétt oder lét.\x04Til dó ain \x05Abakflip\x05@ meðan \x05D¤ \x01Målning\x05@, Drukk \x05C\x9F \x05@als du move\x01bakwards.\x04Til dó ain \x05Aroll angrepen\x05@ meðan \x05D¤ \x01Målning\x05@, Drukk \x05C\x9F \x05@als du move\x01forward. Meðan du roll, du kan\x01avoid damage.\x04Wenn du havst dín sverd Klar meðan\x01\x05D¤ Målning\x05@, du kan dó ain \x05Ajump \x01angrepen\x05@ af pressing \x05C\x9F\x05@! Ain jump \x01angrepen dót dúble damage!\x04Du kan bruken \x05D¤ Målning \x05@auf \x01\x05Astein\x05@ näst til mik, so lat uns \x01praktike!\x02", "box_type": 0},
    {"id": 0x1008, "text": "\x1ADu sin ne allóed til laten  \x01skog!\x07\x10\x09\x02", "box_type": 0},
    {"id": 0x1009, "text": "Stór Deku Trä sagde det wenn\x01ain Kokiri latenar skogar, er oder \x01ela skal die!\x02", "box_type": 0},
    {"id": 0x100A, "text": "\x1ADet ménie,\x05A Mido\x05@, gemakt mik kut \x01 grass an Sarias húse.\x04\x1AMido sagde Saria er vold dó et so\x01ela vold als en, aber Ik am ain\x01dóend alle verk!\x07\x10\x0B\x02", "box_type": 0},
    {"id": 0x100B, "text": "Du und \x05ASaria\x05@ sin klose friends,\x01so skal du helpen mik kut  \x01grass?\x04Ik skal lat du halten aniþing det \x01du vinden meðan skarp et.\x02", "box_type": 0},
    {"id": 0x100C, "text": "\x1AJa, ja! Det ist hú du Bruk ain\x01\x05DFéa\x05@!\x04\x1AEt ist so stór det du finalli have\x01ain Féa\x05A \x05@partner!\x04\x1AIk skal ték du hú til talen til \x01folk brukend dín Féa!\x07\x10\x0D\x02", "box_type": 0},
    {"id": 0x100D, "text": "Wenn ain Féa flies nér ain mar \x01oder ting, Drukk \x05D¤\x05@ til \x05Asé \x05@in det\x01direkçion.\x04Wenn du bruken \x05D¤ Målning\x05@, du kan \x01talen til folk frá ain distanke, \x01als wir sin dóend nú.\x04Wenn du havst keinwat det du\x01kan mål, du kan Drukk \x05D¤\x05@ bara\x01til \x05Asé forward\x05@.\x01Forsöken et!\x02", "box_type": 0},
    {"id": 0x100E, "text": "\x1AÓ, ain \x05DFéa \x05@finalli kom til du!\x04\x1ANú du havst ain mengd til lérn!\x07\x10\x19\x02", "box_type": 0},
    {"id": 0x100F, "text": "\x1A\x12hkwó! \x08Det ist stór nüvar!\x09\x01Ik am so glad für du!\x04\x1ANú du sin ain true Kokiri,\x01\x0F!\x07\x10\x10\x02", "box_type": 0},
    {"id": 0x1010, "text": "\x1AIst det rétt? \x01 Stór Deku Trä havt \x01summoned du?\x04\x1AEt ist qite ain honor til talen til \x01Stór Deku Trä!\x07\x10\x03\x02", "box_type": 0},
    {"id": 0x1011, "text": "\x1AÓ, du sin léving...\x02", "box_type": 0},
    {"id": 0x1012, "text": "\x1AAber det ist OK, bekabruk wir skal vesen\x01friends forever...\x01skal ne wir?\x02", "box_type": 0},
    {"id": 0x1013, "text": "\x1AIk vollen du til have þet Okarina...\x01Bitte nim gut kare de et.\x02", "box_type": 0},
    {"id": 0x1014, "text": "Wenn du spelen mís Okarina, Ik hope\x01du skal denken de mik und komen\x01zurück til skog til Besoek.\x02", "box_type": 0},
    {"id": 0x1015, "text": "\x1AÓ... Navi...\x01Thou hast teruggav...\x04\x1A\x0F...\x01Welcome...\x04\x1AHlusten karefulli til wat Ik, \x01\x05ADeku Trä\x05@, am om til sagen þí...\x04\x1AThy slumber þese past múns \x01mos have gevesen restless, und\x01full de nightmares...\x04\x1AAls servants de ond gén\x01strengþ, ain vile klimate pervades\x01 land und kauses nightmares\x01til de sensitive til et...\x04\x1AVerily, þú hast felt et...\x04\x1A\x0F... \x01 tid havt komen til test þi\x01kúrage...\x07\x10\x16\x02", "box_type": 0},
    {"id": 0x1016, "text": "Ik have gevesen \x05Averflukt\x05@...\x01Ik mos du til breken fluk\x01mit dín wisdom und kúrage.\x04Dost þú have kúrage enúgh\x01til undertake þet task?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x1017, "text": "\x1ADan enter, brave \x01\x0F, und þú ok, \x01Navi...\x04\x1ANavi Féa...  \x01Thou mos éd \x0F...\x04\x1AUnd \x0F...Wenn \x05DNavi \x01\x05@spéks, bruken \x05F¥ \x05@til hlusten vel \x01til elar words de wisdom...\x02", "box_type": 0},
    {"id": 0x1018, "text": "Perhaps du ne iet have \x01konfidenke in dín abilities...\x01Teruggeven til Kokiri Skog til\x01lérn skills de kombat...\x04Wenn þú art Klar, teruggeven hér \x01und spék mit mik af brukend \x05D¤\x05@...\x02", "box_type": 0},
    {"id": 0x1019, "text": "best setzen til Gáe til lérn\x01sum nüv skills ist in \x05BSkog \x01Training Mid\x05@.\x05B \x05@Et ist auf hill\x01bara above hér.\x02", "box_type": 0},
    {"id": 0x101A, "text": "\x1A\x128\x82\x08Ow-ó-ó!\x09 \x08Forgive mik, meister!\x09\x01Wenn Ik geven du ain klue, skal du lat \x01mik Gáe?\x04\x1A\x128\x80Wenn du jump fram ain high kliff,\x01wenn du halten \x05Dª\x05@ forward, du skal\x01roll auf grúnd wenn du land \x01und skal ne kregen hurt frá fall.\x04\x1A\x128\x80Ik ne kan guarantí et skal\x01verk, þótt, wenn kliff ist sannlig,\x01sannlig high, heh heh!\x04\x1A\x128\x80Vel, forsöken et wenn du sin fíling\x01bold!\x01\x08Wah ha hah!\x09\x0B\x02", "box_type": 0},
    {"id": 0x101B, "text": "Hí hí!\x01Under det mask...sin ne du det\x01Kokiri kind?\x02", "box_type": 0},
    {"id": 0x101C, "text": "Quite ain unusual mask du havst\x01þar. Hí hí! Ik als et! Et möge\x01maken mik sé ain klein bit túgher.\x04Hé, warüm ne du geven et til mik?\x01\x01\x1B\x05BOK\x01Non veg\x05@\x02", "box_type": 0},
    {"id": 0x101D, "text": "Doh! Det ist ok mal für mik...\x02", "box_type": 0},
    {"id": 0x101E, "text": "Yowza! Ik am gonna drage þet \x01alle tid!\x02", "box_type": 0},
    {"id": 0x101F, "text": "\x1A\x12H\x07He bara gav du \x05A10 Rubinar \x05@ für \x01þet 20-Rubin mask! Du verloren \x01monei auf det handel!\x04\x1AGáe zurück til Mask Búð \x01und betalen \x05A20 Rubinar \x05@ gegn \x01mask. differenke skal have til \x01komen út de dín ón poket.\x02", "box_type": 2},
    {"id": 0x1020, "text": "Mís buddies sannlig vollen þet mask!\x01Hí hí hí!\x02", "box_type": 0},
    {"id": 0x1021, "text": "Ó, du sin OK? Du didn't laten \x01 skog eftir alle, dóde du?\x02", "box_type": 0},
    {"id": 0x1022, "text": "Dóde du weten det wenn du halten \x05D©\x01\x05@forward wenn du jump fram ain kliff,\x01du skal roll wenn du land. Þet skal\x01absorb şok de dín landing.\x04Wenn du fall ok fjarr, þótt, du skal\x01still kregen hurt...\x02", "box_type": 0},
    {"id": 0x1023, "text": "Saria sagde elas wéting an \x01usual spot.\x02", "box_type": 0},
    {"id": 0x1024, "text": "\x1AVel ferdig, \x0F...\x02", "box_type": 0},
    {"id": 0x1025, "text": "Du havst ain kúl Slinga, huh?\x04Du weten wat ist kúl om et?\x01kanst Du målen meðan haltend ned\x01\x05F¡\x05@ und skjúten af losend \x01knopp! Hú kúl!\x04Wenn du havst Slinga Klar,\x01du kan bruken \x05D¤ Målning\x05@ til  \x01\x05Askjúten meðan moving\x05@.... Dóde du \x01weten det?\x02", "box_type": 0},
    {"id": 0x1026, "text": "Non, \x0F...\x01Thou mos weten mís tid ist şort...\x02", "box_type": 0},
    {"id": 0x1027, "text": "\x1ANú...hlusten karefulli...\x01Ain \x05Awiked mar de desert\x05@ \x01kasten þet drédful fluk upon mik...\x02", "box_type": 0},
    {"id": 0x1028, "text": "Wenn du sin séend für Saria, elas\x01in \x05BVerloren Skogar\x05@, als usual.\x04Ne sagen mik du ne weten \x01var det ist! entranke ist op\x01auf kliff overlúking  \x01by!\x04Ik weten du skal kregen verloren! Ne \x01sorg, du skal bara end op zurück an\x01 entranke!\x04\x06Q\x08Harumph!\x09\x02", "box_type": 0},
    {"id": 0x1029, "text": "\x1AThou mos aldrei alló desert \x01mar in blak armor til lé es \x01hender auf hélag Triforce...\x04\x1AThou mos aldrei suffer det mar,\x01mit es ond hert, til enter  \x01Hélag Rike\x05A \x05@de legend...\x04\x1ADet ond mar wer kasten dauð \x01fluk upon mik und sapped mís \x01kraft...\x04\x1ABekabruk de det fluk, mís end ist\x01nigh...\x04\x1AÞótt dín valiant efforts til \x01breken fluk varen sukkessful, \x01Ik var dúmed för du started...\x04\x1AJa, Ik skal pasar bort sún...\x01\x1AAber ne grieve für mik...\x04\x1AIk have gevesen able til sagen du de \x01þese important matters...\x04\x1AÞet ist Hyrules final hope...\x02", "box_type": 0},
    {"id": 0x102A, "text": "\x1A future depends upon þí,\x01\x0F...\x01Thou art kúrageús...\x04\x1ANavi Féa...\x01Helpen \x0F til tragen út \x01mís skal...\x04\x1A\x14\x02Ik entrét ie... Navi...\x14\x00\x01\x14\x03Gut...farvel...\x14\x00\x02", "box_type": 0},
    {"id": 0x102B, "text": "\x1A\x05Dlat uns Gáe til Hyrule Kastel,\x01\x0F!!\x05@\x02", "box_type": 0},
    {"id": 0x102C, "text": "\x1A\x14\x01\x05DGut-farvel...\x05@\x14\x00\x05DStór Deku Trä...\x05@\x02", "box_type": 0},
    {"id": 0x102D, "text": "Ok mal...Heh heh!\x02", "box_type": 0},
    {"id": 0x102E, "text": "Vilt Du spelen sum meir?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x102F, "text": "\x1AHé du! \"\x05DMr. Non Féa\x05@!\"\x01Wat ist dín business mit \x01Stór Deku Trä?\x04\x1AÓne ain Féa, du sin ne\x01ok ain rél mar!\x07\x10Ð\x02", "box_type": 0},
    {"id": 0x1030, "text": "Wenn du vollen til pasar dur hér,\x01du skold an lést \x05Cutruste\x05@ ain \x05Bsverd\x05A\x01\x05@und \x05Dskjold\x05@!\x04\x06Q\x08Sheesh!\x09\x02", "box_type": 0},
    {"id": 0x1031, "text": "\x06W\x08Wat?!\x09\x04\x1A\x05AMido \x05@skal ne lat du Gáe til séen \x01 Stór Deku Trä?\x07\x10È\x02", "box_type": 0},
    {"id": 0x1032, "text": "Du kan Kaup ain \x05Dskjold\x05@ an búð,\x01aber þar ist nur ain \x05Bsverd\x05@\x01skjult somewhere in skog.\x02", "box_type": 0},
    {"id": 0x1033, "text": "\x1AWenn du vollen til séen  \x01Stór Deku Trä, du skold an \x01lést utruste ain \x05Bsverd\x05@ und \x05Dskjold\x05@!\x07\x10Ò\x02", "box_type": 0},
    {"id": 0x1034, "text": "Ik, stór Mido,\x05A \x05@skal aldrei \x01akkept du als ain de uns!\x04Skjúten! Hú dóde Du havst til vesen \x01favorite de Saria und Stór\x01Deku Trä? Huh?!\x01Grumble...grumble...\x02", "box_type": 0},
    {"id": 0x1035, "text": "Ik kan ték du om \x05Aikonar\x01\x05@an topp de skerm.\x01\x1B\x05BOm ielló ikonar\x01Om blá ikon\x05@\x02", "box_type": 0},
    {"id": 0x1036, "text": "þri ielló ikonar in  \x01upper rétt sin kalled \x05F¡ ikonar\x05@.\x04Sei displé tingar du kan\x01Bruk mit \x05F§\x05@,\x05F ¦ \x05@und\x05F \x01¨ \x05@knoppar.\x04Aingång Du havst ain \x05F¡ Knopp ting\x05@, \x01Gáe inn \x05FValting Underskerm\x05@ \x01und sette et til ain de þri\x01\x05F¡ Knoppar\x05@.\x02", "box_type": 0},
    {"id": 0x1037, "text": "blá ikon an topp de \x01skerm ist kalled \x05CAction Ikon\x05@.\x04Þet Action Ikon vist du \x01wat akçion du skal perform\x01wenn du Drukk \x05C\x9F\x05@.\x04Stoppen in manig spots til séen \x01different tingar du kan dó.\x02", "box_type": 0},
    {"id": 0x1038, "text": "Wenn du vollen til lérn om \x01\x05Akart \x05@und \x05Atingar\x05@, bara ask mik.\x01Aber ne ask unless du vollen\x01til hören ain lang explanaçion.\x04Wat Vilt Du weten om?\x01\x1C\x05BOm kart \x01Om tingar\x01Ne ask\x05@\x02", "box_type": 0},
    {"id": 0x1039, "text": "Þar ist ain \x05Akart\x05@ gevist an \x01bottom rétt de skerm.\x04 \x05Fielló pil \x05@vist dín \x01kurrent posiçion und direkçion du\x01sin faking. \x05Aröd mark \x05@vist\x01var du entered sted frá.\x04Du kan turn kart displé auf\x01und fram mit \x05D¢\x05@.\x04Wenn du vollen til séen namn de ain\x01setzen, Drukk \x05ABEGINNEN\x05@.\x04Du skal kregen inn Underskermar.\x01Val \x05AKart Underskerm\x05@.\x04Auf Kart Underskerm, du kan \x01séen ain kart de Hyrule.\x01Dóde Du havst alle det?\x02", "box_type": 0},
    {"id": 0x103A, "text": "Þar sin þri kindar de tingar:\x01\x05CEquipment tingar\x05@, \x05F¡ Knopp tingar\x05@\x01und \x05DQuest tingar\x05@.\x04\x05CEquipment tingar\x05@ sin tingar als \x01 sverd, skjold und kloþes \x01det sin effektive wenn du utruste\x01sen.\x04\x05F¡ Knopp tingar\x05@ kan vesen sette til \x01\x05F§\x05@, \x05F¦\x05@, und \x05F¨\x05@, und\x01brukte af pressing de knoppar.\x04\x05DQuest tingar \x05@sin tingar du \x01samlen during dín adventure. Du\x01bara tragen sen kring.\x04Wenn du vollen til kange eqipment\x01oder bara brev auf dín inventori,\x01Drukk \x05ABEGINNEN\x05@. \x01Du skal kregen inn Underskermar.\x04Switch til ain de fér \x01different Underskermar mit \x05D¤\x05@ oder\x01\x05D£ \x05@und kange oder brev tingar als\x01du bitte. Nim ain sé kring!\x04Wenn du dekide til utruste ain \x01\x05CEquipment ting\x05@, Drukk \x05C\x9F\x05@. Für\x01\x05F¡ Knopp tingar\x05@, Drukk \x05F§\x05@,\x01\x05F¦ \x05@oder \x05F¨\x05@.\x04Det var ain pretti lang explanaçion.\x01Dóde du understand everiþing?\x02", "box_type": 0},
    {"id": 0x103B, "text": "Vel, bara erinnern þet. Wenn du\x01vollen til \x05Bredden\x05@, Drukk \x05ABEGINNEN \x05@til kregen\x01inn Underskermar, dan Drukk\x01\x05B \x05@.\x02", "box_type": 0},
    {"id": 0x103C, "text": "Mís sister nám sum Rubinar und \x01ging şopping an store\x01det havt ain röd rúf.\x01Tee hí!\x04Speaking de \x05ARubinar\x05@, ain \x05Bgrän \x05@ain\x01ist worþ ain, ain \x05Cblá\x05@ ain ist worþ\x01fim und ain \x05Aröd\x05@ ain ist worþ \x01twentig. Hí hí!\x02", "box_type": 0},
    {"id": 0x103D, "text": "Þet búð...Et seljt tingar du\x01kan kregen in skog für frí!\x01Tee hí!\x04Dó du weten hú til Bruk  \x01\x05ADeku-Skjold\x05@? Tee hí!\x04wenn du havst skjold, Drukk\x01\x05ABEGINNEN \x05@til kregen inn Underskermar.\x01Val \x05CUtrust Underskerm\x01\x05@mit \x05D¤\x05@ oder \x05D£\x05@.\x04Auf \x05CUtrust Underskerm\x05@, \x01kúse ting du vollen til utruste\x01und druk \x05C\x9F\x05@ til utruste det ting.\x04Aingång du utruste et, halten et op\x01mit \x05D£\x05@ und kange es angle\x01mit \x05Dª\x05@. Tee hí!\x02", "box_type": 0},
    {"id": 0x103E, "text": "Vilt Du weten hú til bruken\x01 \x05F¥ Knopp\x05@?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x103F, "text": "Wenn du Drukk \x05F¥\x05@, du kan\x01kange dín view.\x04In ain setzen als þet, et skal switk\x01til ain topp-ned view. Outdoors, in\x01ain field für example, et skal switk\x01til ain fyrst-mar perspektive.\x04Ok, wenn \"\x05FNavi\x05@\" ist gevist in\x01 upper rétt de dín skerm, \x01Navi Féa vilt til talen til\x01du. Bruken \x05F¥\x05@ til hlusten til elar!\x02", "box_type": 0},
    {"id": 0x1040, "text": "Vel, wenn du spelen kring mit et, \x01du skal figure et út.\x02", "box_type": 0},
    {"id": 0x1041, "text": "Det ist ne qite Sarias Sang...\x02", "box_type": 0},
    {"id": 0x1042, "text": "Mido\x05A \x05@ist meir upset!\x01Dóde einwat happen til en?\x02", "box_type": 0},
    {"id": 0x1043, "text": "Wat? Var sin du sker?!\x04Til kastel?\x01Var ist kastel?\x02", "box_type": 0},
    {"id": 0x1044, "text": "Wir Kokiri skal die wenn wir laten \x01skog!\x04Du sin ne sker til forsöken til laten\x01 skog, sin du?!\x02", "box_type": 0},
    {"id": 0x1045, "text": "\x1AHé, \x0F!\x01Wat dóde du dó?!\x04\x1A Stór Deku Trä...dóde er...\x01die?\x04\x1AHú konde du dó ain ting als \x01det?! Et ist alle dín fault!!\x0B\x02", "box_type": 0},
    {"id": 0x1046, "text": "\x08Hé!!\x09\x01Wat sin du dóend in mís húse?!\x02", "box_type": 0},
    {"id": 0x1047, "text": "\x1A\x0F, du sin safe!\x07\x10H\x02", "box_type": 0},
    {"id": 0x1048, "text": "Saria und \x0F skal vesen\x01friends forever.\x02", "box_type": 0},
    {"id": 0x1049, "text": "Dóde einwat happen til  \x01Stór Deku Trä?\x02", "box_type": 0},
    {"id": 0x104A, "text": "Somehow, et síms det ér in\x01 skog havt kanged.\x02", "box_type": 0},
    {"id": 0x104B, "text": "\x0F, sin du sker\x01til Gáe bort?\x02", "box_type": 0},
    {"id": 0x104C, "text": "Wenn du lose dín skjold, skal\x01du komen zurück?\x02", "box_type": 0},
    {"id": 0x104D, "text": "\x128\x80Alle de ung Deku Scrub\x01bróderar agrí...du sé exaktli \x01als unser hélag skog totem!\x04\x128\x80Als ain útering frá uns, bitte\x01akkept þese \x05ADeku-Stavar\x05@.\x01Wir skal ok enhanke dín\x01karriing skills!\x04Abracadabra!\x04\x128\x80Alakazaaaam!\x0B\x02", "box_type": 0},
    {"id": 0x104E, "text": "Weil Stór Deku Trä\x01wiþered...meir ménies have \x01gevesen appéring in skog...\x01Ik am skared!\x02", "box_type": 0},
    {"id": 0x104F, "text": "\x1AAin ond wind ist blóing frá  \x01direkçion de Skogtempel.\x04\x1A\x05ASaria\x05@ lét, séing,\x01\"Ik have til dó einwat\x01om et!\"\x07\x10P\x02", "box_type": 0},
    {"id": 0x1050, "text": "\x05BSkogtempel \x05@ist lokated \x01in Hélag Skog Meadow in\x01 fjarr side de Verloren Skogar.\x02", "box_type": 0},
    {"id": 0x1051, "text": "Saria ging til tempel und \x01hasn't komen zurück...\x02", "box_type": 0},
    {"id": 0x1052, "text": "Hi, mister! Du ne kan Bruk ain\x01Deku-Skjold! Et ist nur für\x01kinder!\x02", "box_type": 0},
    {"id": 0x1053, "text": "Vars Saria? \x01Dó du weten Saria, mister?\x01Det ist weird...\x07\x10T\x02", "box_type": 0},
    {"id": 0x1054, "text": "Var havt \x05AMido\x05@ gangen during suk\x01ain emergenki?\x02", "box_type": 0},
    {"id": 0x1055, "text": "Ik séen. Du didn't have ein \x01problems entering skog, \x01mister...\x04Dóde ménies út þar boþer\x01du meir? För Stór Deku \x01Trä died, du wúldn't séen tingar\x01als det kring hér....\x07\x10V\x02", "box_type": 0},
    {"id": 0x1056, "text": "Weil et ist dangerús útan, Ik \x01alwés sté innan mís húse. \x01Aber Ik am bored til dauð in hér!\x02", "box_type": 0},
    {"id": 0x1057, "text": "Du kan Kaup \x05Apilar \x05@an ain búð \x01nur wenn du havst ain \x05Aboge\x05@. Have du \x01kreeg ain, mister?\x02", "box_type": 0},
    {"id": 0x1058, "text": "\x1AHave du gevesen travelling kring\x01meir, mister?\x01Have du ever met ain dreng named \x01\x0F?\x04\x1AMido sagde det Stór Deku \x01Trä wiþered bekabruk det dreng\x01dóde einwat wrong til et...\x04\x1ANur Saria defended \x01\x0F--bis ela lét.\x07\x10Y\x02", "box_type": 0},
    {"id": 0x1059, "text": "Kannski wir misförstod....\x02", "box_type": 0},
    {"id": 0x105A, "text": "Haven't Ik gesehen du somewhere\x01för, mister?\x02", "box_type": 0},
    {"id": 0x105B, "text": "\x1AMister, dó du weten ain dreng \x01named \x0F?\x04\x1AEr lét skog und aldrei\x01kom zurück...\x07\x10\\\x02", "box_type": 0},
    {"id": 0x105C, "text": "Ik wonder wenn \x0F skal \x01ever teruggeven?\x02", "box_type": 0},
    {"id": 0x105D, "text": "\x1AEt vold vesen awesome til vesen grós \x01als du, mister! Ik sannlig vollen til\x01vesen grós als du!\x04\x1AIk vollen til vesen grós und strong und \x01bét op Deku Scrubs, aber...\x07\x10^\x02", "box_type": 0},
    {"id": 0x105E, "text": "Wir Kokiri skal ne ever kregen bigger \x01gegn rest de unser lives...\x01Wat ain bummer!\x02", "box_type": 0},
    {"id": 0x105F, "text": "Warüm ist det Féa follóing du \x01kring? Du sin ne ain de uns!\x02", "box_type": 0},
    {"id": 0x1060, "text": "\x1AWat sin du? Þótt du drage \x01Kokirish kloþing, du ne kan\x01fúl mik!\x07\x10a\x02", "box_type": 0},
    {"id": 0x1061, "text": "Ik promised Saria Ik vold aldrei\x01lat anibodi Gáe dur hér.\x02", "box_type": 0},
    {"id": 0x1062, "text": "\x1AHi þar! Ik am \x05ADeku Trä \x01sprút\x05@!\x04\x1ABekabruk du und Saria\x05A \x05@brak \x01fluk auf Skogtempel, Ik \x01kan gró und flúriş!\x04\x1AThanks ain mengd!\x02", "box_type": 0},
    {"id": 0x1063, "text": "\x1AHé, have du gesehen dín alt\x01friends? None de sen rekognized\x01du mit dín grón-op bodi, dóde\x01sei?\x04\x1ADet ist bekabruk \x05BKokiri\x05@ aldrei\x01gró op! Ok eftir sevin ár,\x01þei're still kinder!\x02", "box_type": 0},
    {"id": 0x1064, "text": "\x1ADu mos vesen wondering warüm nur\x01du havst grón op!\x04\x1AVel, als du might have alrédi \x01guessed, du sin ne ain Kokiri!\x01Du sin aktualli ain \x05DHylian\x05@!\x04\x1AIk am glad til finalli revél þet\x01geheimnis til du!\x02", "box_type": 0},
    {"id": 0x1065, "text": "Sum tid ago, för Kong de\x01Hyrule unified þet kúntri, þar\x01var ain fierke war in unser verden.\x0CZone dé, til eskape frá fyrar\x01de war, ain \x05AHylian moþer \x05@und \x01elar \x05Ababi dreng\x05@ entered þet \x01forbidden skog.\x0CZþe moþer var graveli injured...\x01Elar nur koike var til entrust\x01 kild til \x05ADeku Trä\x05@,  \x01guardian ande de skog.\x0CZþe Deku Trä konde sense det\x01þet var ain kild de destini, whose\x01fate vold affekt hel verden,\x01so er nám en inn skog.\x0CZafter moþer passed bort, \x01 babi var résed als ain \x05BKokiri\x05@.\x01Und nú, finalli, dé de \x01destini havt komen!\x0EZ\x02", "box_type": 2},
    {"id": 0x1066, "text": "\x1ADu sin ain \x05DHylian\x05@, und varen\x01alwés búnd til laten þet skog.\x04\x1AUnd nú...\x01Du havst lérned dín ón \x01destini...\x01So du weten wat du mos dó...\x04\x1ADet ist rétt...\x01Du mos redden land de \x01Hyrule!\x04\x1ANú, \x0F, breken  \x01flukar auf alle de Tempelar,\x01und teruggeven péke til Hyrule!!\x02", "box_type": 0},
    {"id": 0x1067, "text": "\x1A\x067Det melodi?!\x04\x1ASaria spelt det sang alle  \x01tid!\x01Du...Dó du weten Saria?\x04\x1ADet sang...\x04\x1ASaria taught det sang nur \x01til elar friends...\x07\x10o\x02", "box_type": 0},
    {"id": 0x1068, "text": "Wenn Ik séen du... \x01Ik ne weten warüm, aber Ik erinnern...\x01en...\x02", "box_type": 0},
    {"id": 0x1069, "text": "\x1AIk have du nú!\x01In þet gap millum dréms und \x01réliti, sún alle det skal remén\x01de du skal vesen dín déd bodi!\x02", "box_type": 2},
    {"id": 0x106A, "text": "\x1ADank dir...\x01Bekabruk de du, Ik konde awaken als\x01ain Sage...\x04\x1AIk am \x05BSaria\x05@.\x01 Vísman de Skogs Tempel...\x02", "box_type": 0},
    {"id": 0x106B, "text": "\x1A\x06(Saria skal alwés vesen...\x01\x06<dín friend...\x0EP\x02", "box_type": 5},
    {"id": 0x106C, "text": "\x1A fló de tid ist alwés kruel...\x01Es spíd síms different für\x01elk mar, aber non ain kan \x01kange et...\x04\x1AAin ting det dót ne kange mit\x01tid ist ain memori de iúnger dés...\x04\x1AIn order til komen zurück hér aftur,\x01spelen \x05BMinuet de Skogs\x05@.\x02", "box_type": 0},
    {"id": 0x106D, "text": "\x1A\x0F...\x01Ik skal séen du aftur...\x02", "box_type": 0},
    {"id": 0x106E, "text": "Saria hasn't komen zurück iet...\x01Aber Ik weten şe'll teruggeven somedé...\x02", "box_type": 0},
    {"id": 0x106F, "text": "\x1AOK...\x01Ik trust du.\x07\x10h\x02", "box_type": 0},
    {"id": 0x1070, "text": "\x1AÓ...Ik séen...\x04\x1ASaria skal ne ever komen zurück...\x04\x1AAber...Ik...Ik gemakt ain promise til \x01Saria...\x04\x1AWenn \x0F kom zurück, Ik \x01vold vesen viss til sagen en det \x01Saria hadde gevesen wéting für en...\x04\x1AWeil \x14\x03Saria...sannlig...\x01liked...\x14\x00\x07\x10q\x02", "box_type": 0},
    {"id": 0x1071, "text": "\x06KHé, du.\x04wenn du séest en somewhere, bitte\x01lat en weten...\x07\x10Ö\x02", "box_type": 0},
    {"id": 0x1072, "text": "Teach mik sum fanki fenking!\x01Alle Ik have ever ferdig ist tap \x05B  \x05@alle\x01mís líf!\x02", "box_type": 0},
    {"id": 0x1073, "text": "Ik still denken du sannlig sé als\x01einwer Ik have gesehen för, mister.\x02", "box_type": 0},
    {"id": 0x1074, "text": "Du sin suk ain grós, strong mar!\x01Ik sannlig vollen til vesen als du \x01somedé ok þótt Ik skal alwés vesen\x01klein.\x02", "box_type": 0},
    {"id": 0x1075, "text": "\x0F... Ik wonder wenn er \x01skal komen zurück...\x02", "box_type": 0},
    {"id": 0x1076, "text": "Ik füle als Ik have knón du gegn ain\x01lang tid, mister!\x02", "box_type": 0},
    {"id": 0x1077, "text": "Nú det \x05ADeku Träs sprút\x05@\x01ist gróing in Stór Deku \x01Träs médó, skog havt\x01teruggav til normal!\x02", "box_type": 0},
    {"id": 0x1078, "text": "Wir skal alle verk togeþer til protekt\x01 skog!\x02", "box_type": 0},
    {"id": 0x1079, "text": "Somehow, ain fér wind havt begun\x01til bló rekentli.\x02", "box_type": 0},
    {"id": 0x107A, "text": "Weil ain fér wind started til \x01bló, Ik am viss \x0F \x01skal komen zurück!\x02", "box_type": 0},
    {"id": 0x107B, "text": "Ik wonder wenn Saria skal komen zurück...\x02", "box_type": 0},
    {"id": 0x107C, "text": "Ik am viss \x0F skal \x01teruggeven somedé!\x02", "box_type": 0},
    {"id": 0x107D, "text": "\x1A\x06.\x05DStór Deku Trä...\x01\x05@\x06H\x05DIk am zurück!\x05@\x02", "box_type": 0},
    {"id": 0x107E, "text": "\x1AÞet ond mar késelessli brukt\x01es vile, sorkerús kraftar in es\x01sérk gegn Hélag Rike det\x01ist konnekted til Hyrule...\x04\x1Afür et ist in det Hélag Rike \x01det ain skal vinden divine\x01relik, \x05DTriforce\x05@, welk konténs \x01 essenke de gods...\x02", "box_type": 2},
    {"id": 0x107F, "text": "\x08\x06\x06För tid began, för andear\x01\x061und líf existed...\x09\x0EP\x02", "box_type": 4},
    {"id": 0x1080, "text": "\x08\x06\x02Þri golden goddesses deskended\x01\x06\x04upon kaos det var Hyrule...\x09\x0Ek\x02", "box_type": 4},
    {"id": 0x1081, "text": "\x08\x06\x13Din, goddess de kraft...\x09\x0E<\x02", "box_type": 4},
    {"id": 0x1082, "text": "\x08\x06\x09Nayru, goddess de wisdom...\x09\x0E<\x02", "box_type": 4},
    {"id": 0x1083, "text": "\x08\x06\x06Farore, goddess de kúrage...\x09\x0E<\x02", "box_type": 4},
    {"id": 0x1084, "text": "\x08\x06SDin...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1085, "text": "\x08\x06\x02Mit elar strong flaming arms, ela\x01\x06\x0Akultivated land und kréted\x01\x06: röd érþ.\x09\x0Ek\x02", "box_type": 4},
    {"id": 0x1086, "text": "\x08\x06LNayru...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1087, "text": "\x08\x06\x03Poured elar wisdom onto érþ\x01\x06\x0Fund gav ande de law til\x01\x06E verden.\x09\x0Ek\x02", "box_type": 4},
    {"id": 0x1088, "text": "\x08\x06KFarore...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1089, "text": "\x08\x06\x09Mit elar rik súl, produked alle\x01\x06\x14líf forms wer vold ufold\x01\x06K law.\x09\x0Ek\x02", "box_type": 4},
    {"id": 0x108A, "text": "\x08\x06\x16 þri stór goddesses,\x01\x06\"ser labors geendet,\x01\x06\x19departed gegn hévens.\x09\x0EZ\x02", "box_type": 4},
    {"id": 0x108B, "text": "\x08\x06\x14Und golden hélag triangles\x01\x06\x07reméned an punkt var \x01\x06\x1Bgoddesses lét verden.\x09\x0EZ\x02", "box_type": 4},
    {"id": 0x108C, "text": "\x08\x06\x08Weil dan, hélag triangles\x01\x06\x0Ehave werden basis de unser\x01\x06.verdens providenke.\x09\x0EZ\x02", "box_type": 4},
    {"id": 0x108D, "text": "\x08\x06\x0FUnd, resting setzen de \x01\x06\x1Ctriangles havt werden \x01\x06;Hélag Rike.\x09\x0Ek\x02", "box_type": 4},
    {"id": 0x108E, "text": "Hé kind, du dóde qite vel...\x01Et sýnt als du möge vesen géning\x01sum slight skill...\x0C<Aber du havst deféted nur mís\x01fantom...\x01Wenn du fight rél mik, et \x01skal ne vesen so ési!\x0C<Wat ain worþless kréçion det \x01ghost var! Ik skal baniş et til\x01 gap millum dimençions!!\x0E<\x02", "box_type": 0},
    {"id": 0x108F, "text": "\x1AIk alwés believed det du vold \x01komen. Bekabruk Ik weten du...\x04\x1ANon...\x0C\x1E\x1ADu ne have til explén\x01et til mik...\x04\x1ABekabruk et ist destini det du \x01und Ik ne kan live in sam verden.\x02", "box_type": 0},
    {"id": 0x1090, "text": "\x1AIk skal sté hér als Skog\x01Sage und helpen du...\x04\x1ANú, bitte nim þet \x01\x05BMedallion\x05@...\x02", "box_type": 0},
    {"id": 0x1091, "text": "\x1AThou hast verili demonstrated \x01þi kúrage...\x04\x1AIk viss det þú wúldst vesen able\x01til tragen út mís wişes...\x02", "box_type": 0},
    {"id": 0x1092, "text": "Nú, Ik have iet meir til sagen ie,\x01wúldst þú hlusten...\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x1093, "text": "\x1A\x0F...\x01Gáe nú til Hyrule Kastel...\x04\x1AÞar, þú skal sureli mít\x01 \x05APrinsess de Destiny\x05@...\x04\x1ANim \x05Aþet stein \x05@mit du.\x01 stein det mar vold so\x01meir, det er kasten fluk auf\x01mik...\x02", "box_type": 0},
    {"id": 0x1094, "text": "\x1AIk\x05A \x05@viss...\x01det du vold laten skog...\x01somedé, \x0F...\x04\x1ABekabruk du sin different frá\x01mik\x05A \x05@und mís friends....\x02", "box_type": 0},
    {"id": 0x1095, "text": "\x1A\x12hd\x05DHello, \x08\x0F\x09!\x01Wake op!\x05@\x04\x1A\x05D\x05A Stór Deku Trä \x05Dvilt\x01til talen til du!\x01\x08\x0F, kregen op!\x09\x05@\x02", "box_type": 0},
    {"id": 0x1096, "text": "\x1A\x12h_\x05DHé! \x08K'mon!\x09\x05@\x04\x1A\x05DKan Hyrules destini sannlig depend\x01auf suk ain lazi dreng?\x05@\x02", "box_type": 0},
    {"id": 0x1097, "text": "Jumping ist sker út de stile nú.\x01Ik am krazi om dóend \x05Abakflips\x05@!\x01\x062Kan du dó ain?\x02", "box_type": 0},
    {"id": 0x1098, "text": "\x1A\x05D \x05AStór Deku Trä \x01\x05Dhavt summoned du!\x01So lat uns kregen sker, rétt nú!\x05@\x02", "box_type": 0},
    {"id": 0x1099, "text": "\x1A\x06KNavi...\x01\x06#Navi, var art þú?\x01\x069Komen hiþer....\x02", "box_type": 5},
    {"id": 0x109A, "text": "\x1AÓ, \x05DNavi Féa\x05@...\x01Hlusten til mís words, words de \x01 \x05ADeku Trä\x05@...\x04\x1ADost þú sense et?\x01 klimate de ond deskending \x01upon þet rike...\x04\x1AMalevolent forkes ok nú sin\x01mustering til angrepen unser land\x01de Hyrule...\x04\x1AFür so lang, \x05AKokiri Skog\x05@, \x01súrke de líf, havt stúd als ain \x01barrier, deterring útsiders und \x01ménténing order de verden...\x04\x1AAber...för þet tremendús ond\x01kraft, ok mís kraft ist als \x01keinwat...\x04\x1AEt síms tid havt komen für \x01 \x05Adreng óne ain Féa \x05@til begin \x01es júrnei...\x04\x1A iúþ whose destini et ist til\x01léd Hyrule til paþ de \x01justike und sannheit...\x04\x1A\x05DNavi\x05@...Gáe nú! Vinden unser ung\x01friend und guide en til mik...\x04\x1AIk ne have meir tid lét.\x04\x1AFlygen, Navi, flygen! fate de \x01skog, né, verden, depends\x01upon þí!\x02", "box_type": 0},
    {"id": 0x109B, "text": "\x1A\x128\x82Bitte forgive mik, meister! Ik skal \x01aldrei dó et aftur! Wenn du spare \x01mik, Ik skal ték du einwat kúl.\x04\x1A\x128\x80Du skal aldrei bét mís bróderar \x01op ahéd unless du puniş sen \x01in proper order.\x04\x1A\x128\x80 order ist...\x14\x05\x05D2 3 1\x05@\x14\x00\x01\x08\x05DTwentig-þri ist number ain!\x05@\x09\x04\x1A\x128\x80Dó du denken Ik am ain trétor?\x0B\x02", "box_type": 0},
    {"id": 0x109C, "text": "\x1A\x128\x82Hú dóde du weten unser geheimnis?!\x01Hú \x08irritating!\x09\x04\x1A\x128\x80Et ist so annoiing det Ik am sker til\x01revél geheimnis de Queen Gohma\x01til du!\x04\x1A\x128\x80In order til administer kúp de\x01grake til Queen Gohma, strike\x01mit dín sverd \x05Ameðan elas \x01stunned\x05@.\x04\x1AÓ, Queenie...\x04\x128\x80\x08Sorry om det!\x09\x0B\x02", "box_type": 0},
    {"id": 0x109D, "text": "In vast, díp skog de Hyrule...\x0C(\x06\x16Lang have Ik served als \x01\x063guardian ande...\x01\x06\x0CIk am knón als Deku Trä...\x0EF\x02", "box_type": 4},
    {"id": 0x109E, "text": "\x06\x0B kinder de skog, \x01\x06\x19Kokiri, live hér mit mik.\x0C<\x06\x0BElk Kokiri havt es oder elar ón\x01\x068guardian Féa.\x0E<\x02", "box_type": 4},
    {"id": 0x109F, "text": "\x06\x0BHowever, þar ist ain dreng\x05A \x05@wer\x01\x06 dót ne have ain Féa...\x0E<\x02", "box_type": 4},
    {"id": 0x10A0, "text": "\x128\x82Ik surrender! darfür, Ik skal seljen \x01du Deku-Nötter!\x01\x05A5 styk 20 Rubinar\x05@ sei sin!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10A1, "text": "\x128\x82Rétt vel! Du winnen! darfür,\x01Ik skal seljen du Deku-Stavar!\x01\x05A1 del 15 Rubinar \x05@sei sin!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10A2, "text": "\x128\x82Rétt vel! Du winnen! darfür für\x01sparing mik, Ik skal seljen du ain \x01Hertdel!\x01\x05A1 del 10 Rubinar \x05@et ist!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10A3, "text": "\x128\x80\x08lat uns maken ain handel!\x01\x01\x1B\x05BOK\x01Non veg\x05@\x09\x02", "box_type": 0},
    {"id": 0x10A4, "text": "\x128\x82\x08IIKES!!\x09\x01Ik am sker home dan!\x02", "box_type": 0},
    {"id": 0x10A5, "text": "\x128\x82Ne enúgh Rubinar! \x01Komen zurück aftur!\x02", "box_type": 0},
    {"id": 0x10A6, "text": "\x128\x82Du ne kan have þet nú!\x01Komen zurück aftur!\x02", "box_type": 0},
    {"id": 0x10A7, "text": "\x128\x80\x08\x06-Dank dir meir meir!\x09\x0B\x02", "box_type": 0},
    {"id": 0x10A8, "text": "\x1AIk have gevesen wéting für du,\x01\x0F!\x04\x1AÞet ist \x05AHélag Skog Meadow\x05@.\x01Et ist\x05A \x05@mís geheimnis setzen!\x01Ik füle...\x04\x1AÞet setzen skal vesen meir \x01important für boþ de uns somedé.\x01Det ist wat Ik füle.\x04\x1AWenn du spelen Okarina hér, du \x01kan talen mit andear in  \x01skog.\x07\x10©\x02", "box_type": 0},
    {"id": 0x10A9, "text": "Vold du als til spelen  \x01Okarina mit mik?\x01\x1B\x05BJa\x01Ne dó et\x05@\x02", "box_type": 0},
    {"id": 0x10AA, "text": "\x1AOK, forsöken til folló along mit \x01melodi Ik skal spelen.\x01Sin du Klar?\x02", "box_type": 0},
    {"id": 0x10AB, "text": "\x1AHuh?!\x01Hú boring!\x01K'mon! Spelen along!\x02", "box_type": 0},
    {"id": 0x10AC, "text": "\x1A\x12hk\x066Stór! Stór!\x04\x1ABitte ne vergessen þet sang!\x01Dó du promise?\x07\x10­\x02", "box_type": 0},
    {"id": 0x10AD, "text": "Wenn du vollen til hören mís voike,\x01spelen \x05BSarias Sang\x05@. Du kan talen \x01mit mik anitime...\x02", "box_type": 0},
    {"id": 0x10AE, "text": "Sin du taking gut kare de \x01mís Okarina?\x02", "box_type": 0},
    {"id": 0x10AF, "text": "\x1A\x128\x80Cool!\x01Du sin stór! Du skored\x01þri perfekt bulls-augar!\x04\x1A\x128\x80Ik have til geven ain nét present\x01til suk ain wonderful mar!\x01Bitte nim et!\x0B\x02", "box_type": 0},
    {"id": 0x10B0, "text": "Mido might weten einwat om\x01Sarias wherébúts.\x04Ik denken Mido ist sulking in ain de \x01 húses kring hér.\x02", "box_type": 0},
    {"id": 0x10B1, "text": "\x06Z\x05D??\x01\x05@\x06\x15\x05DNon response. er ist slíping.\x05@\x02", "box_type": 0},
    {"id": 0x10B2, "text": "\x1ACojiro? Warüm?\x01Normally nur ain nike mar als mik \x01kan tame du...\x04\x1AWelk méns...\x04\x1A\x14\x01Du... \x14\x00Du mos vesen ain nike mar!\x01\x08Mos vesen!\x09\x01\x08Du mos vesen!!\x09\x01Bitte Mr. Nice Mar! Bitte!\x04\x1ADeliver þet stuff til \x05Aalt\x01hag in trank búð \x05@in Kakariko\x01By!\x0B\x02", "box_type": 0},
    {"id": 0x10B3, "text": "Þet skal disappér wenn du nim\x01ok lang, so du gotta Snelt!\x01\x1B\x05BOK\x01Ik ne kan\x05@\x02", "box_type": 0},
    {"id": 0x10B4, "text": "Ó, iéh. \x08Det ist et!\x09\x01Du sin ne ain nike mar eftir alle!!\x01\x08Kregen bort frá mik!\x09\x02", "box_type": 0},
    {"id": 0x10B5, "text": "Saria vold til séen du...\x01Dóde ela vinden du alrédi?\x02", "box_type": 0},
    {"id": 0x10B6, "text": "Snelt op, nike mar!\x01För et disappérs, deliver et\x01til det alt wenk....\x02", "box_type": 0},
    {"id": 0x10B7, "text": "\x1ADet mar ist ne hér animore.\x04\x1AAnybody wer komt inn  \x01skog skal vesen verloren.\x04\x1AAlle skal werden ain Stalfos.\x01Alle, Stalfos.\x01So, er ist ne hér animore.\x01Nur es sag ist lét. Hí hí.\x07\x10¸\x02", "box_type": 0},
    {"id": 0x10B8, "text": "Det medikine ist gemakt de \x01skog sveppar. Geven et zurück!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x10B9, "text": "Heh heh heh.\x01Sin du sker til vesen... ok?\x01Heh heh!\x02", "box_type": 0},
    {"id": 0x10BA, "text": "Wir seljen skjoldar, aber ne sverdar!\x0B\x02", "box_type": 0},
    {"id": 0x10BB, "text": "\x1ADu weten \x05BSarias Sang\x05@! Wir skold\x01vesen friends! Hér, nim þet!\x02", "box_type": 0},
    {"id": 0x10BC, "text": "Hi! Dó du denken mís ansikt ist kind\x01de plén?\x01Et ist bara ne meir unusual...\x02", "box_type": 0},
    {"id": 0x10BD, "text": "lat uns spelen aftur sometime!\x02", "box_type": 0},
    {"id": 0x10BE, "text": "\x1AFollow along mit unser sang auf \x01dín Okarina. Wir skal léd du \x01inn et.\x02", "box_type": 0},
    {"id": 0x10BF, "text": "\x1ADet var qite ain nike sesçion.\x01Als ain tegn de unser friendşip, \x01bitte nim þet.\x02", "box_type": 0},
    {"id": 0x10C0, "text": "\x1AHé, yfir hér!\x01Hú hú!\x0C(\x1A\x0F...Gut til séen du\x01aftur! Hlusten til þet!\x01Hoot hút....\x07\x10Á\x02", "box_type": 0},
    {"id": 0x10C1, "text": "Eftir sker dur Verloren \x01Skogar, du skal komen upon  \x01\x05BHélag Skog Meadow\x05@.\x04Det ist ain hélag setzen var wenig\x01folk have ever walked.\x04Shhhh...Wat ist det?\x01Ik kan hören ain mistisk tune...\x04Du skold hlusten für det tune\x01ok...\x01Hú hú hó!\x0B\x02", "box_type": 0},
    {"id": 0x10C2, "text": "Dó du vollen til hören wat Ik sagde\x01aftur?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x10C3, "text": "\x1AWenn du sin kúrageús, du\x01skal maken et dur skog\x01bara gut...\x04\x1ABara folló dín órar und hlusten\x01til súnds koming frá \x01skog! \x01Hoot hút!\x02", "box_type": 0},
    {"id": 0x10C4, "text": "\x1AHú hú!\x0C(\x1ADóde du lérn ain Okarina sang\x01frá Saria?\x04\x1ADet melodi síms til have sum\x01mistisk kraft.\x04\x1AÞar möge vesen sum ander \x01mistisk sangar als þet det\x01du kan lérn in Hyrule.\x07\x10Å\x02", "box_type": 0},
    {"id": 0x10C5, "text": "Wenn du halten Okarina mit \x05F¡\x05@\x01var ain melodi ist nekessari, ain \x01\x05Amusikal staff \x05@skal skinen.\x04Ik rekommend det du spelen ain sang\x01du weten.\x04Ik ok suggest det du spelen ok\x01wenn ain skore ist ne gevist. \x01Bara als þet:\x01Hú hú hú hút hút hút!\x0B\x02", "box_type": 0},
    {"id": 0x10C6, "text": "Dó du vollen til hören wat Ik\x01sagde aftur?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x10C7, "text": "\x1AMelodies du havst lérned \x01skal vesen rekorded auf \x05DQuest \x01Status Underskerm\x05@. Du skold \x01memorize de melodies.\x02", "box_type": 0},
    {"id": 0x10C8, "text": "\x1AOhh...Det bum! Ik ne weten warüm \x01er ist alwés so mén til alle!\x04\x1AWat er sagde ist true, þótt.\x07\x10É\x02", "box_type": 0},
    {"id": 0x10C9, "text": "\x1A skog...strange tingar have\x01gevesen happening hér lateli...\x04\x1ADu mos haven til vesen Klar für aniþing.\x01Du vold beter vinden ain vápn!\x07\x102\x02", "box_type": 0},
    {"id": 0x10CA, "text": "\x128\x82Rétt vel! Du winnen! darfür,\x01Ik skal seljen du \x05ADeku-Frä\x05@!\x01\x05A30 styk 40 Rubinar\x05@ sei sin!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10CB, "text": "\x128\x82Ik geven op! Wenn du lat mik Gáe,\x01Ik skal seljen du ain \x05ADeku-Skjold\x05@! Et ist\x01\x05A50 Rubinar\x05@!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10CC, "text": "\x128\x82Ik qit! Wenn du lat mik Gáe, Ik skal seljen \x01du sum \x05ABombar\x05@!\x01\x05A5 styk 40 Rubinar\x05@ sei sin!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10CD, "text": "\x128\x82Knock et fram! Laten mik alone, und \x01Ik skal seljen du \x05Apilar\x05@!\x01\x05A30 styk 70 Rubinar\x05@ sei sin!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10CE, "text": "\x128\x82Rétt vel! Du winnen! Wenn du spare \x01mik, Ik skal seljen du ain \x05ARöd Trank\x05@ \x01für \x05A40 Rubinar\x05@!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10CF, "text": "\x128\x82Rétt vel! Du winnen! Spare mik, und\x01Ik skal seljen du ain \x05BGrän Trank\x05@ für \x01\x05A40 Rubinar\x05@!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10D0, "text": "\x1AWat?! Du havst kreeg ain Féa?!\x01Sagen wat? Stór Deku Trä\x01aktualli summoned du?\x07\x10Ñ\x02", "box_type": 0},
    {"id": 0x10D1, "text": "\x1AWhaaaaaaat?!\x04\x1AWarüm vold er summon du und ne \x01 stór \x05AMido\x05@?\x04\x1AÞet ist ne funni...\x04\x1AIk ne believe et!\x01Du sin ne ok fulli eqipped\x01iet!\x04\x1AHú dó du denken du sin sker til \x01helpen Stór Deku Trä óne\x01boþ ain \x05Bsverd\x05A \x05@und \x05Dskjold\x05A \x05@Klar?\x04Wat? Du sin rétt, Ik ne have\x01mís eqipment Klar, aber...\x07\x100\x02", "box_type": 0},
    {"id": 0x10D2, "text": "\x1A\x06-Eh, wat ist det?!\x04\x1AÓ, du havst ain \x05DDeku-Skjold\x05@...\x04\x1AUnd wat ist DET?!\x04\x1AIst det \x05BKokiri-Sverd\x05@?!\x04\x1AGUT GRIEF!!\x07\x10Ó\x02", "box_type": 0},
    {"id": 0x10D3, "text": "\x1AVel, ok mit alle det stuff, \x01ain wimp ist still ain wimp, huh?\x07\x104\x02", "box_type": 0},
    {"id": 0x10D4, "text": "\x128\x82Ik verloren! Nú Ik skal seljen du ain \x05ADeku \x01Stav \x05@für \x05A15 Rubinar\x05@.\x07\x10£\x02", "box_type": 0},
    {"id": 0x10D5, "text": "\x128\x82Ik verloren! Nú Ik skal seljen du \x05ADeku \x01Nötar \x05@wenn du laten mik alone.\x01\x05A5 styk 20 Rubinar \x05@sei sin.\x07\x10£\x02", "box_type": 0},
    {"id": 0x10D6, "text": "Und ok...\x04\x08\x06\x0DIk am sorri für vesend mén til en.\x09\x04\x06ESagen en det, ok.\x02", "box_type": 0},
    {"id": 0x10D7, "text": "Hí hí hí!\x01Du kom alle veg op hér?\x01Du sin ain rél mar!\x07\x10Ø\x02", "box_type": 0},
    {"id": 0x10D8, "text": "Sé! Ist ne þet view pretti?\x01Change dín viewpoint mit \x05F¥\x05@,\x01so du kan sé kring skog\x01mit \x05Dª\x05@.\x02", "box_type": 0},
    {"id": 0x10D9, "text": "Wat dóde du dó til Stór\x01Deku Trä?\x02", "box_type": 0},
    {"id": 0x10DA, "text": "Wenn du vollen til Gáe til Verloren \x01Skogar, du vold beter utruste \x01rétt gér!\x01Hí hí!\x02", "box_type": 0},
    {"id": 0x10DB, "text": "\x128\x82Alle mís ung Deku Scrub bróderar\x01sagen...\x01Du havst ain horrible ansikt!\x04\x128\x82Aber ne sorg! Wir skal belónung\x01du mit manig \x05ADeku-Nötter\x05@.\x04\x128\x82De kúrse, wir skal ok enable \x01du til tragen meir de sen!\x04Abracadabra...\x04\x128\x80Alakazaaaam!!\x0B\x02", "box_type": 0},
    {"id": 0x10DC, "text": "\x128\x82Ik surrender!\x04\x128\x80Til maken dín Quest ésier,\x01Ik kan enable du til pik op meir\x01\x05ADeku-Stavar\x05@!\x01Aber, it'll kosten du \x05A40 Rubinar\x05@!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10DD, "text": "\x128\x82Ik surrender!\x04\x128\x80Til maken dín Quest ésier, Ik kan\x01enable du til pik op meir \x05ADeku\x01Nötar\x05@!\x01Aber, it'll kosten du \x05A40 Rubinar\x05@!\x07\x10£\x02", "box_type": 0},
    {"id": 0x10DE, "text": "\x128\x82So sorri!\x01Du ne kan Kaup det rétt nú!\x02", "box_type": 0},
    {"id": 0x10DF, "text": "Det mar ist ne hér animore.\x04Anybody wer komt inn  \x01skog skal vesen verloren.\x04Alle skal werden ain Stalfos.\x01Alle, Stalfos.\x01So, er ist ne hér animore.\x02", "box_type": 0},
    {"id": 0x2000, "text": "\x1ADank dir meir meir gegn \x01ander dé... Ik haven't ok asked\x01du dín namn iet...\x04\x1A\x14\x02........\x14\x00\x04\x1ASannlig?\x01\x0F!\x04\x1A\x08Det ist wat Ik þúght!\x09\x01Du sin Féa dreng frá \x01skog! Det var ár ago!\x01Dó du erinnern mik?\x04\x1ADu dó? Ik var viss et var du\x01bekabruk Epona erinnerde du!\x04\x1AÓ, Ik have til sagen du om\x01\x05AMr. Ingo\x05@...\x04\x1AEr var afréd det Ond Kong\x01might vinden út det Epona hadde\x01gevesen genomen bort...Et sannlig upset\x01en!\x04\x1AAber ain dé, alle de ain sudden, er\x01ging zurück til vesend ain normal, \x05Anike\x01mar\x05@!\x04\x1ANú mís dad ist koming zurück...Ik\x01ne kan believe et, aber péke ist\x01returning til þet hestgarð!\x04\x1AEt ist alle bekabruk de du! Ik\x01óe du so meir!\x04\x1ADank dir! Dank dir,\x01\x0F!\x02", "box_type": 0},
    {"id": 0x2001, "text": "Hú ist \x05AEpona \x05@dóend?\x04Wenn du spelen \x05AEponas Sang \x05@mit\x01dín Okarina, ela skal sureli\x01komen til du.\x04Bitte komen zurück til hestgarð\x01whenever du vollen til \x05Atrén \x01\x05@Epona!\x02", "box_type": 0},
    {"id": 0x2002, "text": "\x1AEpona\x05A \x05@sýnt stór!\x01Et sýnt als du varen able\x01til tame elar, ok!\x07 \x03\x02", "box_type": 0},
    {"id": 0x2003, "text": "Hú om triing dín skill mit\x01Epona auf ain \x05Aobstakle kúrse\x05@?\x04Ik skal tid du für \x05Atwei laps\x05@.\x01Et ist pretti kallenging. Wenn du\x01miss jumping ain fenke in  \x01proper order, du skal fél.\x04Hú om et?\x01Dó du vollen til forsöken? \x01\x1B\x05Blat uns Gáe\x01Ne dó et\x05@\x02", "box_type": 0},
    {"id": 0x2004, "text": "Vel, dín tid var \x05A\x17\x05@.\x01Du havst til trén harder!\x04Erinnern, du ne mos til \x01akkelerate til jump yfir ló \x01fenkes, aber du dó mos til Gáe\x01fast til jump high fenkes!\x02", "box_type": 0},
    {"id": 0x2005, "text": "\x0F...kan du hören mik?\x01Et ist mik, Zelda...\x0E<\x02", "box_type": 5},
    {"id": 0x2006, "text": "\x12(ßmúúúúú!\x04Wat ain nike sang...\x01Et reminds mik de pasture...\x04Det sang makt mik füle so gut,\x01Ik kan produke ain mengd de mjolk!\x0B\x02", "box_type": 0},
    {"id": 0x2007, "text": "Have sum de mís refreşing und \x01nutritiús mjolk!\x0B\x02", "box_type": 0},
    {"id": 0x2008, "text": "\x0F, wenn du halten\x01þet Okarina in dín hand...\x0C<Ik skal ne vesen kring animore...\x0C<Ik vold til warten für du, aber Ik\x01kúldn't delé ein longer...\x0C<An lést Ik konde laten du  \x01Okarina und \x05Dþet melodi\x05@...\x0E<\x02", "box_type": 2},
    {"id": 0x2009, "text": "\x1ANú, \x0F.\x01Spelen þet melodi in front de \x01altar in Tempel de Tid.\x01Du mos protekt Triforce!\x02", "box_type": 5},
    {"id": 0x200A, "text": "\x1AWha-ha-ha-hah! Dó du denken \x01du sin in disguise, Mr. Held?\x04\x1A\x06WÓ?\x04\x1AIst det ain \"Kee...einwat...\"\x01karakter mask? Ik hérd er ist \x01meir elsklig rekentli?\x04\x1Aer ist mís drengs favorite. Det\x01\"Kee...einwat...\" mask...\x01Wenn du ne hug...\x07 \x0B\x02", "box_type": 0},
    {"id": 0x200B, "text": "Skal du seljen et til mik?\x01\x01\x1B\x05BJa\x01Non veg\x05@\x02", "box_type": 0},
    {"id": 0x200C, "text": "Ik skal ne geven op! Ik have plenti de\x01patienke. Ik have til für þet \x01job! Hah hah hah!\x0B\x02", "box_type": 0},
    {"id": 0x200D, "text": "\x1AMmmm...mumble...mumble...\x01Huh? Yeah, Ik am awake!\x04\x1AWat?\x04\x1AHé, et ist du! Welcome!\x04\x1AAwww... Det var rúgh!\x01Malon ielled an mik gegn ain lang\x01tid!\x04\x1ADu nám kare de uns, so Ik am prúd \x01til geven du þet \x05Amjolk\x05@! Du kan \x01halten flaska für dikself.\x02", "box_type": 0},
    {"id": 0x200E, "text": "\x05Aroad ist klosed \x05@beiond þet\x01punkt!\x01Ne kan du réd sign yfir \x01þar?\x04Eh? Ó, Ik séen. Du sin bara ain kind,\x01und du ne kan réd iet. \x01Ha ha hah!\x02", "box_type": 0},
    {"id": 0x200F, "text": "Ik ne vollen det!\x02", "box_type": 0},
    {"id": 0x2010, "text": "\x1AÓ, þet ist...\x01Þet ist sureli Prinsess Zeldas \x01handwriting! Vel, lat uns séen...\x01Hmmm... OK...\x04\x1A\x06\x06\"\x05EÞet ist \x0F...\x01\x05@\x06\x06\x05EEr ist under mís orders til redden\x01\x05@\x06\x06\x05EHyrule.\x05@\"\x04\x1AWah ha ha ha hah!\x01Wat kind de funni spel havt unser\x01Prinsess komen op mit nú?!\x04\x1AOK, OK, Rétt vel. Du kan Gáe \x01nú... Bara vesen vár, Mr. Held!\x01\x14\x01\x08Wah\x09 \x08hah\x09 \x08ha\x09 \x08ha\x09 \x08hah!\x09\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x2011, "text": "Ó, Mr. Held!\x01Thanks für alle dín hard verk!\x01\x14\x01\x08Wah\x09 \x08ha\x09 \x08ha\x09 \x08hah\x09\x14\x00!!\x02", "box_type": 0},
    {"id": 0x2012, "text": "Wow! Stór!\x01Dín tid var \x05A\x17\x05@!\x01Du und Epona sin ain stór\x01tém!\x02", "box_type": 0},
    {"id": 0x2013, "text": "Ó, det ist ok mal.\x01Wenn du hadde einwat til zetten et in,\x01Ik konde geven sum til du...\x0B\x02", "box_type": 0},
    {"id": 0x2014, "text": "Ik am \x05AIngo\x05@--Mr. Ingo til du.\x01Ik nim kare de þese hestar.\x01Du sin in mís veg, so skram,\x01kind!\x02", "box_type": 0},
    {"id": 0x2015, "text": "\x1AAf veg, Mr. Held...\x04\x1AWenn du sin sker til klimb \x01Dauðfjall, du skold utruste\x01ain \x05Dproper skjold\x05@! Et ist ain aktive\x01volkano, eftir alle!\x04\x1AWenn du Gáe zurück til Hyrule Kastel\x01Stad Market, du skold brev\x01út Bazaar. Sei seljen \x01skjold Du mos haven þar.\x04\x1ASagen 'em Ik sent du und sei\x01skold geven du ain spekial \x01diskúnt!\x04\x1AWenn du denken du sin gut til Gáe\x01alrédi, ne sorg om et.\x04\x1ANú, Ik vold als til ask ain favor de \x01du. Non, Ik ne expekt du til dó\x01et bara bekabruk de stór tip Ik\x01bara gav du! Ik am bara asking!\x04\x1AHave du gevesen til \x05AGlad\x01Mask Búð\x05@ det bara opened in\x01 Hyrule Kastel Stad Market?\x01Alle ist talking om et!\x04\x1AMís klein dreng pesters mik gegn ain \x01elsklig mask, aber Ik ne have\x01tid til Gáe þar...\x04\x1ASo, konde du Gáe und kregen \x01mask für mik näst tid du sin in\x01 Market? Wenn du ne füle als\x01et, det ist OK, aber...\x04\x1AVel, Ik have non koike, þet ist mís \x01job...\x04\x1A\x06K...sigh...\x0B\x02", "box_type": 0},
    {"id": 0x2016, "text": "Ik wiş Ik konde Gáe til \x05Amask\x01búð \x05@in stad til Kaup ain present für\x01mís kind...\x04\x06K...sigh...\x02", "box_type": 0},
    {"id": 0x2017, "text": "Ó non... er ist ne bréþing...\x02", "box_type": 2},
    {"id": 0x2018, "text": "\x0F!?\x02", "box_type": 0},
    {"id": 0x2019, "text": "\x1A\x08\x06)Arrrrgh!\x09 Ik verloren elar!\x02", "box_type": 0},
    {"id": 0x201A, "text": "\x1A\x062Du, yfir þar! \x01\x06<\x08Klein kind!\x09\x02", "box_type": 0},
    {"id": 0x201B, "text": "\x1A\x06:\x14\x0A\x08Heh\x09 \x08heh\x09 \x08heh\x09...\x14\x00\x01\x06\x1CDu vollen ain del de mik?!\x01\x06>Meir funni!\x01\x06*Ik als dín attitude!\x02", "box_type": 0},
    {"id": 0x201C, "text": "\x1A\x08\x06+Pathetic klein fúl!\x09\x01\x06\x14Dó du rélize wer du sin\x01\x069déling mit?!\x02", "box_type": 0},
    {"id": 0x201D, "text": "\x1A\x064Ik am \x05AGanondorf\x05@!\x01\x08\x06\x0AUnd sún, Ik skal rule verden!\x09\x02", "box_type": 0},
    {"id": 0x201E, "text": "\x1A\x06\x0DDu mos have gesehen white\x01\x06\x12hest gallop past bara nú...\x01\x06#Welk veg dóde et Gáe?!\x01\x06=\x08Answer mik!!\x09\x02", "box_type": 0},
    {"id": 0x201F, "text": "Tsk tsk...Wenn dín tid ist\x01op, Ik skal kik du út de hér.\x02", "box_type": 0},
    {"id": 0x2020, "text": "Mís dreng skal vesen meir glad mit \x01þet! Du sannlig sin Mr. Held!\x01Wha ha ha hah!\x0B\x02", "box_type": 0},
    {"id": 0x2021, "text": "\x1A\x12H\x07You sold 10-Rubin mask für \x01\x05A15 Rubinar\x05@. Du érned ain klein\x01profit.\x04\x1Alat uns Gáe til Mask Búð und\x01betalen zurück mask prike de \x01\x05A10 Rubinar \x05@.\x0B\x02", "box_type": 2},
    {"id": 0x2022, "text": "Klein kinder ne kan Gáe auf  \x01\"\x05AHert-Pounding Gravedigging\x01Tour\x05@\" deskribed auf sign.\x04Weil Ik ne kan dó det, Ik am bara \x01imitating Dampé gravekíper \x01alle dé.\x04Aber mit mís söt ansikt, Ik am ne\x01hert-púnding an alle, am Ik?\x02", "box_type": 0},
    {"id": 0x2023, "text": "\x08Gyaah!\x09 Et ist Dampé  \x01gravekíper!\x04\x06W???\x04Ó, et ist bara ain mask. Ik kregen ain \x01different kind de fright frá det\x01mask dan Ik kregen frá Dampé...\x04Skal du geven det mask til mik?\x01\x01\x1B\x05BJa\x01Non veg\x05@\x02", "box_type": 0},
    {"id": 0x2024, "text": "Ik sannlig dó have sum monei, du\x01weten.\x02", "box_type": 0},
    {"id": 0x2025, "text": "Hé! Tids op, ung mar!\x01Du nur betald 10 Rubinar!\x01Du havst pléed kring lang enúgh!\x0B\x02", "box_type": 0},
    {"id": 0x2026, "text": "Mit þet mask, Ik skal vesen bara als \x01Dampé! \x01Hérs mís monei!\x02", "box_type": 0},
    {"id": 0x2027, "text": "\x1A\x12H\x07You sold 30-Rubin mask til ain\x01kind für full prike?! \x01Und er didn't hug péing an alle!\x04\x1Alat uns Gáe zurück til mask búð til\x01betalen \x05A30 Rubinar \x05@gegn mask. \x01Du kan kregen nüv mask \x01model, ok.\x02", "box_type": 2},
    {"id": 0x2028, "text": "Ik am gonna dig und dig! \x01Bara als Dampé!!\x02", "box_type": 0},
    {"id": 0x2029, "text": "In alt tidar, Ik hérd þar varen \x01manig wild rabbits in land \x01de Hyrule. Ne animore, þótt, \x01bekabruk de exkessive jagend.\x04Ik vollen til werden ain rabbit...\x01Hlusten til wind mit \x01de órar, hop akross grúnd\x01mit de legs...\x04Ok wenn Ik kan nur pretend.\x02", "box_type": 0},
    {"id": 0x202A, "text": "Ik bet mit de lang órar du \x01kan hören voikes... \x01Ó, þese sin genuine rabbit\x01órar frá animal de legend!\x07 +\x02", "box_type": 0},
    {"id": 0x202B, "text": "Ik ne kare hú expensive et ist!\x01Bitte seljen et til mik!\x01\x1B\x05BJa\x01Non veg\x05@\x02", "box_type": 0},
    {"id": 0x202C, "text": "Det ist ne answer Ik vold til \x01hören!\x02", "box_type": 0},
    {"id": 0x202D, "text": "Mís lang tid drém! Returning til\x01 wild líf! Finally, aktor, \x01stage und prop have gevesen united!\x0B\x02", "box_type": 0},
    {"id": 0x202E, "text": "\x1A\x12H\x07It's ain 50-Rubin mask, aber er betald\x01du ain krazi amúnt de monei für\x01et--meir monei dan du kan \x01reiknen!\x04\x1AGáe zurück til Mask Búð und \x01betalen zurück bara \x05A50 Rubinar \x05@de þet\x01monei.\x02", "box_type": 2},
    {"id": 0x202F, "text": "\x1A\x06\x0ESo, du denken du kan protekt\x01\x066sen frá mik...\x01\x06(Du havst kreeg Gutar, kind.\x02", "box_type": 0},
    {"id": 0x2030, "text": "\x1AÞar sin sum folk in Kakariko\x01spréding rumors det Ik kéted\x01Talon út de hestgarð, aber...\x04\x1A\x06-Ne vesen \x08ridikulús!\x09\x04\x1ADet mar Talon var wék!\x01Ik, hard-working \x05AIngo\x05@, púred \x01so meir energi inn þet setzen!\x04\x1AIk ne vollen ein strangers als\x01du séing aniþing mal om mik!\x04\x1AHlusten. \x05Astór Ganondorf\x01\x05@rekognized mís obviús talents und\x01gav hestgarð til mik!\x04\x1AIk skal rése ain gut hest und\x01winnen rekogniçion frá stór \x01Ganondorf!\x04\x1ASagen, ung mar, dó du vollen\x01til ride ain de mís gut hestar?\x07 1\x02", "box_type": 0},
    {"id": 0x2031, "text": "Betalen mik \x05A10 Rubinar \x05@und du kan \x01ride.\x01\x1B\x05BRide\x01Ne ride\x05@\x02", "box_type": 0},
    {"id": 0x2032, "text": "Rétt vel dan, skram \x01ia klein skarnmar!\x02", "box_type": 0},
    {"id": 0x2033, "text": "Du ne have enúgh!\x01Redden dín kange und \x01komen zurück aftur!\x02", "box_type": 0},
    {"id": 0x2034, "text": "Dó du vollen til hören hú til ride?\x01\x01\x1B\x05BHlusten\x01Ne hlusten\x05@\x02", "box_type": 0},
    {"id": 0x2035, "text": "Approach hest qietli und \x01stá af es side. Drukk \x05C\x9F\x05@ til  \x01múnt op.\x04Bruk \x05Dª \x05@til maken et rennen. \x01Aingång et begint rennend, Drukk\x01\x05C\x9F\x05@ til tap et mit whip. \x01Et skal spíd op!\x04Wenn du vollen til jump yfir ain\x01fenke, akkelerate und treffen et\x01hövd auf!\x04Wenn du forsöken til jump yfir ain fenke \x01an ain angle, hest skal ne als\x01et, und et skal ne jump.\x04Eftir hest komt til ain \x01enden stoppen, Drukk \x05C\x9F\x05@ til  \x01dismúnt. Nú, have fun!\x0B\x02", "box_type": 0},
    {"id": 0x2036, "text": "Wenn du bruken \x05D¤ Målning\x05@, du kan \x01talen til mik frá horsebak.\x04Sin du Klar til Gáe home so \x01sún?\x01\x1B\x05BNon, Ik vollen til ride.\x01Ja, Ik am ferdig.\x05@\x02", "box_type": 0},
    {"id": 0x2037, "text": "Wenn du vollen til dismúnt, stoppen \x01und druk \x05C\x9F\x05@.\x04Hé ung mar!\x01Dó Ik weten du? Ik bara felt als \x01þótt Ik have gesehen du\x01somewhere för...\x07 6\x02", "box_type": 0},
    {"id": 0x2038, "text": "Du sin getting beter!\x01Hú om ain klein rake mit mik?\x01Ain lap kring korral mit\x01det hest.\x04lat uns maken ain klein wager, sagen\x01\x05A50 Rubinar\x05@?\x01\x1B\x05BDó et\x01Ne dó et\x05@\x02", "box_type": 0},
    {"id": 0x2039, "text": "Hé hé... Wat ist matter?\x01Ne du havst ok 50 Rubinar?!\x01Ik ne vollen til rake mit einwer\x01so púr!\x02", "box_type": 0},
    {"id": 0x203A, "text": "\x1A\x069Sh-\x08şúút!\x09\x04\x1AWenn stór Ganondorf fand út\x01om þet humiliaçion...\x01Hé, du!! Hú om ander\x01rake! Wenn du winnen...\x04\x1ADu kan halten... hest!!\x0B\x02", "box_type": 0},
    {"id": 0x203B, "text": "\x1AWat ist op mit det hest?!\x01Ist det \x05AEpona\x05@?\x04\x1AHú dóde du tame det wild hest\x01rétt under mís nose?!\x04\x1AIk var sker til present det hest\x01til stór Ganondorf... Aber Ik bet\x01et auf rake und verloren! Shooot!\x0B\x02", "box_type": 0},
    {"id": 0x203C, "text": "\x1A\x066Hah ha hah!\x04\x1AAls Ik promised, Ik skal geven  \x01hest til du...\x04\x1A\x06\x0AHowever...\x04\x1AIk skal aldrei lat du laten þet hestgarð!\x0B\x02", "box_type": 0},
    {"id": 0x203D, "text": "Hí hí hí... Ok mal für du!\x01Ik kregen dín 50 Rubinar.\x0B\x02", "box_type": 0},
    {"id": 0x203E, "text": "Wah ha hah!\x01Du sin bara ain kind, eftir alle!\x01Vel, komen zurück ein tid und wir skal\x01have sum meir fun...\x02", "box_type": 0},
    {"id": 0x203F, "text": "\x1AWat? Wat sin du dóend \x01hanging kring hér?\x01Du klein weirdo!\x04\x1AIk am \x05AIngo \x05@und Ik hug hestgarð.\x04\x1AIk have gevesen working an þet hestgarð \x01gegn ain lang tid für det lazi\x01bum, Talon.\x04\x1AToday, für example, er ist gangen\x01somewhere gegn ain deliveri und er \x01hasn't komen zurück iet!\x04\x1ASo, Ik am dóend alle verk kring\x01hér.\x07 @\x02", "box_type": 0},
    {"id": 0x2040, "text": "Ó vel...Et ist túgh til vesen ain\x01working mar.\x02", "box_type": 0},
    {"id": 0x2041, "text": "\x1AHé, dín kloþes! Þei're...\x01different...\x01Du sin ne frá kring hér, \x01sin du?\x04\x1A\x14\x02.........\x14\x00........\x04\x1AOhh... Du sin ain Féa dreng frá \x01 skog! Mís namn ist \x05AMalon\x05@!\x01Mís dad óns Lon Lon Hestgarð!\x07 B\x02", "box_type": 0},
    {"id": 0x2042, "text": "Dad ging til kastel til deliver\x01sum mjolk, und er hasn't komen\x01zurück iet...\x02", "box_type": 0},
    {"id": 0x2043, "text": "\x1ASin du sker til kastel,\x01Féa dreng?\x01Vold du hug vinden mís \x05Adad\x05@?\x04\x1A\x12hmhe mos have fallen aslíp \x01somewhere kring kastel. \x01Wat ain ting gegn ain voksen til dó!\x01Tee hí!\x04\x1AÓ iéh, wenn du skal sé für en, Ik skal \x01geven þet til du.\x04\x1AIk have gevesen inkubating þet\x01egg meir karefulli...\x01Tee hí!\x0B\x02", "box_type": 0},
    {"id": 0x2044, "text": "Sette egg til \x05F¡\x05@ til inkubate et.\x01Hí hí!\x04Mís dad ist sannlig trúblesome,\x01gegn ain voksen, ist ne er?!\x01Hí hí!\x02", "box_type": 0},
    {"id": 0x2045, "text": "\x1AIk ne kan believe det Ik, stór\x01\x05AIngo\x05@, am working auf þet dump de\x01ain hestgarð!\x04\x1ABekabruk óner ist so lazi, Ik\x01alwés have til dó alle verk \x01kring hér!\x07 F\x02", "box_type": 0},
    {"id": 0x2046, "text": "Ik, hard-working \x05AIngo\x05@, skold vesen \x01in karge, ne det lazi bum, \x01Talon!\x02", "box_type": 0},
    {"id": 0x2047, "text": "\x1AÓ, et ist Féa dreng aftur!\x04\x1AIk hérd det Du fand mís dad!\x01Hú dóde du als kastel? Dóde\x01Du séest Prinsess? Hí hí!\x04\x1A\x12hmdad kom home in ain Snelt eftir\x01Du fand en. Hí hí!\x04\x1AÓ iéh, Ik have til introduke du\x01til mís friend, Féa dreng!\x04\x1AElas þet hest. Elar namn ist\x01\x05AEpona\x05@. Ist ne ela söt?\x02", "box_type": 0},
    {"id": 0x2048, "text": "Et síms als Epona ist afréd de \x01du, Féa dreng...\x02", "box_type": 0},
    {"id": 0x2049, "text": "Mís moþer komposed þet sang.  \x01Ist ne et nike? lat uns sing togeþer.\x02", "box_type": 0},
    {"id": 0x204A, "text": "Ó, Epona! Elas grón fond de\x01du, Féa dreng.\x02", "box_type": 0},
    {"id": 0x204B, "text": "\x14\x02Z Z Z Z Z Z Z Z Z Z Z Z Z Z Z\x14\x00...\x02", "box_type": 0},
    {"id": 0x204C, "text": "Ó...ain visitor!\x01Et ist gevesen ain lang tid weil we've\x01hadde ain visitor hér...\x01Var dóde du komen frá?\x04Weil Ganondorf kom, folk in\x01 Kastel Stad have gangen, setzt\x01have gevesen ruined, und monsterar\x01sin wandering allstad.\x04Mr. Ingo ist bara brukend hestgarð\x01til gén Ganondorfs favor...\x04Alle síms til vesen turning ond...\x04Aber Dad...\x01Er var kiked út de hestgarð\x01af Mr. Ingo...\x04Wenn Ik disobei Mr. Ingo, er skal trét\x01 hestar so badli...\x04So...\x01Þars keinwat Ik kan dó...\x02", "box_type": 0},
    {"id": 0x204D, "text": "Ik bet keinwer ist faster dan Ik am \x01nú! Aber, Ik ne weten wenn Ik \x01skold vesen glad oder sad....\x02", "box_type": 0},
    {"id": 0x204E, "text": "\x14\x02Z Z Z Z Z Z Z Z Z Z Z Z Z\x14\x00...\x01S-stoppen det sang...Ik...Ik...\x01Mumble... mumble...\x02", "box_type": 0},
    {"id": 0x204F, "text": "\x1ANim ain gut sé an det \x01fjall. Det ist \x05ADauðfjall\x05@,\x01home de Gorons. Sei halten\x01 Andlig Stein de Fyr.\x02", "box_type": 0},
    {"id": 0x2050, "text": "Bitte halten et geheimnis frá \x01Mr. Ingo det Ik sing þet sang...\x02", "box_type": 0},
    {"id": 0x2051, "text": "\x1ADu...\x01Dó du weten mís \x05Amoþers sang\x05@?\x04\x1AAlle sannlig liked det sang...\x01Mís dad... Ok Mr. Ingo...\x04\x1AAber...weil Ganondorf skén,\x01Mr. Ingo havt kanged kompleteli.\x04\x1AIk kan erinnern gut alt dés\x01nur meðan Ik sing sang. Ok...\x07 R\x02", "box_type": 0},
    {"id": 0x2052, "text": "\x05AEpona\x05@ sannlig liked det sang...\x01Nur Ik konde tame det hest...\x01Ok Mr. Ingo hadde ain hard tid...\x04Hí hí hí!\x02", "box_type": 0},
    {"id": 0x2053, "text": "Þet statues ain-eied gaze \x01pierkes inn dín hug...\x02", "box_type": 2},
    {"id": 0x2054, "text": "Responding til dín mask, þet \x01strange stein statue talt til \x01du...\x04Ik overhérd þet...\x02", "box_type": 2},
    {"id": 0x2055, "text": "Ik am gonna turn yfir ain nüv léf \x01und verk rél hard frá nú auf.\x02", "box_type": 0},
    {"id": 0x2056, "text": "Mr. Ingo... Er mos have gevesen \x01tempted af ond kraftar.\x01er ist ne sannlig ain mal mar \x01an alle...\x02", "box_type": 0},
    {"id": 0x2057, "text": "Z Z Z Z Z Z Z Z...\x01Mumble... Et ist ne ési til\x01vesen ain working mar...\x02", "box_type": 0},
    {"id": 0x2058, "text": "Et ist gevesen ain meðan...\x01Dó du vollen til rake?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2059, "text": "Wenn du kange dín hug,\x01komen zurück anitime!\x02", "box_type": 0},
    {"id": 0x205A, "text": "Rétt vel dan! Scram,\x01ia klein skarnmar!\x0B\x02", "box_type": 0},
    {"id": 0x205B, "text": "Heh heh... Sin du mad weil \x01du verloren? Wenn du sin det upset,\x01hú om ander rake?\x04Bet \x05A50 Rubinar \x05@und rake aftur?\x01\x01\x1B\x05BRace\x01Ne rake\x05@\x02", "box_type": 0},
    {"id": 0x205C, "text": "Dank dir so meir. Heh heh!\x0B\x02", "box_type": 0},
    {"id": 0x205D, "text": "Wenn Ik geven ia meir frí de karge,\x01Ingo skal kregen mad an mik. So Ik vold\x01beter seljen et til du gegn\x01normal prike.\x02", "box_type": 0},
    {"id": 0x205E, "text": "Wanna Kaup mjolk für \x05A30 Rubinar\x05@?\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x205F, "text": "Hi þar, hú sin du?\x01Ik am Ingo. Ik füle so honored\x01til vesen allóed til verk hér.\x02", "box_type": 0},
    {"id": 0x2060, "text": "\x1ADu brave lad...\x01Wir mos protekt þet béutiful\x01land de Hyrule!\x02", "box_type": 0},
    {"id": 0x2061, "text": "\x1AÓ, söt okarina!\x01Sin du sker til spelen þet sang\x01mit det okarina?\x02", "box_type": 0},
    {"id": 0x2062, "text": "\x1AAn fút de Dauðfjall\x01du skal vinden mís by, \x05AKakariko\x05@.\x01Det ist var Ik var born und \x01résed.\x04\x1ADu skold talen til sum de \x01villagers þar för du Gáe op\x01Dauðfjall.\x02", "box_type": 0},
    {"id": 0x2063, "text": "\x1A sang Ik bara taught du havt\x01sum mistisk kraft. Nur \x01Konglig Família members sin allóed\x01til lérn þet sang.\x04\x1AErinnern, et skal helpen til prove\x01dín konnekçion mit Konglig \x01Família.\x04\x1A Prinsess ist wéting für du til \x01teruggeven til kastel mit \x01steinar. Rétt vel. Wir sin reiknend\x01auf du!\x02", "box_type": 0},
    {"id": 0x2064, "text": "\x1A\x08Hú hút!\x09\x01\x0F...\x01Sé op hér!\x0C(\x1AEt skint det tid havt \x01finalli komen für du til beginnen dín \x01adventure!\x04\x1ADu skal enkúnter manig hardşips\x01ahéd... Det ist dín fate. Ne \x01füle diskúraged, ok during \x01túghest tidar!\x07 e\x02", "box_type": 0},
    {"id": 0x2065, "text": "Gáe stréght þet veg und du skal\x01séen \x05AHyrule Kastel\x05@.\x04Du skal mít ain \x05Aprinsess \x05@þar...\x04Wenn du sin verloren und ne weten \x01welk veg til Gáe, sé an  \x01\x05AKart\x05@.\x04 stedar du havst explored skal \x01vesen şón auf Kart. Drukk \x01\x05ABEGINNEN \x05@til enter Underskermar\x01und \x05D¤\x05@ oder \x05D£\x05@ til vinden Kart.\x04Auf \x05AKart Underskerm\x05@, du skal\x01ok séen ain \x05Aflaşing dot\x05@ şóing\x01du welk veg du skold Gáe näst.\x07 f\x02", "box_type": 0},
    {"id": 0x2066, "text": "Dóde Du havst alle det?\x01\x01\x1B\x05BNon\x01Ja\x05@\x02", "box_type": 0},
    {"id": 0x2067, "text": "\x1ARétt vel dan, Ik skal séen du kring!\x01Hoot hút hút hó!\x02", "box_type": 0},
    {"id": 0x2068, "text": "\x1AHé, \x0F! Þet veg!\x0C(\x1A prinsess ist innan kastel \x01bara ahéd. Vesen vár ne til kregen \x01kaught af vaktar!\x01Hó hó hó hút!\x0B\x02", "box_type": 0},
    {"id": 0x2069, "text": "Auf þet grúnd, tid flós \x01normalli.\x04Aber tid stát still meðan du\x01sin in Lon Lon Hestgarð oder in ain stad.\x04Wenn du vollen tid til pasar normalli,\x01du skal mos til laten stad.\x04Vel, vel, welk veg sin du \x01sker til Gáe nú?\x01Hú hú hút!\x0B\x02", "box_type": 0},
    {"id": 0x206A, "text": "Dó du vollen til hören wat Ik sagde \x01aftur?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x206B, "text": "\x1AHoooo. Du sin ain smart kind.\x01Gut Heill, dan. Hú hú.\x02", "box_type": 0},
    {"id": 0x206C, "text": "Hé, \x0F! \x01Warten ain sekond, friend!\x04Beyond þet punkt du skal vinden \x01\x05AKakariko By\x05@. Have du gesehen \x01 Prinsess de Hyrule? Wenn ne, \x01Ik suggest du Gáe til kastel.\x0B\x02", "box_type": 0},
    {"id": 0x206D, "text": "Hé, \x0F! \x01Sé yfir hér!\x0C(\x1ABeyond þet punkt du skal vinden\x01\x05AKakariko By\x05@. Watch dín step!\x01Hoot hú!\x0B\x02", "box_type": 0},
    {"id": 0x206E, "text": "\x1A\x0F, du sin nur\x01ain wer kan enden Quest\x01ahéd!\x01Du mos dó dín best! Hú!\x02", "box_type": 0},
    {"id": 0x206F, "text": "\x0F! Warten op, buddi!\x01Hú hú!\x0C(Hövd súþ frá hér til rék\x01\x05AHylia-Sjós \x05@full, rik vatnar.\x04Wenn du Gáe west, du skal vinden \x01\x05AGerudo Valley\x05@. Þars ain hideút\x01de ain gang de þieves auf ander\x01side de vallei.\x04Vel, du sin frí til Gáe aniwhere\x01du vollen!\x01Hó hó hó...húo!\x0B\x02", "box_type": 0},
    {"id": 0x2070, "text": "\x1ANon matter hú hard et ist, bara\x01ne kregen diskúraged. Hó Hó Hú!\x02", "box_type": 0},
    {"id": 0x2071, "text": "Beyond þet punkt lies Hylia-Sjó.\x01Et ist full de díp, pure vatn.\x0C( \x05CZoras\x05@, wer live alle  \x01veg upstrém, vakt sunken\x01tempel an sjós bottom, als \x01vel als Zoras Fountain.\x04Wenn du vollen til konfirm es lokaçion \x01auf kart, Drukk \x05ABEGINNEN \x05@til  \x01switk til Underskermar und \x05D¤\x05@ \x01oder \x05D£\x05@ til vinden Kart.\x04Alle setzt du havst visited \x01skal vesen şón auf kart. \x01Hó hú hút!\x0B\x02", "box_type": 0},
    {"id": 0x2072, "text": "\x1AOK, vesen vár und Gáe!\x02", "box_type": 0},
    {"id": 0x2073, "text": "\x1AWat ist dín namn?\x0B\x02", "box_type": 0},
    {"id": 0x2074, "text": "\x1A\x14\x01.....\x14\x00\x04\x1A\x05B\x0F\x05@...\x04\x1AStrange...et súnds somehó... \x01familiar.\x0B\x02", "box_type": 0},
    {"id": 0x2075, "text": "\x1AOK dan, \x0F...\x04\x1AIk am sker til sagen du geheimnis de\x01 Hélag Rike det havt gevesen\x01passed ned af Konglig Família\x01de Hyrule.\x0B\x02", "box_type": 0},
    {"id": 0x2076, "text": "\x06& Okarina de Tids!\x0B\x02", "box_type": 0},
    {"id": 0x2077, "text": "Dóde du understand vel stori\x01Ik bara sagde du?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2078, "text": "\x1AIk var spiing dur þet windó\x01bara nú...\x04\x1A ander element frá mís\x01drém... \x05Cdark klúds\x05@...\x01Ik believe sei simbolize...\x01det mar in þar!\x04Skal du sé dur windó\x01an en?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2079, "text": "\x1A\x14\x01........\x14\x00Ja.\x04\x1AIk sagde mís faþer om mís drém...\x04\x1AHowever, er didn't believe et var\x01ain profeki...\x04\x1AAber...Ik kan sense det mars ond\x01intençions!\x0B\x02", "box_type": 0},
    {"id": 0x207A, "text": "\x1AWat Ganondorf ist eftir mos vesen \x01keinwat less dan \x05ATriforce \x01\x05@de Hélag Rike.\x04\x1AEr mos have komen til Hyrule til\x01obtén et!\x04\x1AUnd, er vilt til konqer Hyrule...\x01non, hel verden!\x0B\x02", "box_type": 0},
    {"id": 0x207B, "text": "\x1A\x0F...nú, wir sin  \x01nur ainar wer kan protekt Hyrule!\x0B\x02", "box_type": 0},
    {"id": 0x207C, "text": "\x1AWir mos ne lat Ganondorf kregen\x01 Triforce!\x04\x1AIk skal protekt \x05DOkarina de Tids\x01\x05@mit alle mís kraft! \x01Er skal ne have et!\x04\x1ADu Gáe vinden ander \x05Atwei\x01Andlig Steinar\x05@!\x04\x1Alat uns kregen Triforce för\x01Ganondorf dót, und dan defét \x01en!\x0B\x02", "box_type": 0},
    {"id": 0x207D, "text": "\x1AAin meir ting...\x01Nim þet \x05Abrev\x05@...\x01Ik am viss et skal vesen helpful til du.\x0B\x02", "box_type": 0},
    {"id": 0x207E, "text": "\x1AMumble...mumble...\x01Huh? Ik am awake alrédi!\x04\x1AWat?\x04\x1AVel Ik skal vesen! Wenn et én't skog\x01kind frá ander dé!\x01Af veg, þanks ain mengd für\x01waking mik op!\x04\x1AEt nám sum dóend, aber Ik finalli \x01kreeg Malon zurück in ain gut múd.\x04\x1ASo, wat sin du op til todé?\x01Kreeg sum frí tid auf dín hender\x01du sagen?\x01Vel hú om ain klein spel?\x04\x1AÞese þri Kukkoar Ik have hér\x01sin spekial \x05ASuper Kukkoar\x05@!\x04\x1AIk am sker til werfen þese Kukkoar\x01inn det þar gaggle de normal\x01Kukkoar.\x04\x1AWenn du kan pik út þese þri \x01spekial birds frá among \x01normal Kukkoar wiþin tid \x01limit, Ik skal geven du \x05Aeinwat gut\x05@.\x04Wenn du ne kan vinden sen, Ik winnen.\x01It'll vesen 10 Rubinar... Vollen til spelen?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x207F, "text": "Mumble...mumble...\x01Ik am op! Ik am op!\x04Wat?\x04Hé, skog kind!\x01Kreeg sum frí tid?\x01Dan k'mon und spelen!\x04Ik am sker til werfen þese þri\x01\x05ASuper Kukkoar \x05@inn det gaggle de\x01normal Kukkoar.\x04Wenn du kan pik út þese þri \x01spekial birds frá among \x01normal Kukkoar wiþin tid \x01limit, Ik skal geven du \x05Aeinwat gut\x05@.\x04Wenn du ne kan vinden sen, Ik winnen.\x01It'll vesen 10 Rubinar... Vollen til spelen?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2080, "text": "Du havst 30 sekonds!\x01Alle righti dan, kregen Klar.\x01Hér Gáe Super Kukkoar!\x04\x060BEGINNEN LÚKIN'!!\x0B\x02", "box_type": 0},
    {"id": 0x2081, "text": "Tids op!\x01Ok baaaaad!!\x04Þese sin sum stór Kukkoar\x01sin ne sei!\x01Þei're raking in monei für mik!\x04Komen zurück til mik, mís babies!\x0B\x02", "box_type": 0},
    {"id": 0x2082, "text": "Det ist ain de 'em!\x01Halten et op! Halten et op!\x01\x05ATwei meir\x05@ til vinden!\x0B\x02", "box_type": 0},
    {"id": 0x2083, "text": "Þars ander!\x01Rétt vel, nú, moment de\x01sannheit! \x05AAin meir\x05@ til vinden!\x0B\x02", "box_type": 0},
    {"id": 0x2084, "text": "Golly! Ik skal vesen darned!\x01Et ist plum inkredible!\x04Det ist last ain!\x01Du havst fand sen alle!\x01Komen auf yfir hér!\x0B\x02", "box_type": 0},
    {"id": 0x2085, "text": "Vollen til forsöken aftur?\x04Ain ung mar als du mos have\x01ain rél fyr in dín belli!\x01Vinden þri de sen wiþin\x0130 sekonds.\x04Forsöken aftur für 5 Rubinar?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2086, "text": "Hé, du!\x01Du havst kreeg talent til vesen ain de\x01 verdens best kóbois!\x04Hó'd du als til marri Malon?\x01Huh?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x2087, "text": "\x1AHaw haw! Ik var bara kidding! \x01Bara kidding! Ik denken du sin ain klein\x01ung für det, sin ne du?\x01Haw haw haw!\x04\x1AÓ...! Ik am prúd til present til\x01du ain sample de unser meir ón \x05ALon\x01Lon Mjolk\x05@. Du skal vesen energized\x01 moment du drink et!\x04\x1AEftir du drink et, du kan \x01bring zurück \x05Aflaska \x05@und Kaup ain\x01refill, anitime du vollen!\x0B\x02", "box_type": 0},
    {"id": 0x2088, "text": "Hé pardner, du havst ain honest \x01ansikt!\x04Wenn du gró op, warüm ne du\x01komen til verk hér, auf þet \x01hestgarð? Det ist ain standing úter!\x01Ik skal vesen wéting für du.\x0B\x02", "box_type": 0},
    {"id": 0x2089, "text": "Hér du Gáe! Nim þet super\x01frisk \x05ALon Lon Mjolk\x05@!\x0B\x02", "box_type": 0},
    {"id": 0x208A, "text": "Hér du sin! Nim sum super\x01frisk mjolk...\x04Ó? Ok baaaaad!!\x01Du ne have ain Tom Flaska,\x01dó du?\x02", "box_type": 0},
    {"id": 0x208B, "text": "Mumble...mumble...\x01Ik am awake!\x04Wat?\x04Hé, \x0F!\x01Wenn du sin lúkin' für Malon,\x01elas rétt útan. Dóde du \x01komen hér til spelen?\x04Vel dan, hú om pléing \x01\x05ASuper Kukko-findin' spel \x05@mit mik?\x01Oder, dó du vollen til Kaup sum\x01\x05ALon Lon Mjolk\x05@?\x04What'll et vesen?\x01\x1C\x05BLon Lon Mjolk - 30 Rubinar\x01Kukko-findin' spel - 10 Rubinar\x01Quit\x05@\x02", "box_type": 0},
    {"id": 0x208C, "text": "\x08\x05ADu féled!\x05@\x01Du havst til jump yfir alle \x01fenkes!\x09\x0E<\x02", "box_type": 0},
    {"id": 0x208D, "text": "\x08\x05AAin meir lap!\x05@\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x208E, "text": "Sin du making viss til approak\x01 fenkes hövd auf? Wenn du \x01approak an ain angle, hest\x01skal ne jump!\x04Wenn du vollen til forsöken aftur, múnt\x01Epona und kregen Klar!\x02", "box_type": 0},
    {"id": 0x208F, "text": "\x1ADu dóde et!\x01\x05A\x17\x05@ ist nüv kúrse rekord!\x04\x1AIk have til geven du ain present til\x01kommemorate dín nüv rekord!\x04\x1A present ist ain klein ok tung\x01til geven til du hér, so Ik skal have et\x01delivered til dín húse. Bet du\x01ne kan warten til séen et! Hí hí!\x02", "box_type": 0},
    {"id": 0x2090, "text": "rekord so fjarr ist \x05A50 sekonds\x05@.\x01Dín best tid ist \x05A\x1E\x03\x05@.\x04Wenn du kan bét rekord, Ik skal\x01geven du ain present.\x01Geven et dín best skot, OK?\x04lat uns kregen sker!\x0B\x02", "box_type": 0},
    {"id": 0x2091, "text": "Dín best tid ist \x05A\x1E\x03\x05@!\x01Hú fast kan du Gáe?!\x01K'mon, lat uns kregen started!\x0B\x02", "box_type": 0},
    {"id": 0x2092, "text": "kurrent rekord ist \x05A50 sekonds\x05@.\x01Fyrst, forsöken til bét þet rekord!\x04Wenn du kan bét rekord, Ik skal\x01geven du ain present!\x01Geven et dín best skot, OK?\x04Rétt vel, lat uns kregen started!\x0B\x02", "box_type": 0},
    {"id": 0x3000, "text": "\x1ADu ne weten wat er méns af\x01\"Sworn Bróderar,\" aber du havst \x01gesamlt twei Andlig Steinar!\x01Du havst ain meir til vinden!\x02", "box_type": 2},
    {"id": 0x3001, "text": "\x1ADu ne weten wat er méns af\x01\"Sworn Bróderar,\" aber du havst \x01finalli gesamlt alle þri Steinar!\x01Gáe zurück til séen Prinsess Zelda!\x02", "box_type": 2},
    {"id": 0x3002, "text": "Ik maaaade þissss...\x01Trrrrade für \x05Aklémmm kekkk\x05@...\x02", "box_type": 0},
    {"id": 0x3003, "text": "Ik giiiive þissss til iúoú forrr\x01ain súvenirrrrr.\x02", "box_type": 0},
    {"id": 0x3004, "text": "\x1AKind, Ik als du!\x04\x1AHús om du und Ik werden\x01Sworn Bróderar?!\x04\x1ANon, þars non grós keremoni\x01involved! Bara nim þet als ain\x01tegn de unser friendşip!\x02", "box_type": 0},
    {"id": 0x3005, "text": "\x060Du dóde stór!\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3006, "text": "Hú 'bút ain grós Goron hug, \x01Bróder?!\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3007, "text": "\x06PÓ!\x0C\x1E\x06KÓ-ó!\x0C(\x06K\x08K'mon!\x09\x0C\x1E\x06\x14Komen auf! Komen auf! \x08Komen auf!\x09\x0C(\x06P\x08HOT!!\x09\x0C\x1E\x06(Wat ain hot bét!\x0C(\x062WHÚÚAH!\x0C(\x06<\x08IÍÍAH!\x09\x0C(\x06<\x08IAHÚO!!\x09\x02", "box_type": 0},
    {"id": 0x3008, "text": "\x1AIk am ain de \x05AGorons\x05@,\x01 stein-éting folk wer live\x01auf Dauðfjall.\x04\x1ASé an det huge búlder yfir\x01þar!\x04\x1AEt bloks entranke til \x01\x05ADodongos Cavern\x05@, welk var aingång\x01ain meir important setzen für uns\x01Gorons...\x04\x1AAber ain dé, manig Dodongos\x01suddenli skén innan  \x01kavern. Et vard ain meir \x01dangerús setzen!\x04\x1AAuf topp de det, ain \x05AGerudo in blak\x01armor \x05@brukte es magik til sél \x01entranke mit det búlder!\x070*\x02", "box_type": 0},
    {"id": 0x3009, "text": "Ik wiş Ik konde roll ned  \x01fjall als ain rok, mit ain\x01\x05ABomb Flower \x05@und...\x04\x08\x06<\x05ABÚÚÚM!\x05@\x09\x04Wenn Ik konde dó det mit ain Bomb \x01Flower, Ik konde werden ain rél mar.\x02", "box_type": 0},
    {"id": 0x300A, "text": "Ik am standing hér til şade \x01\x05ABomb Flowers \x05@frá sun.\x04Dó du havst ain qesçion für mik?\x01\x01\x1B\x05BAsk om Bomb Flowers\x01Ask om Dodongos Cavern\x05@\x02", "box_type": 0},
    {"id": 0x300B, "text": "De plants gróing yfir þar \x01sin \x05ABomb Flowers\x05@. Sei sin\x01\"mining plants\" det gró nur auf\x01þet fjall.\x04 flóers fruit ist raw \x01material für Bombar.\x04Aber ain non-Goron amateur skold \x01aldrei pik Bomb Flowers' \x01fruit!\x04Sei usualli gró nur in dark \x01setzt, so Bomb Flowers det gró\x01in ain setzen als þet sin extremeli\x01rare.\x02", "box_type": 0},
    {"id": 0x300C, "text": "De plants gróing yfir þar \x01sin \x05ABomb Flowers\x05@. Sei sin\x01\"mining plants\" det gró nur auf\x01þet fjall.\x04Sei usualli gró nur in dark \x01setzt, als kaves, so Bomb \x01Flowers det gró in ain setzen als\x01þet sin extremeli rare.\x04Wenn du havst \x05AGoronens Armband\x05@,\x01ok ain klein kind als du konde\x01ésili pik et mit \x05C\x9F\x05@.\x02", "box_type": 0},
    {"id": 0x300D, "text": "Dóde Du séest kavern auf dín \x01veg hér? Det ist \x05ADodongos \x01Cavern\x05@.\x04Bekabruk ljós innan ist meir \x01dim, \x05ABomb Flowers\x05@, ain plant \x01uniqe til þet fjall, gró als\x01krazi in þar!\x02", "box_type": 0},
    {"id": 0x300E, "text": "\x1AÓ?\x04\x1AWir ne kregen manig visitors veg\x01op hér. Var sin du frá?\x04\x1A skog?\x04\x1AWat ist ain \"skog\"?\x04\x1AEh?\x04\x1AEt ist var ain mengd de \"träar\" und \x01\"plants\" gró?\x04\x1ANú Ik am ok meir konfused! \x01Keinwat grós kring hér besides\x01 \x05ABomb Flowers\x05@...\x04\x1AWir ne have \"frä\" oder \"nötar\"\x01kring hér eiþer.\x04\x1AOk Deku-Stavar sin meir skarke\x01kring hér!\x070\"\x02", "box_type": 0},
    {"id": 0x300F, "text": "Ik séled entranke bekabruk Ik\x01ne have meir merkandise til\x01seljen. Aber du sin qite ain persistent\x01kustomer, sin ne du.\x0B\x02", "box_type": 0},
    {"id": 0x3010, "text": "Ik am sorri...\x01Det Bomb ist bara für displé. \x01Ik am \x05Asold út \x05@de rél ainar.\x0B\x02", "box_type": 0},
    {"id": 0x3011, "text": "Warüm dóde du stoppen mik?\x01Ne stoppen mik hér!\x04Du ne kan stoppen mís wild rolling!\x04Þet wild rolling ist nur veg\x01til relieve mís stress!\x04Nú stá in awe de mís wild, wild\x01rolling!!\x02", "box_type": 0},
    {"id": 0x3012, "text": "\x1ARétt vel! Ik skal geven du þet\x01in prése de dín kúrage!\x0B\x02", "box_type": 0},
    {"id": 0x3013, "text": "Dank dir! lat mik express mís joi\x01mit meir wild rolling!\x02", "box_type": 0},
    {"id": 0x3014, "text": "\x1A\x06!Ó...Ik am so hungri...\x04\x1AAlle fült fént frá hunger\x01bekabruk de fúd şortage in \x01þet stad. Wir sin in danger de \x01extinkçion!\x04\x1AEt ist alle bekabruk wir ne kan enter\x01unser qarri, \x05ADodongos Cavern\x05@.\x04\x1AWir Gorons live auf ain diet de \x01roks...\x04\x1AUnd most delikiús und \x01nutritiús roks kring sin fand \x01in Dodongos Cavern! Aber det \x01síms als ankient histori nú...\x04\x1AWe've werden suk gúrmets det \x01wir ne kan stá til ét roks frá\x01aniwhere else!\x070\x15\x02", "box_type": 0},
    {"id": 0x3015, "text": "Sigh... Ik vollen til ét topp\x01sirloin roks frá \x05ADodongos \x01Cavern\x05@!\x02", "box_type": 0},
    {"id": 0x3016, "text": "\x1AHé!\x04\x1AEt ist dangerús gegn ain klein kind als\x01du til komen út hér. Du might \x01fall ned!\x04\x1AWenn Ik am ne mistaken, du kom út\x01hér til ét \x05Aröd stein\x05@!\x01Vel, ok mal! Et ist ne hér!\x04\x1AWat? Det ist ne warüm du sin\x01hér?\x04\x1ADu sin séend gegn ain \"Andlig\x01Stein?\" Du mos mén det \x01delikiús-séend röd stein\x01det var aingång gevist hér!\x04\x1AIk var so hungri det Ik þúght\x01et vold vesen OK til bara geven et ain\x01tini klein lik...so Ik snuk út\x01hér. Aber, et var alrédi gangen!\x04\x1AIk denken Grós Bróder nám et bort.\x04\x1AEr alwés segt det alle\x01ist eftir det röd stein!\x070\x17\x02", "box_type": 0},
    {"id": 0x3017, "text": "Grós Bróder havt şut himself op in\x01es rúm séing,\x01\"\x05AIk skal warten in hér gegn \x01Konglig Famílias messenger!\x05@\"\x02", "box_type": 0},
    {"id": 0x3018, "text": "\x1AIk am so hungri det Ik ne kan denken\x01om aniþing aber fúd!\x04\x1AAsk Grós Bróder om komplikated\x01tingar.\x04\x1AWenn er ist in ain mal múd, he'll \x01probabli kregen mad an du...et\x01kan vesen pretti skari. Aber...\x04\x1AIk weten es GEHEIMNIS.\x04\x1AEr möge ne sé als art,\x01aber Grós Bróder líbt til danke!\x01Wenn er kregenar in ain rhiþm, he'll sureli...\x070\x19\x02", "box_type": 0},
    {"id": 0x3019, "text": "Ik erinnern Grós Bróder brukte til\x01alwés hlusten til \x05Bmusik det\x01komt frá skog\x05@...\x04Ah ja, gut alt dés...\x01Det musik makt mik füle\x01nostalgik, ok...\x070,\x02", "box_type": 0},
    {"id": 0x301A, "text": "\x1AWat hek! Wer sin du?!\x04\x1AWenn Ik hérd \x05Csang de \x01Konglig Família\x05@, Ik expekted ser \x01messenger hadde arrived, aber...\x01du sin bara ain klein kind!\x04\x1AHavt \x05ADarunia\x05@, grós herre de\x01 Gorons, sannlig verloren so meir\x01status til vesen tréted als þet\x01af es Sworn Bróder, Kong?\x04\x1ANú, Ik am SANNLIG angri!\x01Kregen út de mís ansikt, nú!\x04\x1ASin du asking warüm Ik am in suk ain\x01mal múd rétt nú?\x04\x1A\x08Ancient krétures have \x01infested Dodongos Cavern!\x09\x04\x1A\x08We've hadde ain púr harvest de unser\x01spekial krop, Bomb Flowers!\x09\x04\x1A\x08Starvation und hunger weil\x01de rok şortage!\x09\x04\x1A\x06HAber...\x070\x1B\x02", "box_type": 0},
    {"id": 0x301B, "text": "\x08\x06\x19Þet ist ain Goron problem!\x09\x04\x08\x06\x11Wir ne mos ein helpen frá\x01\x06Fstrangers!\x09\x02", "box_type": 0},
    {"id": 0x301C, "text": "\x1A\x08\x06\x15Heeey!! Wat ain nike tune!\x09\x04\x1ABara als det, mís depresçion ist\x01alle gangen! Einwat bara kom \x01yfir mik! Ik suddenli vold til\x01danke als krazi!\x04\x1A\x06<Ik am \x05ADarunia\x05@!\x04\x1AIk am grós herre de Gorons!\x01Var þar einwat du vold \x01til ask mik om?\x04\x1A\x06PWat?\x04\x1ADu vollen \x05AAndlig Stein de\x01Fyr\x05@, ok?\x04\x1A Andlig Stein de Fyr, ok\x01knón als Goronens Rubin, ist unser\x01rakes skjult skatt....\x04\x1AAber halten auf--Ik am ne sker til geven\x01et til du det ésili.\x01Wenn du vollen et so badli...\x04\x1AWarüm ne du Gáe zerstöten  \x01monsterar innan de Dodongos \x01Cavern und prove du sin ain rél mar?\x04\x1ADet veg, alle skal vesen \x01glad aftur! Wenn du dó et, Ik \x01skal geven du aniþing du vollen,\x01ok Andlig Stein!\x04\x1AIk have einwat für du. Ik am ne\x01sannlig giving du þet in\x01teruggeven für aniþing, aber nim et\x01aniwé.\x04\x1AWenn du drage þet, ok ain klein \x01fella als du kan pik ain \x05ABomb \x01Flower \x05@brukend \x05C\x9F\x05@.\x02", "box_type": 0},
    {"id": 0x301D, "text": "Zerstöten monsterar in \x01\x05ADodongos Cavern \x05@und werden ain \x01rél mar! Dan, wir kan talen om\x01 Andlig Stein!\x02", "box_type": 0},
    {"id": 0x301E, "text": "Hé, Bróder, spelen det tune\x01aftur sometime sún!\x02", "box_type": 0},
    {"id": 0x301F, "text": "Non matter hú manig tidar Ik hören \x01det sang, et dót ne kregen alt!\x02", "box_type": 0},
    {"id": 0x3020, "text": "Vel, det ist ne qite wat Ik \x01var séend für...\x04Ik vold til hören...ain tune...\x01einwat...um...frá útan \x01 fjallar...einwat...\x01grän...natural...\x04Det ist kind de musik Ik vollen \x01til hören...\x02", "box_type": 0},
    {"id": 0x3021, "text": "Ó, nú wir kan enter kavern.\x01Du sin so smart!\x02", "box_type": 0},
    {"id": 0x3022, "text": "Ik weten ain list til konserve stavar!\x01Wenn du ljós ain stav auf fyr, et skal \x01burn til aşes. Drukk \x05C\x9F\x05@ til zetten et\x01bort för et kompleteli burns!\x04Af veg, Ik hid ain stav\x01somewhere...\x01Hehehee...\x02", "box_type": 0},
    {"id": 0x3023, "text": "\x1AEt ist mik, \x05ADarunia\x05@!\x01Vel ferdig!\x04\x1AThanks til du, wir kan aingång aftur\x01ét delikiús roks frá \x01Dodongos Cavern bis unser \x01stomaks burst!\x02", "box_type": 0},
    {"id": 0x3024, "text": "\x1AIk am so hungri det Ik ne kan denken\x01om aniþing aber fúd!\x04\x1A\"Andlig Stein?\"\x01Det \x05Aröd stein\x05@ det var lighting\x01op unser kiti?\x04\x1AGrós Bróder \x05ADarunia\x05@ nám et\x01bort. Dan, er şut himself op in\x01es rúm und skal ne komen út.\x04\x1AWeil dan, et fült als alle\x01 ljósar in kiti have gangen \x01út... Alle síms so...\x01depressed...\x070%\x02", "box_type": 0},
    {"id": 0x3025, "text": "Ik vollen du til bring \x05Afyr\x05@ frá Grós\x01Bróders rúm zurück hér.\x02", "box_type": 0},
    {"id": 0x3026, "text": "Ó, Ik séen...\x01Wir skold have þrón  \x01Bomb frá kliff...\x02", "box_type": 0},
    {"id": 0x3027, "text": "Du sin inkredible, destroiing \x01 Dodongos! Dó du hug wenn Ik \x01kall du Grós Bróder?\x02", "box_type": 0},
    {"id": 0x3028, "text": "Thanks til du, wir sin alle OK!\x01Warüm ne du Kaup sum Bombar \x01nú?\x0B\x02", "box_type": 0},
    {"id": 0x3029, "text": "Du weten, Ik am so grateful til du.\x01Wenn Ik have ain kind, Ik skal namn et\x01eftir du!\x02", "box_type": 0},
    {"id": 0x302A, "text": "Wenn du vollen til hören meir Goron\x01gossip, hövd op til unser kiti!\x04\x05AGoron City\x05@ ist bara ain klein\x01veg op trél. Et skal ne nim\x01meir longer til kregen þar, ok\x01auf fút.\x02", "box_type": 0},
    {"id": 0x302B, "text": "Du pik Bomb Flowers mit \x01\x05C\x9F\x05@. Drukk \x05C\x9F \x05@aftur til sette et.\x02", "box_type": 0},
    {"id": 0x302C, "text": "Wenn alle \x05Atorkes\x05@ auf þet flúr\x01sin lit, Goron City ist sannlig liveli!\x02", "box_type": 0},
    {"id": 0x302D, "text": "Sin du sker til klér út  \x01Dodongos? Et ist ain Goron problem,\x01þótt. Du sin ain nosei klein kind,\x01sin ne du?!\x04Vel, de kúrse wir skal vesen glad wenn \x01du fix et so wir kan kregen alle \x01Bombar wir vollen, als wir brukte til...\x04Bara lat mik warn du, þótt...\x01Dodongos sin skari krétures! \x01Þei'll ét ANIÞING!!\x04So watk dikself, und ne \x01kregen éten!\x0B\x02", "box_type": 0},
    {"id": 0x302E, "text": "Ik alrédi sagde du!\x01Wir sin út de Bombar!\x01Ohhh... Ik am so hungri!\x0A\x02", "box_type": 0},
    {"id": 0x302F, "text": "Hú var Grós Bróder?\x01Ik séen...\x04Af veg, dó du weten \x01musik koming frá díp innan de\x01þet tunnel? Wir alle als þet musik!\x02", "box_type": 0},
    {"id": 0x3030, "text": "Ik skal ne lat Du havst mik! \x01Du probabli verk für Ganondorf!\x02", "box_type": 0},
    {"id": 0x3031, "text": "\x1AHú konde du dó þet til mik?\x01Du, du sin Ganondorfs servant!\x04\x1AHören mís namn und tremble!\x04\x1AIk am \x05A\x0F\x05@! \x01Held de Gorons!\x02", "box_type": 0},
    {"id": 0x3032, "text": "\x1AWat?\x04\x1ADín namn ist ok\x01\x0F?\x04\x1ADan du mos vesen legendari\x01Dodongo Buster und Held, \x01\x0F!\x04\x1AMís dad ist \x05ADarunia\x05@...\x01Dó du erinnern en?\x04\x1ADad named mik \x0F\x01eftir du, bekabruk du sin so \x01brave!\x04\x1AEt ist ain kúl namn!\x01Ik sannlig als et!\x04\x1A\x0F, du sin ain held til \x01uns Gorons! \x01Ik am so glad til mít du!\x04\x1ABitte geven mik dín autograf!\x01Sign et:\x01\x06\x05\"Til mís friend, \x01\x06\x05\x0F de Gorons\"\x04\x1AÓ...\x04\x1AIk guess et ist ne ain gut tid\x01til ask du für þet...\x01Bitte helpen alle!\x04\x1AMís dad, Darunia, ging til \x05AFyr\x01Tempel\x05@. Ain dragon ist innan!\x04\x1AWenn wir ne Snelt op, ok mís dad\x01skal vesen éten af dragon!!\x0703\x02", "box_type": 0},
    {"id": 0x3033, "text": "B-b-b-búú húúo!\x0B\x02", "box_type": 0},
    {"id": 0x3034, "text": "Du vold beter forsöken til kalm en ned\x01wenn du kan...\x01Kannski er skal kalm ned wenn du \x01talen til en?\x04Wat dó du vollen til ask en?\x01\x01\x1B\x05BOm dragon\x01Om Gorons\x05@\x02", "box_type": 2},
    {"id": 0x3035, "text": "\x1AAin lang tid ago þar var ain\x01ond dragon named \x05AVolvagia \x05@living \x01in þet fjall.\x04\x1ADet dragon var meir skari!\x01Er ate Gorons!\x04\x1ABrukend ain huge hamar, held de\x01 Gorons... BÚOM!\x04\x1AZerstört et bara als det. Þet ist \x01ain miþ frá lang ago, aber et ist \x01true!\x04\x1AIk weten, bekabruk mís dad ist ain\x01deskendant de held!\x0703\x02", "box_type": 0},
    {"id": 0x3036, "text": "\x1AAlle var genomen til  \x01\x05AFyr Tempel\x05@...\x04\x1AMeðan mís dad var út...\x01Ganondorfs follóers\x05A \x05@kom und\x01nám sen alle bort!\x04\x1AAlle de sen skal vesen éten af\x01\x05AVolvagia\x05@!\x04\x1ADad sagde det Ganondorf havt\x01revived Volvagia...\x04\x1AAls ain warning til de wer might\x01oppose en, Ganondorf ist sker til\x01fíd sen alle til Volvagia!\x04\x1ADad ging til Fyr Tempel alle\x01af himself til forsöken til redden \x01alle...\x04\x1ABitte helpen, \x0F!\x01Ik skal geven du þet \x05Ahét-resistant\x01tunik\x05@!\x02", "box_type": 0},
    {"id": 0x3037, "text": "\x1ADad sagde mik ne til lat anibodi \x01folló en til tempel, aber...\x04\x1ANur du, \x0F, kan\x01redden alle!\x04\x1AIk am viss det búð óner, wer\x01ist hiding somewhere rétt nú, skal\x01ok helpen du!\x04\x1ANú, Ik skal sagen du om geheimnis\x01passage til Fyr Tempel!\x0708\x02", "box_type": 0},
    {"id": 0x3038, "text": "Forsöken til move \x05Astatue \x05@innan\x01Dads rúm!\x02", "box_type": 0},
    {"id": 0x3039, "text": "\x1AWers þar? Ist det du,\x01\x0F...?\x04\x1AÓ, et sannlig ist \x0F!\x04\x1ADu havst grón so grós weil Ik last\x01sag du!\x04\x1AIk vollen til have ain mar-til-mar talen\x01mit du, aber nús ne tid.\x04\x1AGanondorf ist kausing trúble auf\x01Dauðfjall aftur!\x01Er havt revived ond, ankient\x01dragon Volvagia!\x04\x1AAuf topp de det, er ist sker til\x01fíd mís folk til det ond dragon\x01als ain warning til ander rakes det\x01might resist en...\x04\x1AWenn det fyr-bréþing dragon\x01eskapes frá fjall, alle de\x01Hyrule skal werden ain burning\x01wasteland!\x04\x1AIk skal Gáe auf ahéd til forsöken til sél\x01op ond dragon...\x04\x1AIk am konkerned, þótt, bekabruk Ik\x01ne have legendari hamar...\x01Aber Ik have non koike.\x04\x1A\x0F...Ik am asking du til\x01dó þet als mís Sworn Bróder...\x04\x1AMeðan Ik am triing til handel mit \x01dragon, Bitte redde mís folk!\x04\x1A prisoners' kells sin in \x01opposite direkçion.\x01Ik am reiknend auf du, \x01\x0F!\x02", "box_type": 0},
    {"id": 0x303A, "text": "Ik am gereddet!\x01Dank dir!\x01Hér, nim þet!\x02", "box_type": 0},
    {"id": 0x303B, "text": "\x1A\x0F...Ne kan halten... \x01animore...Ik ne kan halten\x01et ein longer...\x04\x1AKregen út de hér!!\x02", "box_type": 0},
    {"id": 0x303C, "text": "\x1ADank dir, Bróder!\x01Ik sannlig apprekiate wat du\x01dóde. Ik Dank dir auf behalf de\x01 hel Goron rake!\x04\x1ADu turned út til vesen ain rél mar,\x01bara als Ik þúght du vold!\x02", "box_type": 0},
    {"id": 0x303D, "text": "\x066Ne vergessen...\x01\x06\x03Nú du und Ik sin true Bróderar!\x0EP\x02", "box_type": 5},
    {"id": 0x303E, "text": "\x1AEt ist einwat det grós yfir\x01tid... ain true friendşip.\x01Ain fíling in hert det \x01verdet ok stronger yfir tid...\x04\x1A pasçion de friendşip skal \x01sún blossom inn ain righteús\x01kraft und dur et, du skal\x01weten welk veg til Gáe...\x04\x1AÞet sang ist dedikated til  \x01kraft de hert...\x01Hlusten til \x05ABolero de Fyrs\x05@...\x02", "box_type": 0},
    {"id": 0x303F, "text": "\x1A\x0F...Séen du aftur...\x02", "box_type": 0},
    {"id": 0x3040, "text": "\x08\x05D\x0F, et ist so hot in \x01hér! Wir ne kan sté hér für\x01lang!\x05@\x09\x0E<\x02", "box_type": 0},
    {"id": 0x3041, "text": "\x1ABróder \x0F!\x01Alle havt komen zurück!\x04\x1ADad und du zerstört dragon\x01togeþer, didn't du!\x070B\x02", "box_type": 0},
    {"id": 0x3042, "text": "Wenn Ik gró op, Ik vollen til vesen ain\x01strong mar als du, \x01\x0F!\x02", "box_type": 0},
    {"id": 0x3043, "text": "Dank dir, \x0F!!\x02", "box_type": 0},
    {"id": 0x3044, "text": "Dank dir meir meir für\x01reddend uns!\x0A\x02", "box_type": 0},
    {"id": 0x3045, "text": "\x1AAf veg, Ik, wild Darunia,\x01turned út til vesen stór \x01\x05ASage de Fyr\x05@...\x04\x1AIst ne det funni, Bróder?\x01Vel, þet mos vesen wat sei kall\x01destini.\x04\x1AKeinwat havt gemakt mik happier\x01dan helping du sél ond\x01hér!\x02", "box_type": 0},
    {"id": 0x3046, "text": "\x1AHé, Bróder, nim þet!\x01Þet ist ain \x05AMedallion \x05@det konténs\x01 kraft de fyr andear--und\x01mís friendşip.\x02", "box_type": 0},
    {"id": 0x3047, "text": "Grós problem!\x01Alle ist gangen!\x01Aber Ik skal halten mís business opnen!\x0A\x02", "box_type": 0},
    {"id": 0x3048, "text": "\x1AWat ain wild adventure! Et skal\x01maken ain inkredible stori...\x04\x1AIk ne kan believe det Dodongos\x01suddenli skén in suk stór \x01numbers!\x04\x1AUnd det grós rok bloking  \x01kave...\x04\x1AAlle þet trúble mos have gevesen\x01kaused af det Gerudo þief, \x01\x05AGanondorf\x05@!\x04\x1AEr sagde, \x01\"\x05DGeven mik Andlig Stein!\x01Nur dan skal Ik opnen kave \x01für du!\x05@\"\x04\x1ADu, auf ander hand, risked \x01dín líf für uns...\x02", "box_type": 0},
    {"id": 0x3049, "text": "\x06KTight fit...\x02", "box_type": 0},
    {"id": 0x304A, "text": "Ik am working auf einwat sannlig \x01kúl rétt nú! Aber Ik denken et ist\x01sker til nim ain meðan...\x070K\x02", "box_type": 0},
    {"id": 0x304B, "text": "Wenn du kan warten fim oder sex ár,\x01et skold vesen Klar. OK?\x02", "box_type": 0},
    {"id": 0x304C, "text": "Ik bara geendet ain klein vápn.\x01Hú om et...\x070O\x02", "box_type": 0},
    {"id": 0x304D, "text": "Hú dó du als füle de et?\x02", "box_type": 0},
    {"id": 0x304E, "text": "Et sýnt als þar ist ain problem \x01mit es durabiliti...\x01Aber still...\x070O\x02", "box_type": 0},
    {"id": 0x304F, "text": "Hú om buiing þet kníf für \x01200 Rubinar?\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x3050, "text": "Rétt vel. Komen zurück aftur.\x02", "box_type": 0},
    {"id": 0x3051, "text": "Bitte...Ne...Eat mik...\x01Wenn du ét einwat als mik,\x01du skal kregen ain stomak ake!\x04Du skal vesen sorri!!\x02", "box_type": 0},
    {"id": 0x3052, "text": "Ó, Ik séen. Grós Bróder Darunia\x01asked du til reskue mik.\x01Ik óe du grós tid!\x04Bitte helpen Grós Bróder!\x02", "box_type": 0},
    {"id": 0x3053, "text": "Mís Brotherrrr...\x01Opened ain nüv storrrre...\x01Et ist Medigorons Kling\x01Storrrrrrrre...\x04Howeverrrrr... \x01Ik am betterrrrrr an making\x01bladessssss.\x04Hylian karpenterrrrrs prése\x01mik forrrrrr mís skillssssss.\x01Ik am ne liinnnnng...\x02", "box_type": 0},
    {"id": 0x3054, "text": "\x1ADet broten kníf ist sureli mís \x01worrrrrrrrrrk...\x01Ik sannlig vollen til repérrrrr et, aber...\x04\x1AAber bekabruk de iesterrrrrdés\x01errrrrupçion, mís augar sin \x01irrrrrrrritated...\x04\x1AÞar sin gut eiedrops in Zoras\x01Domain... Du skal vinden sen wenn du\x01Gáe til séen \x05AKinnnnnng Zorrrrrra\x05@...\x070U\x02", "box_type": 0},
    {"id": 0x3055, "text": "Bitte Gáe kregen eiedrrrrrrops...\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x3056, "text": "Awww núúo... Ik am finişed...\x01Mís augar arrrrrre so itki...\x01Owwwwww...\x02", "box_type": 0},
    {"id": 0x3057, "text": "Ó, non! Alles gangen!\x01Nur Ik var lét bak!\x0B\x02", "box_type": 0},
    {"id": 0x3058, "text": "Ik have gevesen wéting forrrrr du,\x01mit térrrrrrs in mís augar...\x01Bitte sagen hello til Kinnng Zorrra!\x02", "box_type": 0},
    {"id": 0x3059, "text": "\x1ARrrrreally? Du brrrrúght aug\x01dropar? Ik am so rrrrrelieved! Ik am\x01sker til Bruk sen rrrrrright nú!\x0B\x02", "box_type": 0},
    {"id": 0x305A, "text": "\x1A\x05AWowwwwwwwwwwwwww!!\x05@\x04\x1AÞet ist stimulating! Et ist\x01worrrrrking grrrrrét!\x04\x1ANú Ik kan kregen zurück til mís kling\x01business! Mís worrrrrk ist ne \x01verrrri konsistent, so Ik skal geven þet \x01til du so du skal ne forrrrrget.\x070\\\x02", "box_type": 0},
    {"id": 0x305B, "text": "Alle havt komen zurück!\x01Et ist business als usual!\x0B\x02", "box_type": 0},
    {"id": 0x305C, "text": "Afterrrr ain wenig dés...\x01Bitte returrrrrrn...\x01Warten, bara warten patientli...\x02", "box_type": 0},
    {"id": 0x305D, "text": "Ne iet...\x01Hé du...\x01Du arrrre impatient...\x02", "box_type": 0},
    {"id": 0x305E, "text": "Det sworrrrd ist mís best \x01worrrrk!\x02", "box_type": 0},
    {"id": 0x305F, "text": "\x08\x05DDín \x05@skjold \x05Dist gangen!\x05@\x09\x0E<\x02", "box_type": 0},
    {"id": 0x3060, "text": "\x08\x05D \x05@tunik \x05Ddu varen wéring ist \x01gangen!\x05@\x09\x0E<\x02", "box_type": 0},
    {"id": 0x3061, "text": "\x08\x05DDín \x05@skjold \x05Dist gangen!\x01 \x05@tunik \x05Ddu varen wéring havt\x01ok gevesen genomen!\x05@\x09\x0E<\x02", "box_type": 0},
    {"id": 0x3062, "text": "\x1ADu havst ferdig vel til komen alle \x01veg op hér, \x0F. \x01Þet ist summit de hélag\x01Dauðfjall! Hoot!\x04\x1AEt ist sagde det klúds \x01surrúnding þet pék reflekt \x01kondiçion de Dauðfjall. Wenn\x01sei sé normal, et ist an péke.\x04\x1AClimbing alle veg op hér\x01bara proves hú smart du sin!\x01Nú Ik vollen til séen du maken\x01ander smart move...\x04\x1A \x05AStór Féa\x05@ lives auf þet\x01múnténtop, und ela skal geven\x01du ain nüv skill! Ela ist léder\x01de féries, du weten. Hú!\x04\x1AIk skal perk hér und warten für du.\x01Wenn du sin Klar til Gáe zurück\x01ned, Ik kan helpen du! \x01Nú, kregen sker!\x02", "box_type": 0},
    {"id": 0x3063, "text": "Hú hút!\x01Vel, et sýnt als du havst grón\x01op ain klein frá Stór Féas\x01kraft...\x04Aber du still ne sannlig sé als\x01 held wer skal redden Hyrule. An\x01lést ne iet!\x04Wenn du sin sker zurück \x05Aned \x01fjall\x05@, Ik kan lend du ain wing.\x01Komen hér und grab mís talons!\x01Und halten auf tight! Hú húúúot!\x02", "box_type": 0},
    {"id": 0x3064, "text": "Sei sagen det ain \x05Abéutiful\x05@ \x05AFéa\x01\x05@lives auf topp de Dauðfjall!\x04Ne du vollen til séen elar?\x02", "box_type": 0},
    {"id": 0x3065, "text": "Sei sagen det ain \x05AFéa \x05@lives auf topp\x01de Dauðfjall.\x04Wenn du vollen til maken et til topp,\x01du vold beter nim ain grós \x05Dskjold\x05@\x01mit du...\x02", "box_type": 0},
    {"id": 0x3066, "text": "\x08\x05DSé! Ain \x05@kiken \x05Dhatked frá\x01 \x05@egg \x05Ddu varen inkubating!\x01Et ist mirakle de líf!\x05@\x09\x0Ek\x02", "box_type": 2},
    {"id": 0x3067, "text": "Dóde Du havst röd stein?\x01lat mik kregen ain klein lik!\x04Non? Booooo!\x02", "box_type": 0},
    {"id": 0x3068, "text": "\x1ABróder! Du skal halten bruşing op\x01auf dín skills als du travel,\x01skal ne du?\x04\x1ADu skold Gáe séen \x05AStór Féa\x05@\x01auf topp de Dauðfjall! Ela\x01skal kraft du op!\x04\x1AHé, alle! lat uns séen fram unser\x01Bróder!\x02", "box_type": 0},
    {"id": 0x3069, "text": "\x1AIk skal sagen du ain geheimnis für\x01reddend mik!\x04\x1AIn þet tempel, þar sin \x05Adyrar\x01det fall ned \x05@wenn du forsöken til \x01opnen sen. Wenn ain de þese\x01dyrar begint til fall, move!\x04\x1AWenn du Bruk ain sample de \x01Goron \"spekial krop,\" du kan\x01breken et...\x02", "box_type": 0},
    {"id": 0x306A, "text": "\x1Alat mik sagen du ain geheimnis als\x01ain belónung für losend mik!\x04\x1AWenn du sin auf fyr, du kan zetten\x01et út af swinging dín sverd, oder\x01af rolling forward... Dóde du weten\x01det?\x02", "box_type": 0},
    {"id": 0x306B, "text": "\x1AHérs ain tip für reskuing mik!\x04\x1ASomewhere in þet tempel, du sin\x01viss til mít op mit sum \x01krétures det danke als sei\x01angrepen. pilar skal ne hurt sen!\x04\x1ASýnt als du might mos sum de\x01 Goron \"spekial krop!\" Det ist\x01alle Ik have til sagen du!\x02", "box_type": 0},
    {"id": 0x306C, "text": "\x1AIk skal sagen du ain geheimnis für\x01reddend mik!\x04\x1AÞar sin switkes in þet tempel\x01det du havst til kut til aktivate.\x01Aber, du kan ok Bruk Goron\x01\"spekial krop\" til dó job.\x02", "box_type": 0},
    {"id": 0x306D, "text": "\x1AIk skal sagen du ain geheimnis für\x01reddend mik!\x04\x1AWenn du vinden ain setzen det du kan\x01séen auf kart, aber ne kan rék,\x01forsöken pléing dín Okarina!\x02", "box_type": 0},
    {"id": 0x306E, "text": "\x1AIk skal sagen du ain geheimnis für\x01reddend mik!\x04\x1AIn order til kregen inn rúm\x01var Darunia ging, du havst til\x01dó einwat om pillar\x01stuk in keiling.\x04\x1AVinden ain paþ det léds til ain rúm\x01above keiling rétt bort!\x02", "box_type": 0},
    {"id": 0x306F, "text": "\x1AIk skal sagen du ain geheimnis für\x01reddend mik!\x04\x1AAin dyr ist skjult innan statue\x01an entranke til þet tempel.\x04\x1AAber, Goron \"spekial krop\" skal ne\x01verk auf et... Ne du havst\x01aniþing stronger?\x02", "box_type": 0},
    {"id": 0x3070, "text": "\x1AHérs ain geheimnis für reddend mik!\x04\x1AAin vegg det du kan zerstöten mit\x01 Gorons \"spekial krop\" skal\x01súnd different dan ain regular\x01vegg wenn du treffen et mit dín sverd.\x02", "box_type": 0},
    {"id": 0x3071, "text": "Sin du losend mik?\x01Am Ik frí til Gáe?\x0B\x02", "box_type": 0},
    {"id": 0x4000, "text": "\x1AÞese augkúlar sin so delikiús!\x01Tonight Ik skal kúk fried augkúlar \x01gegn fyrst tid in ain lang tid!\x01Uhoy hoi hú húi hoi!\x04\x1ASuch stór stuff! Bitte sagen \x01Dank dir til Kong Zora!\x01Eh? Wat?\x0B\x02", "box_type": 0},
    {"id": 0x4001, "text": "\x1AÞese sin für making \x05ABiggorons \x01Aug Dropar\x05@? Ó, hú disappointing!\x01Du skold have sagde so in  \x01fyrst setzen!\x0B\x02", "box_type": 0},
    {"id": 0x4002, "text": "\x1A\x0F!\x01Þet veg! Hú hú!\x0C(\x1AIk wonder wat \x05ASaria\x05@ ist dóend nú?\x01Hú om sker zurück til \x01skog sometime?\x02", "box_type": 0},
    {"id": 0x4003, "text": "\x1AWat sin du dóend? Du havst komen \x01ain lang veg til kregen op hér...\x0C(\x1ADu skold sé an \x05AKart \x01Underskerm \x05@sometimes.\x04\x1A\x0F, þet ist ain béutiful\x01sjó full de pure, klér vatn.\x04\x1AAn sjó bottom þar ist\x01ain \x05CVatn Tempel \x05@brukte til worşip \x01 vatn andear. \x05CZoras \x05@sin\x01guardians de tempel. Hú hú.\x04\x1A Zoras komen frá Zoras\x01Domain in norþést Hyrule. Ain\x01aqatik rake, sei sin longtime\x01allies de Hyrules Konglig Família.\x04\x1AIk hérd det nur Konglig Família\x01de Hyrule kan enter Zoras Domain...\x01Hú hú!\x04\x1AIk am auf mís veg zurück til \x05Akastel\x05@.\x01Wenn du vollen til komen mit mik, halten\x01auf til mís talons!\x02", "box_type": 0},
    {"id": 0x4004, "text": "Ik am auf mís veg zurück til \x05Akastel\x05@.\x01Wenn du vollen til komen mit mik, halten\x01auf til mís talons!\x02", "box_type": 0},
    {"id": 0x4005, "text": "\x1A...Huh?\x04\x1AEt sýnt als þar ist einwat\x01alrédi innan þet flaska.\x01Et ist ain \x05Abrev\x05@:\x04\x1A\x08\x06\x0C\"\x05EHelpen mik.\x01\x05@\x06\x0C\x05EIk am wéting für du innan\x01\x05@\x06\x0C\x05FLord Jabu-Jabus\x05E belli.\x01\x05@\x06\x18--\x05FRuto\x05@\x09\x04\x1A\x08\x06\x0C\x05EPS: Ne sagen mís faþer!\x05@\"\x09\x02", "box_type": 2},
    {"id": 0x4006, "text": "\x1AWer sin du?\x04\x1AWir sin \x05CZoras\x05@, prúd\x01aqatik folk!\x04\x1ASo...du sagen du havst sum \x01konnekçion mit Hyrules Konglig\x01Família... \x01Vel, wat dó du vollen frá uns?\x02", "box_type": 0},
    {"id": 0x4007, "text": "Wir sin gut an diving!\x01Hú om du?\x04Wenn du vollen til vesen ain meister diver,\x01forsöken \x05Adiving spel\x05@ an topp \x01de waterfall!\x01Have du tried et alrédi?\x02", "box_type": 0},
    {"id": 0x4008, "text": "\x1AZoras Fountain ist  \x01súrke de river.\x01\x05ALord Jabu-Jabu \x05@lives in  \x01fúntén.\x07@\x09\x02", "box_type": 0},
    {"id": 0x4009, "text": "Lord Jabu-Jabu ist patron deiti\x01de Zoras. \x05APrinsess Ruto\x05@ ist in \x01karge de preparing es méls, \x01morgn und naht.\x02", "box_type": 0},
    {"id": 0x400A, "text": "Wir Zoras alle serve stór \x01\x05AKong Zora\x05@.\x02", "box_type": 0},
    {"id": 0x400B, "text": "stór Kong Zora skold vesen in\x01 \x05AKonglig Chamber\x05@.\x02", "box_type": 0},
    {"id": 0x400C, "text": "Have du gesehen Lord Jabu-Jabu?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x400D, "text": "According til \"Legend de Zora,\"\x01 akt de útering ain \x05AFisk\x05@ til Lord \x01Jabu-Jabu skal maken du glad.\x02", "box_type": 0},
    {"id": 0x400E, "text": "Ó, det ist ne gut.\x04Alle wer komt kring hér \x01skold séen \x05ALord Jabu-Jabu\x05@ an \x01lést aingång!\x04Zoras Fountain ist bara beiond \x01Kong Zoras þrone. Det ist var\x01Lord Jabu-Jabu swims. Aber...\x04unless du havst Kong Zoras\x01permisçion, du ne kan Gáe til \x01Zoras Fountain.\x02", "box_type": 0},
    {"id": 0x400F, "text": "\x1AWir haven't fand \x05APrinsess Ruto\x01\x05@ok þótt sum de uns have \x01sérked als fjarr als \x05CHylia-Sjó\x05@....\x02", "box_type": 0},
    {"id": 0x4010, "text": "Wenn du vinden ein klues til\x01\x05APrinsess Rutos \x05@wherébúts,\x01skal du vise sen til Kong Zora?\x02", "box_type": 0},
    {"id": 0x4011, "text": "Alle de vatn in Hyrule flós\x01frá \x05CZoras Fountain\x05@.\x04Det vatn flós dur Zoras\x01River, welk eventualli rékes\x01\x05CHylia-Sjó \x05@til súþ.\x02", "box_type": 0},
    {"id": 0x4012, "text": "\x1AÓ--Ik have komen zurück til líf!\x04\x1AVar et du wer gereddet mik?\x01Ne vesen nervús!\x04\x1AEt sýnt als du havst ain hard tid\x01bréþing underwater.\x04\x1AAls ain expresçion de mís gratitude,\x01Ik grant du þet \x05Atunik\x05@. Mit þet,\x01du skal ne koke underwater.\x02", "box_type": 0},
    {"id": 0x4013, "text": "Prinsess Ruto havt gangen til Sjó \x01Hylia und havt ne komen zurück...\x01Ik am so worried...aftur!\x02", "box_type": 0},
    {"id": 0x4014, "text": "\x1AOoh...\x01Þet ist... vel... hmmm...\x01Hmmm... \x05AAug dropar\x05@...\x04\x1ADu might sagen wir have sen,\x01du might sagen wir ne...\x01Wir dó have ingredients.\x04\x1AWenn du nim \x05Aingredients \x05@til \x01doktor an sjó laboratori, er\x01kan maken dropar für du.\x04\x1AAber Du mos haven til deliver sen\x01frisk...\x07@\x15\x02", "box_type": 0},
    {"id": 0x4015, "text": "Kan du maken et \x05Aför sei\x01skarnen\x05@?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4016, "text": "Dan du denken þei'll skarnen \x01för du kan kregen þar?\x01Et ist ne det fjarr wenn du maken  \x01konnekçion auf horsebak...\x02", "box_type": 0},
    {"id": 0x4017, "text": "\x1AHoot hút!\x0C(\x1A\x0F, du sé als \x01du sin getting meir komfortable\x01in dín role als adventurer.\x04\x1AIk denken Prinsess Zelda ist \x01wéting für du til Besoek elar aftur.\x04\x1ADu alrédi have \x05AGoronens Rubin\x05@,\x05A\x01\x05@ne du?\x02", "box_type": 0},
    {"id": 0x4018, "text": "Hello þar, son. Ik am resérking \x01 prokess de making medikine af \x01mixing Hylia-Sjós vatn mit \x01variús unusual kompúnds.\x04Perhaps du havst met det alt fraua \x01frá trank búð...ela ist als \x01ain student de mís...\x01Hó hó hó!\x02", "box_type": 0},
    {"id": 0x4019, "text": "\x08Ó, wó!\x09\x04\x1AIk haven't gesehen ain \x05AAugfrosk\x05@ \x01als þet weil Zoras Domain froze\x01yfir!\x0B\x02", "box_type": 0},
    {"id": 0x401A, "text": "Ó, mís dér, swít \x05APrinsess Ruto\x05@...\x01Var havt ela gangen?\x01Ik am so worried...\x02", "box_type": 0},
    {"id": 0x401B, "text": "\x1AHó, þet brev! \x01Et ist frá \x05APrinsess Ruto\x05@!!\x04\x1AHmmm...lat uns séen...\x01Elas innan Lord Jabu-Jabu?\x01Det ist ne mulig!\x04\x1AUnser guardian god, \x05ALord Jabu-Jabu\x05@,\x01vold aldrei ét mís dér Prinsess\x01Ruto!\x04\x1AAber weil det stranger, \x05AGanondorf\x05@,\x01kom hér, Lord Jabu-Jabu havt \x01gevesen ain klein grän kring \x01gills...\x04\x1A evidenke síms klér.\x01De kúrse, du skal Gáe vinden Ruto.\x01Du kan pasar dur hér til  \x01altar de Lord Jabu-Jabu.\x04\x1AIk skal halten þet brev. Du halten  \x01\x05Aflaska \x05@et var in. Nim et \x01respektfulli!\x07@\x1C\x02", "box_type": 0},
    {"id": 0x401C, "text": "Bitte vinden mís dér \x05APrinsess Ruto\x05@\x01immediateli... Zora!\x02", "box_type": 0},
    {"id": 0x401D, "text": "\x08\x05DDu ne kan bréþe underwater!\x01Wenn du beginnen koking, nim fram\x01de \x05@búts\x05D!\x05@\x09\x0E<\x02", "box_type": 2},
    {"id": 0x401E, "text": "\x08\x066Ooooh Noooooo!\x09\x02", "box_type": 0},
    {"id": 0x401F, "text": "\x1AOhhh, Ik am revived...\x01Var et du wer gereddet mik?\x01Ne vesen so nervús!\x04\x1AIk skal geven du ain \x05CZora-Tunika \x05@als\x01ain tegn de mís þanks. Wenn du havst\x01þet, du kan... Wat?!\x04\x1ADu alrédi have ain? Du sin \x01Klar für aniþing, sin ne du!\x04\x1AMit mís hértfelt þanks...hú \x01om ain KISS?! Wat? Du ne \x01vollen et?! Ó vel...\x04\x1AWenn du ne vollen mís belónungar, du\x01kan hlusten til mís trúbles...\x07@\x13\x02", "box_type": 0},
    {"id": 0x4020, "text": "Ik am ain \x05CZora\x05@. Have du gesehen ain \x01pretti Zora fraua kring hér?\x02", "box_type": 0},
    {"id": 0x4021, "text": "Ik am ain \x05CZora\x05@. Have du gesehen\x01aniþing strange in sjó?\x01 river tragt manig tingar \x01inn þet sjó!\x02", "box_type": 0},
    {"id": 0x4022, "text": "\x1ADu...\x08Du sin late!\x09\x01\x08Wat nám du so lang?\x09\x01Du sin \x08useless!\x09\x04\x1AIk var bara loneli, det ist alle...\x01Bara ain klein!!\x02", "box_type": 0},
    {"id": 0x4023, "text": "\x1A\x08Ik var skared...\x09\x01\x08Ain klein!\x09 Bara ain klein!!\x02", "box_type": 0},
    {"id": 0x4024, "text": "\x1A\x0F!\x01\x0F!\x02", "box_type": 5},
    {"id": 0x4025, "text": "\x1A\x08Du!\x09\x01Du lúked kúl...kúler dan Ik \x01þúght du vold, aniwé... \x01\x08Bara ain klein!\x09\x04\x1AVel, aniwé, du gereddet mik, so Ik \x01guess Ik skal belónung du.\x04\x1AWat dó du wiş? Bara sagen mik...\x01\x01\x1B\x05BIk vollen det Andlig Stein.\x01Keinwat sannlig...\x05@\x02", "box_type": 0},
    {"id": 0x4026, "text": "\x1ADu mén Andlig Stein de\x01Vatn, \x05CZoras Safir\x05@, ne du?\x07@'\x02", "box_type": 0},
    {"id": 0x4027, "text": "\x1AMís moþer gav et til mik und sagde \x01Ik skold geven et nur til mar \x01wer skal vesen mís husband. Du might\x01kall et Zoras Engagement Ring!\x04\x1A\x06E\x08Rétt vel!\x09\x04\x1AIk skal geven du mís most prekiús\x01possesçion: \x01Zoras Safir!\x02", "box_type": 0},
    {"id": 0x4028, "text": "Ne sagen mís faþer...\x02", "box_type": 0},
    {"id": 0x4029, "text": "\x1AHeeheehee... Ne vesen şi.\x04\x1AIk kan sagen wat du sin þinking...\x07@'\x02", "box_type": 0},
    {"id": 0x402A, "text": "Ik vollen til Kaup ain Fisk, aber sei sin\x01ain klein ok expensive...\x04Ik have non koike aber til katk ain\x01de Fiskes det ist swimming\x01kring út þar.\x02", "box_type": 0},
    {"id": 0x402B, "text": "Ó, \x0F!\x01So, du gereddet Prinsess, eh?\x01Ik sannlig apprekiate et!\x02", "box_type": 0},
    {"id": 0x402C, "text": "Dóde mís most prekiús possesçion\x01helpen du in dín Quest? Heehee!\x02", "box_type": 0},
    {"id": 0x402D, "text": "Ó, hi \x0F!\x01Du sin alle Prinsess Ruto skal talen\x01om lateli!\x02", "box_type": 0},
    {"id": 0x402E, "text": "Ó, et ist du, \x0F!\x01Thanks til du, Lord Jabu-Jabu ist\x01aftur normal!\x02", "box_type": 0},
    {"id": 0x402F, "text": "\x1AWir Zoras alle respekt stór\x01Kong Zora! Er havt digniti de\x01ain kong. Ó iéh, er dót.\x04\x1A grand Kong Zora havt ain \x01Prinsess named \x05ARuto\x05@. Elas ain\x01nur kild.\x04\x1AElas ok ain wild tomboi, und et\x01síms als elas alwés kausing\x01 Kong ain mengd de trúble!\x07@\x0B\x02", "box_type": 0},
    {"id": 0x4030, "text": "\x1AHér et ist.\x04\x1AÞet medikine dót ne have ein\x01preservatives in et. So et \x05Askal ne \x01last lang \x05@an þet temperature.\x04\x1ARennen als fast als du kan til \x01Dauðfjall. Du sin ung--\x01du kan dó et!\x02", "box_type": 0},
    {"id": 0x4031, "text": "\x1AHú hú! Sýnt als du havst gotten\x01bigger und stronger alrédi,\x01\x0F!\x04\x1ABara ahéd lies \x05CZoras Domain\x05@. \x01 Zoras serve Hyrules Konglig \x01Família af protekting þet vatn \x01súrke.\x04\x1ASer dyr skal ne opnen für \x01anione exkept de wer have\x01sum konnekçion mit Konglig \x01Família.\x04\x1Alat sen hören \x05Amelodi de  \x01Konglig Família\x05@!\x01Hooo hú húút!\x02", "box_type": 0},
    {"id": 0x4032, "text": "Wenn du komen zurück näst tid, \x01ne vergessen til bring mik ain \x01súvenir!\x02", "box_type": 0},
    {"id": 0x4033, "text": "\x1ADu fand Prinsess Ruto!\x01Nú Kong Zora skal geven du  \x01\x05CAndlig Stein de Vatn\x05@...\x01Vel, kannski.\x04\x1AHuh?\x02", "box_type": 2},
    {"id": 0x4034, "text": "\x1AElar most prekiús possesçion?\x01Du ne weten wat elas talking\x01om, aber du havst gesamlt twei \x01Andlig Steinar! Nur ain til Gáe!\x02", "box_type": 2},
    {"id": 0x4035, "text": "\x1AElar most prekiús possesçion?\x01Du ne weten wat elas talking\x01om, aber du havst finalli gesamlt\x01alle þri Andlig Steinar!!\x04\x1AGáe zurück til séen Prinsess Zelda!\x02", "box_type": 2},
    {"id": 0x4036, "text": "\x1AWir mít aftur, \x0F...\x02", "box_type": 0},
    {"id": 0x4037, "text": "\x1AÞet ís ist kréted af ain ond\x01fluk... monster in \x05CVatn\x01Tempel \x05@ist súrke de fluk.\x04\x1AUnless du şut fram súrke, \x01þet ís skal aldrei melt....\x04\x1AWenn du havst kúrage enúgh til \x01konfront danger und redden \x01 Zoras, Ik skal ték du  \x01melodi det léds til tempel.\x02", "box_type": 0},
    {"id": 0x4038, "text": "\x1ATid passes, folk move....\x01Als ain rivers fló, et aldrei ends...\x04\x1AAin kildiş hug skal turn til\x01noble ambiçion... Ung líben skal\x01werden díp affekçion... klér \x01vatns surfake reflekts gróþ...\x04\x1ANú hlusten til \x05CSerenade de \x01Vatn\x05@ til reflekt upon dikself....\x02", "box_type": 0},
    {"id": 0x4039, "text": "\x1AWenn du kom hér til mít  \x01Zoras, du wasted dín tid...\x01Þet ist alle þar ist...\x04\x1AMit ain exkepçion, Zoras \x01sin nú séled under þet þik \x01ís şít...\x04\x1AIk managed til reskue Zora\x01prinsess frá under ís, aber... \x01ela lét til hövd gegn \x05CVatn \x01Tempel\x05@...\x02", "box_type": 0},
    {"id": 0x403A, "text": "Wenn du vollen til Kaup Fisk, Du mos haven\x01ain kar til zetten sen in.\x0B\x02", "box_type": 0},
    {"id": 0x403B, "text": "Du sagen du vollen til Kaup ain \x05CZora\x01Tunic\x05@? Det tunik ist gemakt de \x01best material, und ist þerefore\x01exkídingli expensive!\x04In fakt, Ik am afréd nur det \x05Ameir\x01rik família in Kakariko By \x05@kan\x01afford þet gut garment...\x0B\x02", "box_type": 0},
    {"id": 0x403E, "text": "\x1AÓ...du... Wenn Ik am rétt...\x01\x0F?!\x04\x1ADu sin \x0F, sin ne\x01du?\x04\x1AEt ist mik, dín fiankée, \x05CRuto\x05@!\x01Prinsess de Zoras!\x04\x1AIk aldrei vergat vós wir\x01gemakt til elk ander sevin ár \x01ago!\x04\x1ADu sin ain terrible mar til have \x01kept mik wéting für þese sevin\x01lang ár...\x04\x1AAber nú ist ne tid til talen \x01om líben...\x04\x1AIk am viss Du havst alrédi gesehen et!\x01Zoras Domain--totalli frozen!\x04\x1AAin ung mar named \x05ASheik\x05@ gereddet \x01mik frá under ís...\x04\x1AAber mís faþer und ander \x01Zoras have ne\x14\x02...iet...\x14\x00\x04\x1AIk vollen til redden sen alle!\x01Ik vollen til redden Zoras Domain!\x04\x1ADu! Du havst til helpen mik!\x01Þet ist ain reqest frá mik, \x01fraua wer ist sker til vesen dín\x01wife!\x04\x1A\x0F, du havst til \x01helpen mik zerstöten ond monster\x01in Tempel, OK?!\x04\x1AInnan Vatn Tempel, þar sin \x01\x05Aþri setzt\x05@ var du kan \x01kange vatn level.\x04\x1AIk skal léd veg.\x01Follow mik, snellig!!\x02", "box_type": 0},
    {"id": 0x403F, "text": "\x1A\x0F! Sé út!\x01Det ist ne normal vatn yfir \x01þar!\x02", "box_type": 0},
    {"id": 0x4041, "text": "\x1A\x0F...\x04\x1AIk vold have expekted non less\x01frá mar Ik kose til vesen mís\x01husband.\x04\x1AZoras Domain und es folk\x01skal eventualli teruggeven til ser\x01original state.\x02", "box_type": 0},
    {"id": 0x4042, "text": "\x1Awenn du séest Sheik, \x01bitte geven en mís þanks, OK?\x0EZ\x02", "box_type": 5},
    {"id": 0x4043, "text": "\x1ADóde Ruto vollen til þank mik?\x04\x1AIk séen....\x04\x1AWir have til teruggeven péke til \x01Hyrule für elar sake, ok. \x01Ne wir?\x02", "box_type": 0},
    {"id": 0x4045, "text": "Ah, Ik séen...\x01Prinsess Ruto ging til Vatn\x01Tempel...\x02", "box_type": 0},
    {"id": 0x4046, "text": "\x1AAls ain belónung...\x01Ik grant mís eternal líben til du.\x04\x1AVel, det ist wat Ik vollen til sagen, \x01aber Ik ne denken Ik kan úter det\x01nú.\x02", "box_type": 0},
    {"id": 0x4047, "text": "\x1APrinsess Zelda... Elas alive. Ik kan\x01sense et...so ne vesen diskúraged.\x02", "box_type": 0},
    {"id": 0x4048, "text": "\x08\x06?Keeeyaaaah!\x01\x06\x0FWat ist þet?! Ain oktopus?!\x09\x0E<\x02", "box_type": 0},
    {"id": 0x4049, "text": "\x1AIk have til vakt Vatn \x01Tempel als \x05CSage de Vatn\x05@...\x04\x1AUnd du... Du sin sérking gegn\x01prinsess, \x05AZelda\x05@?\x04\x1AHah!\x01Du ne kan hide aniþing frá mik!\x02", "box_type": 0},
    {"id": 0x404A, "text": "\x1AIk kan sagen det keinwat skal stoppen\x01du in dín Quest für justike und \x01péke... Du mos nim þet \x01\x05CMedallion\x05@... Nim et respektfulli!\x02", "box_type": 0},
    {"id": 0x404B, "text": "\x1ADu! Wer sin du?!\x04\x1AIk am \x05ARuto\x05@, Prinsess de Zoras.\x04\x1A\x08Wat?!\x09\x01Sin du séing mís faþer asked \x01du til komen hér til redden mik?\x04\x1AIk vold \x08aldrei\x09 ask anione til dó suk ain\x01ting!\x04\x1A\"Brev in ain Flaska?\" Ik have\x01\x08non idé\x09 wat du sin talking om!\x04\x1AMís faþer ist worried om mik?\x04\x1AIk ne \x08kare!\x09\x04\x1AAnyway, Ik ne kan Gáe home rétt nú.\x01Und du... \x08Kregen út de hér!\x09\x01\x08Understand?!\x09\x02", "box_type": 0},
    {"id": 0x404C, "text": "\x1ASin du still hanging kring hér?\x01Ik sagde du til Gáe bort!\x04\x1AIk am OK. Ik have gevesen sker innan\x01Lord Jabu-Jabus Buk weil Ik var\x01klein, aber...\x04\x1ALord Jabu-Jabu ist meir strange \x01todé...\x04\x1AÞar sin elektrified jellifisk und\x01strange holar kring...\x04\x1AAuf topp de det, mís prekiús stein \x01var...aber...\x01\x08Det ist none de dín business!\x09\x01Anyway...\x04\x1ADu! \x08Gáe home nú!\x09\x01\x08Understand?!\x09\x0B\x02", "box_type": 0},
    {"id": 0x404D, "text": "\x1ADu sin det worried om mik?\x04\x1ADan Ik skal geven du honor\x01de karriing mik!\x04\x1A\x08However\x09...Ik skal ne laten bis Ik \x01vinden ting Ik am séend für.\x01Du vold beter believe mik!\x0B\x02", "box_type": 0},
    {"id": 0x404E, "text": "\x08Hú inkonsiderate!\x09\x01Hú konde du laten mik bak?! \x01Wenn du sin ain mar, akt als ain! \x01Nim responsibiliti!\x0B\x02", "box_type": 0},
    {"id": 0x404F, "text": "\x1A\x08Det ist et!\x09\x01Det ist wat Ik have gevesen séend für!\x01Werfen mik op þar! \x01Onto platfórm!\x02", "box_type": 0},
    {"id": 0x4050, "text": "\x1A\x08Prinsess Ruto kreeg  \x01\x05CAndlig Stein\x05@!\x09\x01\x14\x02Aber\x14\x00 warüm Prinsess Ruto?\x02", "box_type": 2},
    {"id": 0x4051, "text": "\x1AÓ mís gúdness!\x01Ik finalli fand... \x01Mís moþers stein...\x04\x1AIk kreeg meir upset wenn Lord Jabu-\x01Jabu swallóed et...\x04\x1AMeðan Ik var fíding en, er\x01suddenli swallóed mik! Ik var \x01so surprised Ik dropped et innan...\x04\x1AAber, nú det Ik have fand et, \x01Ik ne mos til vesen in hér \x01animore!\x02", "box_type": 0},
    {"id": 0x4052, "text": "So, nim mik home, rétt nú!\x02", "box_type": 0},
    {"id": 0x4053, "text": "Diving Spel 20 Rubinar\x01Vollen til spelen?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4054, "text": "\x08\x06?OKAY!\x09\x04Pick op alle Rubinar Ik werfen \x01frá hér. Du havst nur ain limited\x01amúnt de tid!\x04Wenn du pik sen alle op, \x01komen zurück hér! Ik skal geven du\x01einwat meir nike!\x0B\x02", "box_type": 0},
    {"id": 0x4055, "text": "\x1A\x08Hé! Congratulations!\x09\x01Ik have kreeg einwat \x01meir nike für du!\x01Komen und kregen et!\x0B\x02", "box_type": 0},
    {"id": 0x4056, "text": "\x1AWat ain grakeful dive!\x01Nú, bitte nim þet!\x04\x1AÞet ist ain \"\x05Askal\x05@\" de unser kind.\x01Mit þet, du kan dive meir\x01díper under vatn.\x0B\x02", "box_type": 0},
    {"id": 0x4057, "text": "\x1AAls vatn rises, ond \x01ist vanişing frá sjó...\x01\x0F, du dóde et!\x02", "box_type": 0},
    {"id": 0x4058, "text": "\x1AIk...believe det du sin sker til \x01redden þet verden...\x02", "box_type": 0},
    {"id": 0x4059, "text": "\x1ASé an det, \x0F...\x04\x1ATogether, du und Prinsess Ruto \x01zerstört ond monster!\x04\x1AAingång aftur, sjó ist filled mit\x01pure vatn. Alle ist als et var hér.\x02", "box_type": 0},
    {"id": 0x405A, "text": "\x08\x06Q\x05ABEGINNEN!\x05@\x09\x0B\x02", "box_type": 0},
    {"id": 0x405B, "text": "Gáe yfir falls gegn ain şortkut.\x0B\x02", "box_type": 0},
    {"id": 0x405C, "text": "Nim als meir als du vollen für \x0120 Rubinar. Vollen til spelen?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x405D, "text": "\x08Hé! Congratulations!!\x09\x0B\x02", "box_type": 0},
    {"id": 0x405E, "text": "\x1AChomp komp komp...\x01Hú om sum \x05AMagikbónaar\x05@?\x01Sei sin ne selling meir vel...\x04Hú om...\x01\x05A10 Rubinar \x05@ für ain del?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x405F, "text": "\x1AChomp komp komp...\x01Hú om sum \x05AMagikbónaar\x05@?\x01Vel, þei're ne det elsklig iet.\x04Hú om...\x01\x05A20 Rubinar \x05@ für ain del?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4060, "text": "\x1AChomp komp komp...\x01Hú om sum \x05AMagikbónaar\x05@?\x01Sei sin getting til vesen qite \x01elsklig...\x04\x05A30 Rubinar\x05@ für ain del.\x01Hú om et?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4061, "text": "\x1AChomp komp komp...\x01Hú om sum \x05AMagikbónaar\x05@?\x01Þei're alle rage!\x04\x05A40 Rubinar\x05@ für ain del.\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4062, "text": "\x1AChomp komp komp...\x01Wir have elsklig \x05AMagikbónaar\x05@!\x01Du skal regret et wenn du ne Kaup \x01sen nú!\x04\x05A50 Rubinar\x05@ für ain del.\x01(Bara für nú.)\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4063, "text": "\x1AChomp komp komp...\x01Þese sin super-elsklig \x01\x05AMagikbónaar\x05@! In kase du sin \x01wondering, þei'll sún vesen sold út!\x04Super prike!\x01\x05A60 Rubinar\x05@ für ain del!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4064, "text": "\x1AChomp komp komp...\x01Wir have super-rare \x01\x05AMagikbónaar\x05@! Þet konde vesen dín\x01last kanke!\x04Special prike!\x01\x05A70 Rubinar\x05@ für ain del!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4065, "text": "\x1AChomp komp komp...\x01Wir have legendari \x01\x05AMagikbónaar\x05@! Ik skal seljen sen nur \x01til du!\x04Super prike!\x01\x05A80 Rubinar\x05@ für ain del!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4066, "text": "\x1AChomp komp komp...\x01Dó du vollen...\x05AMagikbónaar\x05@?! \x01Sei sin ne kép, aber...dó du\x01still vollen sen?\x04Ik ne kan lat sen Gáe für less dan\x01\x05A90 Rubinar\x05@ apieke!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4067, "text": "\x1AChomp komp komp...\x01Wir have...\x05AMagikbónaar\x05@! \x01Dó du vollen sen...huh? Huh?\x04\x05A100 Rubinar\x05@ für ain del!\x01Keyahahah!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4068, "text": "Ó vel...\x01Chomp komp...\x02", "box_type": 0},
    {"id": 0x4069, "text": "Du ne have enúgh monei.\x01Ik ne kan seljen sen til du.\x01Chomp komp...\x02", "box_type": 0},
    {"id": 0x406A, "text": "Sette ain bóna til \x05F¡ \x05@und Bruk et auf\x01 dirt rétt hér.\x02", "box_type": 0},
    {"id": 0x406B, "text": "Ó, ok mal! Wir sin sold út!\x01Chomp komp...Wat?\x01Ó, þese bónaar sin ne für sale!\x02", "box_type": 0},
    {"id": 0x406C, "text": "Wenn du vollen til plant bónaar, Gáe\x01kring und sé für mjúk jörd.\x01Chomp komp komp.\x02", "box_type": 0},
    {"id": 0x406D, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A1 meter\x05@ bara nú. Aber Ik wúldn't \x01kall det ain rél dive.\x02", "box_type": 0},
    {"id": 0x406E, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A2 meters\x05@ bara nú. Aber Ik wúldn't \x01kall det ain rél dive.\x02", "box_type": 0},
    {"id": 0x406F, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A3 meters\x05@ bara nú. Aber Ik wúldn't \x01kall det ain rél dive.\x02", "box_type": 0},
    {"id": 0x4070, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A4 meters \x05@bara nú. Still ne \x01díp enúgh!\x02", "box_type": 0},
    {"id": 0x4071, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A5 meters \x05@bara nú. Still ne \x01díp enúgh!\x02", "box_type": 0},
    {"id": 0x4072, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A6 meters\x05@ bara nú. Du skold vesen\x01able til dive díper!\x02", "box_type": 0},
    {"id": 0x4073, "text": "Du möge ne have notiked, aber Ik have\x01gevesen watking du. Du dove \x01\x05A7 meters\x05@ bara nú. Du skold vesen\x01able til dive díper!\x02", "box_type": 0},
    {"id": 0x4074, "text": "\x1ADu möge ne have notiked, aber Ik have\x01gevesen watking du. Du \x05Atúked \x01 bottom \x05@bara nú. Fantastic!\x01Ik skal geven þet til du!\x02", "box_type": 0},
    {"id": 0x4075, "text": "Dín diving ist best in  \x01verden. Warüm ne du dive til  \x01bottom de Hylia-Sjó?\x02", "box_type": 0},
    {"id": 0x4076, "text": "Mís namn ist \x05APierre\x05@, wandering\x01skarekró. Actually, Ik wiş Ik konde\x01wander til sé für súl-moving\x01súnds, aber Ik am kind de stuk hér.\x02", "box_type": 0},
    {"id": 0x4077, "text": "Fantastic tune! Et túkes mís \x01hert!\x0B\x02", "box_type": 0},
    {"id": 0x4078, "text": "Wenn du komen op mit ain nike sang,\x01komen zurück und lat mik hören et!\x0B\x02", "box_type": 0},
    {"id": 0x4079, "text": "Det sang du pléed für mik still\x01stés in mís hert. lat uns hören et\x01aftur!\x0B\x02", "box_type": 0},
    {"id": 0x407A, "text": "Det sang du pléed für mik \x01stés in mís hert!\x0B\x02", "box_type": 0},
    {"id": 0x407B, "text": "Vel, dó du vollen til Gáe Fisking \x01für \x05A20 Rubinar \x05@?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x407C, "text": "Ó, non! Du ne have ain \x05ARumble \x01Pak\x05@! Mit ain Rumpelpak, du kan\x01füle vibraçions de ain Fisk auf\x01dín haken.\x04Þet tid, non rumble für du!\x0B\x02", "box_type": 0},
    {"id": 0x407D, "text": "Wow! Du havst ain \x05ARumpelpak\x05@!\x01Today, du kan füle vibraçion,\x01ung mar!\x0B\x02", "box_type": 0},
    {"id": 0x407E, "text": "Shucks! Du ne have enúgh \x01monei.\x02", "box_type": 0},
    {"id": 0x407F, "text": "OK, hlusten op!\x04Walk op til vatns kant und\x01Drukk \x05D¤\x05@ til sé an ain Fisk.\x04Meðan séend an ain Fisk, du kan \x01kasten dín line mit \x05B \x05@. Drukk \x05C\x9F\x01\x05@til brake line.\x04Wenn lure dropar inn  \x01vatn, du kan wiggle et mit \x05Dª\x05@.\x01Wenn du sin ain novike, du kan ok\x01Bruk \x05B \x05@.\x04Reel in dín lure mit \x05C\x9F\x05@. Halten \x01ned \x05C\x9F\x05@ und \x05D£ \x05@til ríl et in \x01faster.\x04Wenn du füle ain treffen, Drukk \x05C\x9F\x05B \x05@und\x01\x05Dª ned \x05@til sette haken.\x01Eftir det, ríl et in mit \x05C\x9F\x05@.\x04Dó du understand?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4080, "text": "Ik am so generús, Ik skal lat du Fisk\x01für als lang als du vollen. However,\x01du kan halten nur ain Fisk.\x04 biggest Fisk ever kaught hér\x01weighed \x05A\x1D púnds\x05@.\x04Eftir du kasten, du kan kange\x01dín view mit \x05D¤\x05@.\x04\x06Alat uns Fisk!\x0B\x02", "box_type": 0},
    {"id": 0x4081, "text": "Wah ha haah!\x01Dóde du sette haken af pressing\x01\x05C\x9F\x05@ und \x05Dª ned\x05@?\x02", "box_type": 0},
    {"id": 0x4082, "text": "Hé, wat happened?\x01Du verloren et!\x0E<\x02", "box_type": 0},
    {"id": 0x4083, "text": "Vel, vel...et ist om \x05A\x1D púnds\x05@. \x01Dó du vollen til halten et?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4084, "text": "Wat dó du vollen?\x01\x1C\x05BWeigh mís Fisk.\x01lat uns talen om einwat.\x01Ik vollen til qit.\x05@\x02", "box_type": 0},
    {"id": 0x4085, "text": "Passion alone skal ne katk du \x01manig Fisk. Ik am seriús!\x02", "box_type": 0},
    {"id": 0x4086, "text": "\x06KWHOA!\x04Þet Fisk ist huge! Et sýnt als ain \x01nüv rekord! Et weighs an lést \x01\x05A\x1D púnds\x05@! Seriously! \x01OK, hér ist dín pris!\x0B\x02", "box_type": 0},
    {"id": 0x4087, "text": "Wat? \x01Wat sin du dóend til mik?!\x0E<\x02", "box_type": 0},
    {"id": 0x4088, "text": "Hé, ung mar! Ne du havst \x01aniþing important du skold vesen\x01dóend?\x04Wat? Sin du séing et ist meir \x01fun til spelen hér?\x04Ik have gesehen manig folk ruin ser\x01lives mit det kind de attitude.\x01Ik am seriús!\x01Ó vel...\x02", "box_type": 0},
    {"id": 0x4089, "text": "\x08 biggest Fisk ever kaught in\x01þet pond weighed \x1D púnds.\x01 angler: \x0F\x09\x02", "box_type": 2},
    {"id": 0x408A, "text": "Dó du vollen til kontinue Fisking?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x408B, "text": "Vel, et weighs \x05A\x1D púnds\x05@...\x01Ne mal, aber þar sin bigger\x01Fisk in þar!\x0B\x02", "box_type": 0},
    {"id": 0x408C, "text": "Hé, k'mon! Du ne have ain Fisk!\x01Shucks!\x0B\x02", "box_type": 0},
    {"id": 0x408D, "text": "Du vollen til forsöken ander lure?\x01Wat sin du talking om? Sin\x01du so selfisk?\x04Ne du weten alt séing,\x01\"Ain stór Fiskerman aldrei kúses\x01es ón lure?\"\x02", "box_type": 0},
    {"id": 0x408E, "text": "Wat? Vilt Du weten sum \x01Fisking geheimnisar? Ik ne kan sagen du\x01ein. Sei sin kompani geheimnisar.\x01Seriously!\x02", "box_type": 0},
    {"id": 0x408F, "text": "Wat? Du vollen til weten wenn Ik am ain \x01gut Fiskerman?\x04De kúrse Ik am! Ik am ain alt pro!\x01Dó du weten wat ain pro ist?\x01Ik am telling du sannheit!\x02", "box_type": 0},
    {"id": 0x4090, "text": "\x08Rules und Regulations\x09\x01\x081. Ne Bruk sinking lures.\x012. Ne litter.\x013. Walk qietli.\x09\x04\x084. Ne kasten an anione.\x09\x02", "box_type": 1},
    {"id": 0x4091, "text": "Wow! Þet ist ain rél lunker!\x01lat uns séen...et weighs\x01\x05A\x1D púnds\x05@!\x04Dó du vollen til halten et?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4092, "text": "Komen zurück wenn Du havst older!\x01 Fisk skal vesen bigger, ok...\x01Vel, kannski.\x02", "box_type": 0},
    {"id": 0x4093, "text": "\x1AHé, mister! Ik erinnern du!\x01Et ist gevesen ain lang tid!\x04\x1AHú manig ár havt et gevesen?\x01Sevin ár?! Wat have du\x01gevesen dóend alle þet tid?!\x04\x1ADu sin mís nur kustomer. Ik am \x01nästum út de business! Seriously!\x01Auf topp de det, mís hér...\x04\x1AUh, Ik mén, aldrei hug...\x04\x1AVel, dó du vollen til Gáe Fisking?\x01Et kostet nur \x05A20 Rubinar \x05@!\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x4094, "text": "Wat?\x04Du vollen til Gáe Fisking in ain \x01different Fisking pond?!\x01Wat sin du talking om?\x04Ik skal Gáe út de business wenn du Gáe\x01somewhere else!\x01Ik am seriús!\x02", "box_type": 0},
    {"id": 0x4095, "text": "Wat?\x04Du vollen til weten warüm Ik am \x01skratking alle tid?\x01Wat sin du talking om?\x04Actually, Ik have non idé.\x01Ik am seriús!\x02", "box_type": 0},
    {"id": 0x4096, "text": "Wat?\x04Sin du triing til sagen mik du\x01ne kan séen Fisk bekabruk \x01vatn ist klúdi?\x04Wat sin du talking om?\x01Þet tid de dé makt für \x01Fisking an es best!\x04Du kan haken ain Fisk út de \x01blá, wenn du lést expekt et.\x01Nú det ist exkiting!\x04Ik am seriús. Sannlig, Ik am!\x02", "box_type": 0},
    {"id": 0x4097, "text": "Hé, wat sin du dóend?\x01Ik sagde du ne til dó det!\x01Du sin terrible!\x01Seriously!\x04Geven mik zurück mís hat!\x01\x01\x1B\x05BOK\x01Non veg\x05@\x02", "box_type": 0},
    {"id": 0x4098, "text": "Wat? Huh? Ó?\x01Ik denken Fisk du alrédi\x01kept var bigger dan þet ain...\x04Dó du still vollen til halten et?\x01\x01\x1B\x05BNon, Ik ne vollen et\x01Ja, Ik vollen til halten et aniwé\x05@\x02", "box_type": 0},
    {"id": 0x4099, "text": "Gosh! Det ist ain strange Fisk du\x01kaught þar! Auf topp de det, et\x01weighs \x05A\x1D púnds\x05@!\x04Wat dó du vollen til dó mit et?\x01\x01\x1B\x05BHalten et aniwé\x01Ik ne vollen et\x05@\x02", "box_type": 0},
    {"id": 0x409A, "text": "Wow!\x04Ist þet wat Ik denken et ist?\x01Astonishing!\x01Du snagged ain \x05Asinking lure\x05@!\x04Wat dó du vollen til dó mit et?\x01\x01\x1B\x05BBruk et nú.\x01Kregen rid de et.\x05@\x02", "box_type": 0},
    {"id": 0x409B, "text": "Vel, vel...\x04WÓ! Wat ain rare Fisk!\x01Þet ist ain \x05AHyrule Loach\x05@!\x04Für þet Fisk, size dót ne \x01matter. Ik skal geven du þet \x01pris!\x0B\x02", "box_type": 0},
    {"id": 0x409C, "text": "Recently, number de þese\x01Fisk havt dekrésed tremendúsli,\x01so Ik am sker til Los þet ain.\x0B\x02", "box_type": 0},
    {"id": 0x409D, "text": "\x08Rules und Regulations\x011. Ne Bruk sinking lures.\x012. Ne litter.\x013. Walk qietli.\x09\x02", "box_type": 1},
    {"id": 0x409E, "text": "Hé! Hé!\x01Du ne kan nim rod út de\x01hér!\x04Wenn du qit Fisking, teruggeven \x01 rod til kúnter.\x01Ik am seriús!\x02", "box_type": 0},
    {"id": 0x409F, "text": "Ó mís goş!\x01Þet Fisk ist gigantik!!\x04Ain Fisk þet grós ne kan ok fit\x01auf skerm, und Ik ne kan weigh et\x01akkurateli, aber et sýnt als et ist\x01om \x05A\x1D púnds\x05@!!\x04Du skal vollen til halten þet ain,\x01rétt?\x01\x1B\x05BHalten et\x01Ne halten et\x05@\x02", "box_type": 0},
    {"id": 0x40A0, "text": "Hé, babi!\x01Ik am \x05ABonooru\x05@, skarekró!\x01Du havst probabli hérd om mís\x01fantastik memori!\x04Wenn du havst ain nüv tune til spelen,\x01bló et!\x04Þet ist sang du túted last \x01tid, babi!\x04Treffen et!\x0B\x02", "box_type": 0},
    {"id": 0x40A1, "text": "Ik am \x05ABonooru\x05@, skarekró\x01musikal genius!\x01Ik hören ain sang aingång, und Ik aldrei\x01vergessen et, babi!\x02", "box_type": 0},
    {"id": 0x40A2, "text": "Spelen usual tune til kall\x01Pierre!\x01Wenn er ist nérbi, he'll komen út til\x01helpen du, babi!\x02", "box_type": 0},
    {"id": 0x40A3, "text": "Hé! Sin ne du Féa buddi Ik\x01met ain lang tid ago?\x01Wow, du grew, dude!\x04Vel, hérs dín sang...\x04Wat?\x04Non, Ik aldrei vergessen!\x01Du, du sin ain wer vergat...\x01sin ne du? Wenn du havst ain \x01Okarina, spelen det sang, babi!\x02", "box_type": 0},
    {"id": 0x40A4, "text": "Whoa! Du havst ain okarina!\x01Hé, warüm ne du lé ain tune\x01auf mik mit et, babi?!\x0B\x02", "box_type": 0},
    {"id": 0x40A5, "text": "Vel...ne mal!\x01Ik skal erinnern et für du \x01aniwé!\x04Ik ne mén Ik kan erinnern nur\x01acht notes, aber lat uns bara kut et\x01rétt þar für nú, babi!\x0B\x02", "box_type": 0},
    {"id": 0x40A6, "text": "Spelen et als det und du skal\x01aldrei move þet skarekrós hert,\x01babi!\x0B\x02", "box_type": 0},
    {"id": 0x40A7, "text": "Ó IÉHHH!!\x01Det ist et, det ist tune!!\x01Du rok!! Ik am blón bort!\x04Ó, non, non! Ik didn't vergessen \x01sang...Ik aldrei vergessen aniþing!\x01Aber Ik bara füle als rewarding\x01du, babi!\x04........\x01Ik have ain gut idé!\x04Mís buddi Pierre ist wandering\x01kring, so spelen det tune wenn\x01du vollen til kall en!\x04Ik skal sagen en til helpen du wenn er ist\x01nérbi und hört det sang, babi!\x0B\x02", "box_type": 0},
    {"id": 0x40A8, "text": "Hé, et ist Okarina!\x01Spelen det sang mit et,\x01babi!\x0B\x02", "box_type": 0},
    {"id": 0x40A9, "text": "\x12(äiúng lad, du spelen Okarina\x01vel... Mmmmm...! Det melodi ist \x01so gut...ribbit! Wir alle skold\x01praktike et, ribbit!\x04Nim Rubinar als ain súvenir!\x01Wenn du komen op mit ander nike \x01melodi, bitte drop af und spelen\x01et...Ribbit ribbit!\x0B\x02", "box_type": 0},
    {"id": 0x40AA, "text": "\x12(ãwó, det melodi ist so kúl! \x01Ribbit!\x04Siiiiingin' in raaaaaén,\x01Ó wat ain fíling! \x01Rrrrrribbbit!!\x04Bitte nim þet als ain tegn de\x01unser froggiş gratitude, ribbit!\x01Rétt vel. Séen du, ribbit!\x0B\x02", "box_type": 0},
    {"id": 0x40AB, "text": "\x12(älúk an uns, wir sin alle huge froskar!!\x01Wir sin verden berömd Fabulous\x01Fim Froggish Tenors!!\x01Rrrribbit!!\x04Maken uns jump so wir kan ét  \x01bugs fliing above uns, ribbit!\x04OK? \x01Dan, Klar, sette, Gáe!\x0B\x02", "box_type": 0},
    {"id": 0x40AC, "text": "\x12(ãiúng dreng, du dóde grrrét!\x01Perrrrrfect!\x01Wir sin stuffed, ribbit!\x04Vold du nim þet tegn de unser\x01gratitude?\x0B\x02", "box_type": 0},
    {"id": 0x40AD, "text": "Ó vel, Ik ne erinnern det \x01sang, babi.\x01Warüm? Det ist wat Ik ne kan sagen ia!\x01Gut golli!\x02", "box_type": 0},
    {"id": 0x40AE, "text": "\x08 biggest Fisk ever kaught in\x01þet pond weighed \x1D púnds.\x01 angler: pond óner\x09\x02", "box_type": 2},
    {"id": 0x40AF, "text": "Wat?\x01Dó du vollen til Fisk mit ain \x01different lure?\x01...Hé, wat ist det?\x04Wat? Du bara piked et op?\x01Usually, rules segt du ne kan\x01Bruk ain de de. Ik mén, usualli. \x01Aber, wat hek...\x02", "box_type": 0},
    {"id": 0x40B0, "text": "IAHÚÚÚ!\x01Þet ist HUGE!! Ain nüv rekord!!\x01Þet...þet weighs als meir als...\x01\x05A\x1D púnds\x05@!!\x04Buuuuuuuut! Det sinking lure ist\x01in violaçion de rules!\x01So, non pris für du.\x01Wah ha ha ha ha ha!\x0B\x02", "box_type": 0},
    {"id": 0x40B1, "text": "\x08 biggest Fisk ever kaught in\x01þet pond weighed \x1D púnds.\x01 angler: \x0F\x01(NOTE: Mit illegal sinking lure.)\x09\x02", "box_type": 2},
    {"id": 0x40B2, "text": "Du sin ain kind-hérted kind!\x01Aber ne sagen anione om þet.\x01Seriously!\x0B\x02", "box_type": 0},
    {"id": 0x40B3, "text": "WHAAAAAT?!?\x04Warüm sin du dóend þet til mik?\x01Wat sin du þinking?\x04Ik am ne sker til lat Du havst fram\x01det ési! Du havst til betalen mik ain \x01\x05A50-Rubin \x05@gut!\x01Seriously!\x0B\x02", "box_type": 0},
    {"id": 0x5000, "text": "\x08GIAAAH!\x09\x01\x14\x02\x08Du\x09 \x08killed\x09 \x08mik!!\x09\x14\x00\x01Huh? Ó, et ist du.\x04Dóde du forsöken til spelen  \x01\x05FSóls Sang\x05@?\x04Als Ik sagde du för, mit det \x01sang, du kan turn dé til naht \x01oder naht til dé whenever du \x01vollen.\x04Wenn du sin in darkness, det \x01sang skold bring suns ljós\x01til du. Du skold forsöken et.\x02", "box_type": 0},
    {"id": 0x5001, "text": "\x08Wenn Ik dug ain hol, Ik fand ain \x01skatt det stretkes--BOING!\x01und şrinks--BOING! Et ist so fun, \x01Ik skal aldrei geven et til anibodi!\x09\x02", "box_type": 2},
    {"id": 0x5002, "text": "\x05Agravekípers diari \x05@ist hér.\x01Dó du vollen til réd et?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 2},
    {"id": 0x5003, "text": "\x08Whoever réds þet, bitte enter\x01mís grave. Ik skal lat du havst mís\x01stretking, şrinking \x05Akípsake\x05@.\x09\x04\x08Ik am wéting für du.\x01--Dampé\x09\x02", "box_type": 2},
    {"id": 0x5004, "text": "\x08Du dekide ne til réd et...\x09\x02", "box_type": 2},
    {"id": 0x5005, "text": "Du deféted Poe ghost!\x04Dó du vollen til katk et in \x01ain flaska?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 2},
    {"id": 0x5006, "text": "Du vollen til katk et aber du \x01ne have ain Tom Flaska.\x02", "box_type": 2},
    {"id": 0x5007, "text": "Du lat et Gáe für nú.\x02", "box_type": 2},
    {"id": 0x5008, "text": "Du kaught ain Poe!\x02", "box_type": 2},
    {"id": 0x5009, "text": "\x1A\x08\x06\x04 rising sun skal eventualli sette,\x01\x06\x19Ain newborns líf skal fade.\x09\x04\x1A\x08\x06\x05Frá sun til mún, mún til sun...\x09\x04\x1A\x08\x06%Geven pékeful rest til\x01\x067 living déd.\x09\x04\x1AÞet ist ain interesting poem...\x01huh?\x02", "box_type": 2},
    {"id": 0x500A, "text": "\x08\x06$Restless súls wander\x01\x06\x1Evar sei ne belong,\x01\x06'bring sen kalm mit\x01\x066 \x05FSóls Sang\x05@.\x09\x02", "box_type": 2},
    {"id": 0x500B, "text": "\x1AEinwat ist inskribed auf  \x01tombstone...\x04\x1AEt ist \x05Fgeheimnis melodi\x05@ de  \x01Composer Bróderar!\x02", "box_type": 2},
    {"id": 0x500C, "text": "Ultimate trank! Hú om\x01\x05A100 Rubinar\x05@?\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x500D, "text": "Wenn du kange dín hug, komen \x01zurück und Besoek mik...\x01Hí hí hí!\x02", "box_type": 0},
    {"id": 0x500E, "text": "Du ne have enúgh Rubinar!\x01Hí hí hí!\x02", "box_type": 0},
    {"id": 0x500F, "text": "\x1AGIAAAAH!\x01\x14\x02\x08DU\x09 \x08KILLED\x09 \x08MIK...\x09\x14\x00\x08Unbelievable!\x09\x04\x1AÓ, wat?\x01Du sin ne ain de Ganondorfs \x01men, sin du?\x04\x1ABekabruk de mís role als ain ghost, Ik\x01hadde til akt als det. Ik apologize.\x04\x1ANú dan, lat mik introduke miself.\x01Ahem...\x07P\x10\x02", "box_type": 0},
    {"id": 0x5010, "text": "Ik am ain de ghostli komposer \x01bróderar de Kakariko By.\x04Alle folk in þet by sin\x01born til serve Konglig Família de\x01Hyrule.\x04Wir bróderar ok served Konglig \x01Família, und varen assigned til \x01studi hereditari mistik \x01kraftar de família.\x04Þótt wir aldrei konde figure út \x01 kraft de Triforce,\x04wir hadde nästum geendet unser \x01\x05Astudi de kontrolling tid\x05@ mit  \x01tones de okarinaar.\x04Uh, Ik mén...\x04Actually, wir dóde enden det \x01studi!\x04Wir vold have gevesen berömd, wenn \x01det hateful Ganondorf hadde ne\x01tried til stél unser results.\x04Wir konde aldrei lat en rép  \x01fruits de unser resérk!\x04Det ist warüm wir gav unser lives til \x01protekt geheimnis.\x07P\x11\x02", "box_type": 0},
    {"id": 0x5011, "text": "Dó du vollen til hören wat Ik \x01sagde aftur?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x5012, "text": "\x1A\x08GIAAAAH!\x09\x01\x14\x02\x08IK AM\x09 \x08DÉD\x09 \x08Ain\x09\x08GÉN!\x09\x14\x00\x01Wat? Du aftur?\x04\x1ASomehow, du remind mik de...\x01Prinsess Zelda...\x04\x1AHmm... Weil du möge have sum\x01konnekçion mit Konglig Família, Ik\x01skal sagen du ain klein meir de unser\x01tale.\x04\x1AZurück dan, folk kalled uns stór\x01komposers bekabruk de manig \x01musikal masterpiekes wir wrote.\x04\x1AAber wir bróderar varen ne bara \x01komposers.\x04\x1AWir hadde ain misçion til analize \x01mistisk kraftar de Hyrules\x01Konglig Família.\x04\x1AUnser namnar vold vesen ain part de \x01Hyrules histori wenn wir konde \x01enden unser resérk!\x04\x1AWir kept unser studi extremeli \x01geheimnis bis wir geendet et.\x07P\x14\x02", "box_type": 0},
    {"id": 0x5013, "text": "\x1A\x08GIAAAAH!\x09\x01\x14\x02\x08IK AM\x09 \x08DÉD\x09 \x08Ain\x09\x08GÉN!\x09\x14\x00\x01Wat? Du aftur?\x04\x1ASomehow, du remind mik de\x01Prinsess Zelda.\x04\x1AWeil du sím til have sum\x01konnekçion mit Konglig Família, Ik\x01skal sagen du ain klein meir de unser\x01stori.\x07P\x14\x02", "box_type": 0},
    {"id": 0x5014, "text": "Til sagen sannheit, elk de uns\x01var studiing ain different sang, ain\x01til \x05Asummon sun\x05@ und ander til\x01\x05Asummon mún\x05@.\x04Wenn du varen sannlig sent af ain \x01member de Konglig Família, Ik skal\x01sagen du om results de unser\x01studi.\x04Wir inskribed et auf \x05Akonglig\x01tombstone\x05@.\x04Als ain messenger de Konglig \x01Família, du skold vise dín\x01Konglig kredentials auf topp de  \x01Triforce mark...\x07P\x11\x02", "box_type": 0},
    {"id": 0x5015, "text": "Z Z Z...\x04Malon...dóend Rétt vel...\x01Mumble...mumble...\x01Sorry til maken du sorg...\x02", "box_type": 0},
    {"id": 0x5016, "text": "Ingo nám yfir Lon Lon Hestgarð und\x01sei kall et \x05AIngo Hestgarð \x05@nóadés.\x04Ik var kiked út de þar, und\x01sé an mik nú! Mís fraua, Malon, \x01still verkar an hestgarð...\x04Ik am worried om elar...\x02", "box_type": 0},
    {"id": 0x5017, "text": "Dóde du redden Malon? Thanks!\x01Ik am goin' zurück til hestgarð, dan!\x01Yeehah!\x02", "box_type": 0},
    {"id": 0x5018, "text": "\x1A\x08Hé kind!\x09\x01Ne mess kring mit  \x01graves!\x04\x1AIk am \x05ADampé Gravekeeper\x05@!\x01Mís ansikt möge vesen skari, aber Ik am ne\x01ain mal mar...\x04\x1Alat mik geven du ain advertisement\x01für mís side business...\x04\x1A\x05ADampé Gravekeepers\x05@\x01Hert-Pounding\x05D Gravedigging Tour\x05@!\x04\x1AWat ist gonna komen út?!\x01Wat ist gonna komen út?!\x01Wenn Ik beginnen digging,\x01wir skal vinden út!\x07P\x19\x02", "box_type": 0},
    {"id": 0x5019, "text": "Dó du vollen mik til dig hér?\x01\x05A10 Rubinar \x05@ für ain hol.\x01\x1B\x05BJa\x01Ne dó et\x05@\x02", "box_type": 0},
    {"id": 0x501A, "text": "\x05ANon, keinwat hér!\x05@\x02", "box_type": 0},
    {"id": 0x501B, "text": "\x1AKregen zurück, \x0F!\x02", "box_type": 0},
    {"id": 0x501C, "text": "\x1A\x0F....\x01Ain terrible ting havt happened!\x01 \x05Aond skugg ande\x05@ havt\x01gevesen relésed!\x04\x1A\x05AImpa\x05@, léder de Kakariko\x01By, hadde séled ond skugg\x01ande in bottom de vel....\x04\x1AAber forke de ond ande\x01kreeg so strong, sél de \x01vel brak, und et eskaped inn \x01verden!!\x02", "box_type": 0},
    {"id": 0x501D, "text": "\x1Alat mik nim kare de by!\x01Ik am reiknend auf du,\x01\x0F!\x02", "box_type": 0},
    {"id": 0x501E, "text": "\x08\x06#Konglig Composer Bros.\x01\x067Sharp Elder\x01\x06PR.Ik.P.\x09\x0B\x02", "box_type": 2},
    {"id": 0x501F, "text": "\x08\x06#Konglig Composer Bros.\x01\x063Flat Younger\x01\x06PR.Ik.P.\x09\x0B\x02", "box_type": 2},
    {"id": 0x5020, "text": "\x08\x06(Konglig Famílias Tomb\x09\x02", "box_type": 2},
    {"id": 0x5021, "text": "\x1A\x08\x06\x1AÞet poem ist dedikated til\x01 memori de dérli departed\x01\x06\x10members de Konglig Família.\x09\x0B\x02", "box_type": 0},
    {"id": 0x5022, "text": "\x1A dreng mit noble Zeldas \x01Okarina...Als Ik expekted, \x01du havst komen.\x04\x1AIk am \x05AImpa\x05@, ain de Sheikah.\x01Ik am Prinsess Zeldas karetaker,\x01und Ik am ok Sage wer\x01vaktar Skugg Tempel.\x02", "box_type": 0},
    {"id": 0x5023, "text": "\x1ABitte sé út gegn Prinsess!\x0E2\x02", "box_type": 5},
    {"id": 0x5024, "text": "\x1A\x0F, held!\x04\x1AFinally, alle de uns, \x05Asex Vísmen\x05@, \x01have gevesen awakened!\x01 tid gegn final şódón\x01mit Kong de Ond havt komen!\x04\x1AFör det, þótt, du skold\x01mít ain wer ist wéting für\x01du...\x04\x1A ain wer ist wéting für du an\x01 \x05DTempel de Tid\x05@....\x02", "box_type": 0},
    {"id": 0x5025, "text": "\x1AWir Sheikah have served  \x01roialti de Hyrule frá generaçion\x01til generaçion als attendants.\x01However...\x04\x1AAuf det dé sevin ár ago,\x01Ganondorf suddenli attaked...\x01und Hyrule Kastel surrendered\x01eftir ain şort tid.\x04\x1AGanondorfs mål var ain de\x01 lyklar til Hélag Rike...\x01skjult skatt de Konglig\x01Família... Okarina de Tids!\x04\x1AMís duti búnd mik til nim Zelda \x01út de Ganondorfs rék.\x04\x1AWenn last Ik sag du, als wir gemakt\x01unser eskape frá kastel, du\x01varen bara ain lad...\x04\x1ANú Ik séen det du havst werden \x01ain gut held...\x02", "box_type": 0},
    {"id": 0x5026, "text": "\x1AIk have til sté hér... Du Gáe til \x01Prinsess Zeldas side und protekt \x01elar auf mís behalf.\x04\x1ANú Ik zetten mís kraft, welk skold \x01vesen helpful til du, inn þet\x01\x05CMedallion\x05@!\x02", "box_type": 0},
    {"id": 0x5027, "text": "Hú ist dín Kukko? Ist er glad?\x01Skal Ik brev en út für du?\x02", "box_type": 0},
    {"id": 0x5028, "text": "\x1A\x12hui am \x05Aherre de karpenters\x01\x05@det Impa hired til improve þet\x01by und maken et inn ain true\x01kiti!\x04\x1AAber ung men þese dés ne\x01have ein ambiçion...\x01Dó du weten wat Ik mén, kind?\x04\x1AMís workers sin bara rennend\x01émlessli kring by, und\x01þei're ne making ein progress\x01an alle...\x04\x1AOk mís ón son dót ne have ain \x01job, und er bara wanders kring\x01alle dé!\x07P)\x02", "box_type": 0},
    {"id": 0x5029, "text": "\x1AÞei're alle worþless, Ik sagen du!!\x02", "box_type": 0},
    {"id": 0x502A, "text": "Sé an det púr fraua yfir þar.\x01Ela verkar so hard taking kare de \x01elar kikens, ok þótt túking\x01sen gevt elar gúse bumps...\x04Wat ain trúper! Ik vold sannlig \x01als til helpen elar! Ik have bara gevesen\x01fíling so karitable þese dés!\x01Ne du füle det veg, ok?\x02", "box_type": 0},
    {"id": 0x502B, "text": "\x1AÞars keinwat til sorg om...\x01 Prinsess ist safe nú.\x02", "box_type": 0},
    {"id": 0x502C, "text": "\x1ASoon, du skal mít Prinsess Zelda\x01ansikt-til-ansikt, und ela skal explén\x01everiþing...\x04\x1ADet ist wenn wir, sex Wise \x01Ainar, skal sél op Ond Kong\x01und teruggeven péke til Hyrule.\x02", "box_type": 0},
    {"id": 0x502D, "text": "\x1AHehehe, ung mar...\x01Du varen meir snel til vesen able\x01til halten op mit mik! Hehehe!\x04\x1AAls ain belónung, Ik am sker til geven\x01du mís skatt. Et ist kalled \x01\x05AHookshot\x05@!\x04\x1AEs fjäder-laden ketta skal trekken\x01du til ein spot var es haken\x01stavar. Dót ne det súnd kúl?\x01Ik am viss et skal helpen du!\x04\x1AIk live hér nú, so komen zurück\x01aftur sometime. Ik skal geven du\x01einwat kúl!\x04\x1AAin meir ting! Vesen vár auf\x01dín veg zurück!\x01Heheheh....\x02", "box_type": 0},
    {"id": 0x502E, "text": "Du sin zurück, ung mar...\x01Var present Ik gav til du\x01fun und useful?\x02", "box_type": 0},
    {"id": 0x502F, "text": "\x06\x19 tid de þet rake var\x01\x06K\x17!!\x0B\x02", "box_type": 0},
    {"id": 0x5030, "text": "\x1ASýnt als du sin koming kring...\x02", "box_type": 0},
    {"id": 0x5031, "text": "\x1AIk believe Impa havt gangen til  \x01\x05ESkugg Tempel \x05@til sél et aftur,\x01aber...ela skal vesen in danger óne \x01ein helpen!\x04\x1A\x0F!\x01Impa ist ain de sex Vísmen.\x01Zerstöten ond skugg ande und\x01redden Impa!\x04\x1AÞar ist ain entranke til  \x01Skugg Tempel benéþ  \x01graveiard bak þet by.\x04\x1A nur ting Ik kan dó für du ist\x01ték du melodi det skal\x01léd du til Skugg Tempel...\x04\x1AÞet ist melodi det skal drá\x01du inn infinite darkness \x01det absorbs ok tid... Hlusten til \x01þet, \x05ENocturne de Skuggs\x05@!!\x02", "box_type": 0},
    {"id": 0x5032, "text": "Gáe kring! Gáe kring und kring\x01und kring! Wat fun! Ik am so \x01glad!\x04Ik am ain musik mar wer líbt\x01til Gáe kring und kring!\x01Gáe kring und kring!!!\x04Ik am triing til komen op mit ain\x01musikal þeme inspired af þet \x01windmill...sker kring und\x01kring und kring!!!\x02", "box_type": 0},
    {"id": 0x5033, "text": "Gáe kring, Gáe kring, Gáe kring...\x01Wat? Et ist sker veg ok fast!\x02", "box_type": 0},
    {"id": 0x5034, "text": "Grrrrrrrrr!\x04Ik skal aldrei vergessen wat happened auf\x01det dé, sevin ár ago!\x01Grrrrrrrrr!\x04Et ist alle det Okarina kinds fault!\x01Näst tid er komt kring hér,\x01Ik am gonna mess en op!\x02", "box_type": 0},
    {"id": 0x5035, "text": "\x1AWat?! Du havst kreeg ain okarina!!\x04\x1AWat hek!\x04\x1ADet reminds mik de det tid,\x01sevin ár ago!\x04\x1AZurück dan ain mén kind kom hér \x01und pléed ain \x05Estrange sang\x05@. Et \x01messed op þet windmill!\x02", "box_type": 0},
    {"id": 0x5036, "text": "Wat skold Ik dó!?\x01Mís \x05AKukkoar\x05@ have alle flón bort!\x04Du, klein dreng, bitte!\x01Bitte helpen mik bring sen zurück til \x01þet pen!\x02", "box_type": 0},
    {"id": 0x5037, "text": "Mís Kukkoar have rennen bort!\x01Bitte helpen mik bring ander \x01fér zurück til þet pen! Bitte!\x02", "box_type": 0},
    {"id": 0x5038, "text": "Mís Kukkoar have rennen bort!\x01Bitte helpen mik bring ander \x01þri zurück til þet pen! Bitte!\x02", "box_type": 0},
    {"id": 0x5039, "text": "Mís Kukkoar have rennen bort!\x01Bitte helpen mik bring ander \x01twei zurück til þet pen! Bitte!\x02", "box_type": 0},
    {"id": 0x503A, "text": "Mís Kukkoar have rennen bort!\x01Bitte helpen mik bring last ain\x01zurück til þet pen! Bitte!\x02", "box_type": 0},
    {"id": 0x503B, "text": "\x1ADank dir für vinden mís Kukkoar.\x01Ik have allergies, so Ik kregen \x01gúse bumps wenn Ik túk sen.\x04\x1AFür helping mik, Ik skal geven þet\x01til du. Et ist gut glass, und skold\x01vesen useful. Bitte nim gut\x01kare de et!\x0B\x02", "box_type": 0},
    {"id": 0x503C, "text": "Hé, wat sin du dóend?!\x01Nú Gáe rúnd sen op oder betalen für \x01sen!\x0B\x02", "box_type": 0},
    {"id": 0x503D, "text": "Bitte ne tése mís Kukkoar!\x02", "box_type": 0},
    {"id": 0x503E, "text": "\x1AIk bred ain nüv art de miniature \x01Kukko! Ik kall et \x05APocket \x01Kukko\x05@! Ik ne kregen gúse bumps\x01frá þet babi.\x04\x1A\x05AKukkoar \x05@sin meir gut an \x01getting lazi, late-risers út de bed.\x01Haven't du hérd de sen \x01för?\x04\x1AEt makt sen meir glad til kraíen:\x01\x08\x068\x05AKUKKÚÚ\x05@!\x09\x01espekialli wenn et wakes op ain \x01meir tung slíper!\x04\x1AHowever, mís Kukko ist ne entireli\x01glad rétt nú...\x04\x1ADu..., \x01Du sé als du sin gut an \x01handling Kukkoar.\x04\x1AHér, nim þet egg.\x01Eftir Kukko hatkes, bring et \x01zurück til mik eftir ain meðan, und Ik skal \x01brev út es múd.\x07P?\x02", "box_type": 0},
    {"id": 0x503F, "text": "Wat dó du denken? \x01Skal du forsöken?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x5040, "text": "Ó, ok mal...varen du peked af\x01ain Kukko wenn du varen klein?\x0B\x02", "box_type": 0},
    {"id": 0x5041, "text": "Heh heh heh, ung mar!\x01Sin du fast auf dín fít?\x04Ik möge ne sé als et, aber Ik am \x01konfident in mís spíd!\x01lat uns have ain rake! \x01Follow mik wenn du dare!\x02", "box_type": 0},
    {"id": 0x5042, "text": "Bitte maken mís Kukko glad!\x01OK?\x02", "box_type": 0},
    {"id": 0x5043, "text": "\x1AÓ, dín Kukko sýnt pretti \x01glad! Er mos have awakened ain\x01extremeli lazi mar!\x04\x1ADu sin ain gut Kukko Keeper!\x01Ik skal geven du ain rare, valuable\x01Kukko, wenn du sin interested...\x04\x1AEs namn ist \x05ACojiro\x05@,\x05A \x05@und et brukte til\x01vesen mís bróders Kukko. Es\x01blá bodi ist qite karming.\x01Et ist so söt!\x04\x1AWeil mís bróder havt gangen, \x01et ist strange, aber Cojiro havt \x01stopped króing.\x07PD\x02", "box_type": 0},
    {"id": 0x5044, "text": "Dó du vollen til halten \x05ACojiro\x05@?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x5045, "text": "Et sýnt als wenn du sannlig als det\x01ander Kukko. OK, du kan halten et\x01gegn ain meðan.\x0B\x02", "box_type": 0},
    {"id": 0x5046, "text": "Ain alt witk rennt Trank Búð\x01bak þet ain. Du kan kregen til \x01det búð dur dyr til \x01lét de kúnter.\x0B\x02", "box_type": 0},
    {"id": 0x5047, "text": "Mís bróder mos have gevesen meir \x01loneli...\x02", "box_type": 0},
    {"id": 0x5048, "text": "Ik hérd det \x05BVerloren Skogar\x05@, \x01var féries live, ist ain strange\x01setzen mit manig mistisk smells.\x04Ik wiş Ik konde bara aingång maken \x01medikine mit sum de strange\x01tingar Ik might vinden þar...\x04Ik möge ne vesen able til séen meir \x01vel animore, aber mís nose still \x01verkar gut! Hehehe!\x02", "box_type": 0},
    {"id": 0x5049, "text": "Sniff sniff sniff...\x04Wat ain mistisk smell...\x04Du mos have einwat!\x02", "box_type": 0},
    {"id": 0x504A, "text": "Det bum! Er hadde til Gáe inn  \x01skog...\x01\x14\x01.....\x14\x00Ik séen.\x07PK\x02", "box_type": 0},
    {"id": 0x504B, "text": "Hé, geven et til mik nú!\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x504C, "text": "Hú sad... Ik bara mos ain klein...\x02", "box_type": 0},
    {"id": 0x504D, "text": "\x1Awenn du séest det fúl, geven þet til \x01en. Et ist strongest medikine\x01Ik have ever produked.\x04\x1AHowever, þet trank skal ne\x01verk auf ain monster...\x0B\x02", "box_type": 0},
    {"id": 0x504E, "text": "Hé, kind! Wenn du vollen til tragen \x01medikine, Du mos haven ain kar til\x01zetten et in!\x0B\x02", "box_type": 0},
    {"id": 0x504F, "text": "Sei sagen det þar ist non \x01medikine det kan kure ain fúl...\x01Ik guess det ist true...\x02", "box_type": 0},
    {"id": 0x5050, "text": "Ik ne kan kregen ned, so alle Ik kan dó\x01ist sé an \x05ADauðfjall\x05@.\x02", "box_type": 0},
    {"id": 0x5051, "text": "Ik ne kan kregen ned, so alle Ik kan dó \x01ist sé an stars.\x02", "box_type": 0},
    {"id": 0x5052, "text": "Kan Du séest et frá þar? \x01Einwat ist happening auf \x05ADauð \x01Fjall\x05@!\x02", "box_type": 0},
    {"id": 0x5053, "text": "Kan Du séest et frá þar?\x01\x05ADauðfjall \x05@ist aftur normal!\x02", "box_type": 0},
    {"id": 0x5054, "text": "Ik ne füle als getting ned,\x01ever! Whatever happens, Ik skal halten\x01watking Dauðfjall frá \x01op hér.\x02", "box_type": 0},
    {"id": 0x5055, "text": "\x1AHé! Gut til séen du aftur! Ik skal\x01geven du þet als ain memento.\x02", "box_type": 0},
    {"id": 0x5056, "text": "Til kregen ain gut view, bruken \x05F¥\x05@ und \x01sé kring mit \x05Dª\x05@.\x02", "box_type": 0},
    {"id": 0x5057, "text": "\x1AHé! Kind, dó du alwés enter\x01ander folks húses óne \x01permisçion? Didn't dín parents \x01ték du ein manners?\x04\x1A\x06BÓ vel.\x04\x1ADóde Du séest ain fraua bak þet \x01húse? Elas sker dur hard \x01tidar.\x04\x1A\x06BÓ vel.\x07PX\x02", "box_type": 0},
    {"id": 0x5058, "text": "Wenn det fraua asks du om \x01kikens, du skold hlusten til elar.\x02", "box_type": 0},
    {"id": 0x5059, "text": "\x1AIst visiting ander folks húses \x01an þet late húr dín idé de \x01fun? Du mos ne have hadde ain \x01gut upbringing.\x04\x1A\x06BÓ vel.\x07PZ\x02", "box_type": 0},
    {"id": 0x505A, "text": "Det fraua nimt kare de kikens,\x01aber ela ist, in fakt, allergik til \x01sen.\x04\x06BÓ vel.\x02", "box_type": 0},
    {"id": 0x505B, "text": "\x1AHé! Ung mar! Ain grón dreng\x01als du entering ain mars húse\x01óne permisçion?! Ik vollen til\x01talen til dín parents!\x04\x1A\x06BÓ vel.\x04\x1AÞet ist ne mís hobruk aniwé.\x01Þet ist \x05Astór Impas\x05@ húse!\x04\x1A stór Impa havt gangen til \x01\x05Agraveiard \x05@til sél op  \x01humongús kréture þar.\x04\x1AWeil Ganondorf skén, manig \x01monsterar have gevesen sighted \x01kring hér.\x04\x1ANur stór Impa havt kept \x01péke in unser by. Du havst til\x01erinnern det, ung mar!\x04\x1A\x06BÓ vel.\x04\x1ASpeaking de stór Impa, ela\x01hasn't komen zurück iet. Ik wonder \x01wat happened til elar?\x07P\\\x02", "box_type": 0},
    {"id": 0x505C, "text": "Ik hérd det \x05Aghost de \x01gravekíper \x05@often skint in  \x01graveiard bak þet by...\x04\x064Aber, non grós handel.\x02", "box_type": 0},
    {"id": 0x505D, "text": "\x1AHi, dreng! Ist þet fyrst tid\x01du havst visited þet by?\x04\x1AAin stór fraua, \x05AImpa\x05@, opened op\x01þet by til uns púr folk.\x07P^\x02", "box_type": 0},
    {"id": 0x505E, "text": "Vel, maken dikself an home.\x01 fúd ist ne Klar iet, þótt.\x02", "box_type": 0},
    {"id": 0x505F, "text": "stór Impa ist ne hér. Dóde\x01einwat happen til elar?\x02", "box_type": 0},
    {"id": 0x5060, "text": "\x1AAlle folk have hardşips in \x01ser past det sei vold\x01raþer non ain fand út om.\x07Pa\x02", "box_type": 0},
    {"id": 0x5061, "text": "Sé an bérded mar slíping\x01yfir þar. Ik bet ok einwer\x01als en havt hadde es şare de\x01trúbles in past...\x02", "box_type": 0},
    {"id": 0x5062, "text": "Det bérded mar ging zurück til \x01 hestgarð. Er lúked so glad!\x02", "box_type": 0},
    {"id": 0x5063, "text": "\x1ADing dong, ding dong!\x01Ik am ain klok soldier de Kakariko!\x01 kurrent tid ist: \x1F.\x04\x1AHello þar, son.\x01Zeldas attendant, stór \x05AImpa\x05@,\x01opened þet by til kommon\x01folk.\x04\x1AWir have nur ain klein populaçion \x01nú, aber somedé þet setzen skal \x01vesen als liveli als Hyrule Kastel \x01Stad! Ó, ja! Et skal!\x04\x1AClimb op \x05Astérs an norþ\x01\x05@end de by til vinden trél\x01det léds op Dauðfjall.\x04\x1AAber Du mos haven Kongs permisçion\x01til aktualli Gáe op fjall.\x02", "box_type": 0},
    {"id": 0x5064, "text": "Ding dong, ding dong!\x01 kurrent tid ist: \x1F.\x02", "box_type": 0},
    {"id": 0x5065, "text": "Ding dong, ding dong!\x01 kurrent tid ist: \x1F.\x01Af veg, dó du weten wat \x01happened in kastel?\x02", "box_type": 0},
    {"id": 0x5066, "text": "\x1AHé, son, wat sin du dóend \x01wandering kring þet late an \x01naht?\x04\x1AÓ, Ik kregen et. Du sin testing dín\x01kúrage, sin ne du? Du mos \x01vollen til Gáe til...ain graveiard!\x04\x1AWarten ain minute! Wat am Ik dóend\x01talking til ain kind? Ik have kreeg verk til\x01dó! Verk! Verk!\x07Pg\x02", "box_type": 0},
    {"id": 0x5067, "text": "Ding dong, ding dong!\x01 kurrent tid ist: \x1F.\x04Hövd ést und du skal vinden ain\x01\x05Agraveiard\x05@. Legends sagen du kan \x01kalm súls de déd mit\x01ain \x05Calt sang de Konglig Família\x05@.\x02", "box_type": 0},
    {"id": 0x5068, "text": "Þars ain strange mar living in  \x01Windmill. Have du alrédi met\x01en, Mr. Held?\x02", "box_type": 0},
    {"id": 0x5069, "text": "Folk sin disgusting. \x01Mís ón faþer und moþer sin\x01disgusting.\x01Du mos vesen disgusting, ok!\x02", "box_type": 0},
    {"id": 0x506A, "text": "Alle dé lang, wir sin working auf \x01manig konstrukçion projekts in \x01by. Et ist sker til nim awhile\x01för everiþing ist ferdig.\x04Unser herre verkar uns meir hard!\x02", "box_type": 0},
    {"id": 0x506B, "text": "Ik am starving!\x01lat uns ét dinner, rétt nú!\x02", "box_type": 0},
    {"id": 0x506C, "text": "De marar elk dó verk de \x01half ain mar, aber sei still vollen ain\x01full mars porçion!\x01Þei're lazi slakers, Ik sagen du!\x02", "box_type": 0},
    {"id": 0x506D, "text": "\x08\x05APoe 30 Rubinar\x01\x05@Þet ist ain bottled ghost ande. \x01Seljen et til einwer wer ist krazi \x01om weird tingar als þet.\x09\x0A\x02", "box_type": 0},
    {"id": 0x506E, "text": "\x08Poe 30 Rubinar\x09\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x5070, "text": "Mís Kukkoar have rennen bort!\x01Bitte katk sex meir!\x02", "box_type": 0},
    {"id": 0x5071, "text": "\x08\x05D\x0F!\x01Þet şip ist sinking!\x01Abandon şip!\x01Kregen onto ain safe platfórm!\x05@\x09\x0E<\x02", "box_type": 0},
    {"id": 0x5072, "text": "Ik am still missing sum Kukkoar!\x01Bitte rúnd op fim meir!\x02", "box_type": 0},
    {"id": 0x5073, "text": "\x08Ne kabruk trúble!\x01Ik skal sagen Dampé!\x09\x0E<\x02", "box_type": 0},
    {"id": 0x5074, "text": "Sé an þet, kind! Mís béutiful,\x01smúþ hender sin alle worn út \x01frá working. Sob sob...\x02", "box_type": 0},
    {"id": 0x5075, "text": "Ain job var du kan maken ain mengd\x01de monei óne meir effort...\x01 nur ting Ik kan denken de ist\x01þieveri... Ist det ain mal idé?\x02", "box_type": 0},
    {"id": 0x5076, "text": "Ik hérd det unser herres hobruk ist\x01bara bak þet húse. Er dót ne\x01vollen ein de uns til weten, þótt.\x02", "box_type": 0},
    {"id": 0x5077, "text": "Have du gesehen \x05AMr. Dampé\x05@, wer\x01lives in graveiard op ahéd?\x04Et ist \x1F rétt nú, so er ist\x01probabli aslíp in es hut.\x04Warüm ne du Gáe út onto  \x01field und kill sum tid?\x02", "box_type": 0},
    {"id": 0x5078, "text": "Ik am starving!\x01Ist ne dinner Klar iet?\x01Et ist \x1F alrédi!\x02", "box_type": 0},
    {"id": 0x5079, "text": "\x1AÞet brukte til vesen \x05Astór \x01Impas húse\x05@, aber ela dót ne\x01live hér ein longer.\x04\x1AEt ist nú opnen til alle \x01villagers. Du sin frí til\x01Gáe auf in.\x07Pz\x02", "box_type": 0},
    {"id": 0x507A, "text": "Þet by brukte til vesen ain \x01\x05CShiekah \x05@by, aber  \x01stór Impa opened et til \x01alle.\x02", "box_type": 0},
    {"id": 0x507B, "text": "Ik sagen du, Ik sag en!\x04Ik sag ghostli figure de Dampé\x01 gravekíper sinking inn\x01es grave. Et lúked als er var\x01haltend sum kind de \x05Askatt\x05@!\x02", "box_type": 0},
    {"id": 0x507C, "text": "Þar er ist! Et ist en!\x01er ist ain wer dropped frá\x01 ski surrúnded af ain blá\x01ljós!\x04Nú dó du believe mik?\x02", "box_type": 0},
    {"id": 0x507D, "text": "Keinwer believes wat Ik have gevesen\x01telling sen alle þese past \x01sevin ár!\x02", "box_type": 0},
    {"id": 0x507E, "text": "fyr nästum konsumed uns alle!\x01Aber togeþer, wir alle varen able til\x01zetten út fyr! Pretty gut\x01verk, ne du denken?\x02", "box_type": 0},
    {"id": 0x507F, "text": "Wah hah hah hah hah hah!\x04Sé an þet mar! Ever weil\x01er eskaped frá Hyrule Kastel\x01Stad, er ist werden ok meir\x01timid!\x02", "box_type": 0},
    {"id": 0x5080, "text": "Wah hah hah hah hah hah!\x04Er mos have gevesen séend tingar!\x01Wah hah hah hah hah hah!\x02", "box_type": 0},
    {"id": 0x5081, "text": "Wah hah hah hah hah hah!\x01De sin sum funni-séend\x01kloþes, mar!\x02", "box_type": 0},
    {"id": 0x5082, "text": "Wah hah hah hah hah hah!\x01Wenn tidar sin túgh, laughter ist\x01 best medikine!\x01Det ist wat mís dad alwés sagde!\x02", "box_type": 0},
    {"id": 0x5083, "text": "Sé an mik! Ik am auf topp de  \x01verden! Et sannlig boþers mik til séen\x01anione an ain higher level dan Ik\x01am! Ik have til vesen auf topp!\x02", "box_type": 0},
    {"id": 0x5084, "text": "Wenn Ik fall aslíp op hér, Ik skal\x01sureli fall ned...\x02", "box_type": 0},
    {"id": 0x5085, "text": "windmill dráar vatn op frá \x01 depþ de vel.\x04Nú vel ist dried op, þótt.\x01Hrrrrm...\x02", "box_type": 0},
    {"id": 0x5086, "text": "fraua hér ist sannlig\x01generús. Ela ok nám kare de\x01 karpenters wenn sei varen\x01hér!\x02", "box_type": 0},
    {"id": 0x5087, "text": "Ain lang tid ago...\x01Þar var ain mar in þet meir\x01by wer hadde ain aug sei sagde\x01konde séen sannheit!\x04Nú usualli, du havst til trén\x01dín hugs aug most strenuúsli\x01til aktualli séen sannheit...\x04Aber þet fella, non, sei sagen er\x01hadde ain different veg de dóend\x01tingar...\x04Es hobruk stúd var vel ist\x01nú...\x02", "box_type": 0},
    {"id": 0x5088, "text": "Folkar kring hér sagen de ain\x01\x05Afabulúsli rik família \x05@det aingång\x01lived in ain de húses in þet\x01by...\x04Aber sei sagen det hel\x01família var verflukt due til ser\x01gríd!\x04Wer wet wat might happen til\x01de wer sin konsumed af\x01gríd...\x02", "box_type": 0},
    {"id": 0x5089, "text": "Heh....\x04Wat ain annoiing mar,\x01interrupting uns als þet...\x01Ne du agrí, mís líben?\x02", "box_type": 0},
    {"id": 0x508A, "text": "Hí hí...\x04Violating unser personal spake!\x01Er mos have einwat beter\x01til dó...\x01Ne du agrí, darling?\x02", "box_type": 0},
    {"id": 0x508B, "text": "\x1ASé an en... mar mit \x01bérd. Ik denken er var fired frá\x01es job an hestgarð...\x07P\x8C\x02", "box_type": 0},
    {"id": 0x508C, "text": "er ist alwés bara lazing kring, \x01morgn, nún und naht. \x01er ist ain awfulli karefrí mar \x01during suk hard tidar.\x02", "box_type": 0},
    {"id": 0x508D, "text": "Det lazi mar, er kind de \x01reminded mik de mís klein Richard...\x04Wat ist det? Du sagen du havst\x01aldrei hérd de mís klein Richard?\x01Er var suk ain berömd puppi! Du \x01seriúsli haven't hérd de en?\x02", "box_type": 0},
    {"id": 0x508E, "text": "Ó, non! Ain storm aftur!!\x01Du pléed Okarina aftur,\x01didn't du!!\x01Grrrrrrrrrrrrrrr!!\x02", "box_type": 0},
    {"id": 0x508F, "text": "Du kaught ain Grós Poe!\x01Seljen et an \x05AAndebúð \x05@gegn ain\x01mengd de monei!\x02", "box_type": 2},
    {"id": 0x6000, "text": "\x08Halt! Stay var du sin!\x09\x02", "box_type": 0},
    {"id": 0x6001, "text": "Hé, newkomer!\x02", "box_type": 0},
    {"id": 0x6002, "text": "Hé, newkomer! Warten ain sekond \x01und Ik skal opnen port für du.\x02", "box_type": 0},
    {"id": 0x6003, "text": "\x08Ne nim uns so lightli!\x09\x02", "box_type": 0},
    {"id": 0x6004, "text": "\x1AIk have gesehen dín gut verk. Til kregen \x01past vaktar hér, du mos \x01have gut þieving skills.\x04\x1AIk brukte til denken det alle men, \x01besides stór Ganondorf, varen \x01useless...aber nú det Ik have gesehen\x01du, Ik ne denken so animore!\x04\x1A\x05A exalted Nabooru\x05@, unser léder, \x01zetten mik in karge de þet fortress.\x04\x1ANabooru ist sekond-in-kommand\x01til stór Ganondorf, Kong de \x01 Gerudo Thieves.\x04\x1AElar hédqarters sin in \x05FAnde\x01Tempel\x05@, welk ist an end de \x01desert.\x04\x1ASagen, du mos vollen til werden \x01ain de uns, eh?\x01Rétt vel, dan!\x01Du sin in frá nú auf!\x04\x1ANim þet. Mit et, du skal\x01have frí akkess til alle stedar de\x01 fortress!\x0B\x02", "box_type": 0},
    {"id": 0x6005, "text": "Frá nú auf, du sin frí til komen\x01und Gáe als du bitte dur  \x01port til desert.\x04Du skal vinden \x05FAnde Tempel\x05@,\x05F \x01\x05@var exalted Nabooru lives,\x01út þar in desert.\x02", "box_type": 0},
    {"id": 0x6006, "text": "\x08Stupid Kind!\x09\x01Kregen in þar und halten qiet!\x02", "box_type": 0},
    {"id": 0x6007, "text": "\x1AIk have non idé var du \x01komen frá, aber du mos have ain\x01mengd de Gutar til maken et past alle\x01 vaktar kring hér!\x04\x1AAlle de mís felló karpenters\x01sin imprisoned somewhere in hér.\x04\x1AWenn du kan kregen uns út de hér,\x01wir skal repé favor somehó!\x04\x1AAber vesen vár! Þere're viss\x01til vesen \x05AGerudo \x05@vaktar somewhere \x01\x14\x02\x08kring\x09 \x08hér\x09....\x14\x00\x04\x1A\x08Woo!\x09 \x08Watch út!\x09\x02", "box_type": 0},
    {"id": 0x6008, "text": "\x08\x06. Entrance til Past\x09\x02", "box_type": 1},
    {"id": 0x6009, "text": "\x08\x06$ Entrance til Present\x09\x02", "box_type": 1},
    {"id": 0x600A, "text": "\x08\x06$ Entrance til Future\x09\x02", "box_type": 1},
    {"id": 0x600B, "text": "\x128ìi'll vesen dín guide auf dín veg,\x01aber koming zurück, Ik skal ne spelen!\x01Ik skal vise du nur veg til Gáe,\x01so folló mik und ne vesen sló!\x0EZ\x02", "box_type": 0},
    {"id": 0x600C, "text": "\x1APast, present, future...\x04\x1A Meister Sverd ist ain şip mit \x01welk du kan sél upstrém und\x01dónstrém dur tids river...\x04\x1A port für det şip ist in \x01Tempel de Tid...\x04\x1ATil restore Desert Colossus\x01und enter \x05FAnde Tempel\x05@, du\x01mos travel zurück dur tids\x01fló...\x04\x1AHlusten til þet \x05FRequiem de Andes\x05@...\x01Þet melodi skal léd ain kild zurück\x01til desert.\x02", "box_type": 0},
    {"id": 0x600D, "text": "Ik am Gerudo meister de \x01horsebak arkeri! Auf topp de \x01det, Ik am Gerudo meister de\x01horsebak riding!\x04Vollen til forsöken horsebak arkeri\x01für \x05A20 Rubinar \x05@?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x600E, "text": "Du havst Gutar--Ik als du. \x01Follow mik.\x02", "box_type": 0},
    {"id": 0x600F, "text": "Et ist út de qesçion wenn du \x01ne have ain hest!\x02", "box_type": 0},
    {"id": 0x6010, "text": "\x08Ik skal ne have aniþing til dó mit ain\x01kóard als du!\x09\x02", "box_type": 0},
    {"id": 0x6011, "text": "Ah, du sin ne als gut als du \x01krav. Kannski näst tid.\x02", "box_type": 0},
    {"id": 0x6012, "text": "Du dóde vel.\x04Für todé, Ik admit Ik verloren. \x01Et síms Ik have ain mengd de rúm für \x01improvement.\x02", "box_type": 0},
    {"id": 0x6013, "text": "Þet ist Gerudos \x05ATraining \x01Ground\x05@.\x04Keinwer ist allóed til enter \x01óne ain memberşip kard.\x02", "box_type": 0},
    {"id": 0x6014, "text": "Þet ist Gerudos \x05ATraining\x01Ground\x05@.\x04Membership kard verified.\x04Ain forsöken für 10 Rubinar!\x01\x01\x1B\x05BForsöken\x01Ne forsöken\x05@\x02", "box_type": 0},
    {"id": 0x6015, "text": "Rétt vel, Ik skal nim dín 10 Rubinar.\x01Geven et dín best skot!\x0B\x02", "box_type": 0},
    {"id": 0x6016, "text": "Du ne have enúgh monei!\x01\x08Komen zurück aftur.\x09\x02", "box_type": 0},
    {"id": 0x6017, "text": "\x1AHé, rúkie!\x04\x1ASin du sker inn desert?\x01Ik skal opnen þet port für du, aber...\x04\x1ADu ne kan kross desert \x01unless du pasar \x05Atwei trials\x05@.\x07`\x18\x02", "box_type": 0},
    {"id": 0x6018, "text": "fyrst trial ist... \x05ARiver de \x01Sand\x05@! Du ne kan walk akross þet\x01river! Eftir du kross et, folló\x01 flags wir plaked þar.\x04 sekond trial ist... \x05APhantom\x01Guide\x05@!\x04De óne \x05Aaugar det kan séen\x01 sannheit \x05@skal nur vinden þemselves\x01returning hér.\x04Du sin sker aniwé, sin ne du?\x01Ik skal ne stoppen du...\x01Gáe ahéd!\x0B\x02", "box_type": 0},
    {"id": 0x6019, "text": "\x1AWarüm dóde du komen alle \x01veg ned hér? Wat? Du varen\x01bara om til ask mik sam \x01ting?\x07`\x1A\x02", "box_type": 0},
    {"id": 0x601A, "text": "Vel, nú det du sin ned hér, \x01du möge als vel maken best de \x01tingar!\x02", "box_type": 0},
    {"id": 0x601B, "text": "Gut kind! Thanks!\x01Ik am sorri det Ik ne kan geven du\x01einwat als gut darfür, aber...\x01nim þet aniwé!\x02", "box_type": 0},
    {"id": 0x601D, "text": "\x1AIk haven't gesehen du kring, kind...\x04Wat dó du vollen?\x01\x1C\x05BTil séen tempel\x01Séend gegn Vísmen\x01Keinwat, sannlig\x05@\x02", "box_type": 0},
    {"id": 0x601E, "text": "Du sin bara ain kind! tempel ist\x01non setzen für kinder!\x02", "box_type": 0},
    {"id": 0x601F, "text": "Ain Sage? Ik ne weten anione\x01als det.\x02", "box_type": 0},
    {"id": 0x6020, "text": "\x1ADu havst keinwat til dó? Wat \x01gut timing! Kan du dó mik ain \x01favor, kind?\x04\x1AWarten ain sekond, Ik vollen til ask du\x01fyrst--du wúldn't happen til vesen\x01ain de Ganondorfs...\x04follóers...vold du?\x01\x01\x1B\x05BWat wenn Ik am?\x01Ik hate Ganondorf!\x05@\x02", "box_type": 0},
    {"id": 0x6021, "text": "\x1AWha-ha-ha!\x01Ne forsöken til akt kúl, kind.\x01Ik var bara asking!\x04\x1AAin kind als du konde aldrei vesen\x01ain de Ganondorfs follóers!\x04\x1AVel, lat uns kut til kase...\x07`#\x02", "box_type": 0},
    {"id": 0x6022, "text": "\x1AUh-huh!\x04\x1ADu havst kreeg Gutar.\x01Ik denken Ik als du.\x07`#\x02", "box_type": 0},
    {"id": 0x6023, "text": "\x1AFyrst, lat mik introduke \x01miself. Ik am \x05ANabooru \x05@de Gerudo.\x01Ik am ain lone wolf þief.\x04\x1AAber ne kregen mik wrong!\x04\x1AÞótt wir sin boþ þieves, Ik am \x01kompleteli different frá\x01Ganondorf.\x04\x1AMit es follóers, er stole\x01frá women und kinder, und er \x01ok killed folk!\x04\x1AAin kind als du möge ne weten þet, \x01aber Gerudo rake konsists nur\x01de women. Nur ain mar ist born\x01everi hundred ár...\x04\x1AOk þótt unser laws sagen det\x01lone male Gerudo mos werden\x01Kong de Gerudo, Ik skal aldrei\x01boge til suk ain ond mar!\x04\x1AAf veg, wat ist dín namn, \x01kind?\x04\x1A\x0F?!\x04\x1AWat kind de namn ist det?\x01Vel...aniwé...\x07`$\x02", "box_type": 0},
    {"id": 0x6024, "text": "\x1AIk vollen til ask du ain favor...\x04\x1ASkal du Gáe dur þet tini hol\x01und kregen ain skatt det ist innan?\x04\x1A skatt ist \x05CSilver\x01Gauntlets\x05@. Wenn du utruste sen, du\x01kan ésili puş und trekken meir \x01tung tingar!\x04\x1ANon, non, non, kind! Ne ok denken\x01om taking þet skatt für \x01dikself!\x04\x1A Silfrhanskar skal ne fit ain\x01klein kind als du wenn du forsöken til \x01utruste sen! Ik vollen du til vesen ain \x01gut dreng und geven sen til mik!\x04\x1AGanondorf und es minions sin\x01brukend Ande Tempel als ain \x01hideút.\x04\x1ANur Silfrhanskar skal \x01alló mik til snék díp inn \x01tempel.\x04\x1AAingång þar, Ik am sker til stél alle\x01 skatt innan und mess op\x01ser plans!\x04Hú om et? Skal du dó et?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x6025, "text": "\x1AThanks, kind!\x04\x1ADu und Ik, lat uns geven Ganondorf\x01und es follóers ain grós surprise,\x01skal wir?\x07`&\x02", "box_type": 0},
    {"id": 0x6026, "text": "Wenn du kan sukkessfulli kregen  \x01\x05CSilfrhanskar\x05@...\x04Ik skal dó einwat stór\x05A \x05@für du!\x02", "box_type": 0},
    {"id": 0x6027, "text": "Vel, wat dóde Ik expekt?\x01Eftir alle, du sin bara ain kind!\x02", "box_type": 0},
    {"id": 0x6028, "text": "\x1AHé! Var sin du taking mik?!\x02", "box_type": 0},
    {"id": 0x6029, "text": "\x1AHó hó hó!\x01Sýnt als einwer ist hér, Koume.\x02", "box_type": 0},
    {"id": 0x602A, "text": "\x1AHí hí hí!\x01Sýnt als et, Kotake!\x02", "box_type": 0},
    {"id": 0x602B, "text": "\x1AWat ain útrageús felló er ist,\x01til intrude so boldli inn unser \x01Tempel...\x01Hó hó hó!\x02", "box_type": 0},
    {"id": 0x602C, "text": "\x1AWir skold ték þet útrageús\x01felló ain lesson!\x01Hí hí hí!\x02", "box_type": 0},
    {"id": 0x602D, "text": "\x1AÓ, loial minion...\x02", "box_type": 0},
    {"id": 0x602E, "text": "\x1AZerstöten þet intruder auf \x01unser behalf!\x02", "box_type": 0},
    {"id": 0x602F, "text": "\x1AStór Ganondorfs...Fiend...\x01Mos die...\x02", "box_type": 0},
    {"id": 0x6030, "text": "\x1AUnnnh...\x01Var am Ik...?\x02", "box_type": 0},
    {"id": 0x6031, "text": "\x1AVel, vel...\x01Sýnt als elas aftur normal...\x01Koume...\x02", "box_type": 0},
    {"id": 0x6032, "text": "\x1AElas bara ain klein fraua,\x01aber ela kommands ain mengd de \x01respekt among Gerudo, Kotake...\x02", "box_type": 0},
    {"id": 0x6033, "text": "\x1AKannski wir skold maken elar verk\x01gegn stór Ganondorf für\x01ain klein meðan longer!\x01Hó hó hó!\x02", "box_type": 0},
    {"id": 0x6034, "text": "\x1ADan wir skold brénwaş elar\x01aftur!\x01Hí hí hí!\x02", "box_type": 0},
    {"id": 0x6035, "text": "\x1AKind, lat mik Dank dir.\x04\x1AHeheheh...sé wat klein\x01kind havt werden in past sevin\x01ár--ain kompetent swordsman!\x02", "box_type": 0},
    {"id": 0x6036, "text": "Wenn nur Ik viss du vold werden \x01suk ain handsome mar...\x0CPI skold have kept promise\x01Ik gemakt zurück dan...\x0EP\x02", "box_type": 5},
    {"id": 0x6037, "text": "\x1AHér, Ik skal geven du \x05Aþet\x05@...\x01Et ist ain meir important ting til mik.\x01lat uns have ain kompetiçion later!\x02", "box_type": 0},
    {"id": 0x6038, "text": "\x1A\x0F...séen du aftur!\x02", "box_type": 0},
    {"id": 0x6039, "text": "\x1AAf veg...\x04\x1AIk sannlig messed op...\x04\x1AIk var brénwaşed af de alt\x01witkes und brukte af Ganondorf til\x01dó es ond skal...\x04\x1AAber ist ne et funni? Det ain mar\x01als mik konde turn út til vesen \x01\x05FSage de Ande\x05@!\x04\x1AUnd nú, Ik am sker til fight\x01sen als ain de sex Vísmen!\x01Heh heh...\x04\x1AIk am sker til betalen sen zurück für\x01wat sei dóde til mik!\x02", "box_type": 0},
    {"id": 0x603A, "text": "\x1AKind...\x04\x1ANon...\x01\x0F, Held de Tid!\x04\x1AInstead de kíping promise Ik\x01gemakt zurück dan, Ik geven du þet\x01\x05FMedallion\x05@!\x04\x1ANim et!\x02", "box_type": 0},
    {"id": 0x603B, "text": "\x1A\x08\x06\x12Yeearggh!\x09 lat mik Gáe!!\x02", "box_type": 0},
    {"id": 0x603C, "text": "\x1A\x063Du, \x08du fiendar!\x09\x01\x06)Ganondorfs minions!\x02", "box_type": 0},
    {"id": 0x603D, "text": "\x1A\x08\x06\x1E\x0F!\x09\x01\x06 Kregen út de hér! Nú!\x02", "box_type": 0},
    {"id": 0x603E, "text": "\x1A\x06\x0CÞese witkes! Þei're brukend\x01\x06+blak magik auf mik!\x02", "box_type": 0},
    {"id": 0x603F, "text": "Hé, newkomer! Þet ist unser \x01\x05Ahorsebak arkeri field\x05@.\x04Eftir ain mengd de hard praktike und\x01tréning, wir finalli have skill\x01til treffen bulls-aug meðan riding\x01als wind!\x04Wenn du finalli lérn hú til ride\x01ain hest, du skold komen zurück\x01und forsöken et. Et ist ain dangerús sport,\x01aber et ist fun!\x02", "box_type": 0},
    {"id": 0x6040, "text": "Hé newkomer, du havst ain gut \x01hest!\x04Ik ne weten var du stole \x01et frá, aber...\x04OK, hú om kallenging þet \x01\x05Ahorsebak arkeri\x05@?\x04Aingång hest begint galloping,\x01skjúten mål mit dín\x01pilar. \x04lat uns séen hú manig punktar du \x01kan skore. Du havst 20 pilar.\x04Wenn du kan skore \x05A1,000 punktar\x05@, Ik\x01skal geven du einwat gut!\x0B\x02", "box_type": 0},
    {"id": 0x6041, "text": "Dó du vollen til forsöken für \x05A20 Rubinar \x05@?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x6042, "text": "Hé, rúkie!\x01Du sin séend gut!\x01Vise mik dín skill aftur!\x04Du skold sette ain nüv goal de\x01\x05A1,500 punktar\x05@ und forsöken aftur!\x0B\x02", "box_type": 0},
    {"id": 0x6043, "text": "Wat? Dó du vollen til forsöken aftur?\x01Sýnt als du havst sum\x01potential!\x0B\x02", "box_type": 0},
    {"id": 0x6044, "text": "Ik skal vesen darned! Du sin ultimate\x01meister!\x04Ik skal geven du ain ting suitable\x01gegn meister.\x04Þet qiver ist meir important til \x01mik. Ik vollen du til have et.\x01Nim gut kare de et, OK?\x02", "box_type": 0},
    {"id": 0x6045, "text": "\x18 punktar...Hmm...\x01Wha-ha-ha! Du havst plenti de \x01rúm für improvement!\x0B\x02", "box_type": 0},
    {"id": 0x6046, "text": "Fantastic!\x01Du sin ain true meister!\x04Ik skal geven þet til du.\x01Halten improving dikself!\x02", "box_type": 0},
    {"id": 0x6047, "text": "\x18 punktar...\x01Quite impressive!\x0B\x02", "box_type": 0},
    {"id": 0x6048, "text": "Sé an det stupid kind!\x01Er kom auf es ón til úter \x01himself als ain sakrifike til \x01stór Ganondorf...\x0EZ\x02", "box_type": 0},
    {"id": 0x6049, "text": "\x06\x05Mit mís flame, Ik skal burn en til\x01\x06F bone!\x0E<\x02", "box_type": 0},
    {"id": 0x604A, "text": "Mit mís frost, Ik skal fríze en til\x01\x06Fes súl!\x0E<\x02", "box_type": 0},
    {"id": 0x604B, "text": "\x06\x1CSkjúten, wat ain frisk kind!\x01\x06\x15Þet tid, wir skal kregen seriús,\x01\x06<rétt Kotake?\x0EZ\x02", "box_type": 0},
    {"id": 0x604C, "text": "\x06KWat?\x0C\x14\x06\x0AHé, Koume, wat ist det above\x01\x06Adín hövd?\x0E<\x02", "box_type": 0},
    {"id": 0x604D, "text": "\x06\x0BIk ne weten, aber du havst ain\x01\x06\x14yfir dín hövd ok, Kotake!\x0E<\x02", "box_type": 0},
    {"id": 0x604E, "text": "\x06\x14Aber Ik am nur 400 ár alt!\x0E(\x02", "box_type": 0},
    {"id": 0x604F, "text": "\x06\x14Und Ik am bara 380 ár alt!\x0E(\x02", "box_type": 0},
    {"id": 0x6050, "text": "\x08\x06\x0CWir sin twins! Ne forsöken til lie\x01\x065om dín age!\x09\x0E(\x02", "box_type": 0},
    {"id": 0x6051, "text": "\x08\x06\x06Du mos have gangen senile!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6052, "text": "\x08\x06\x1EWer sin du kalling senile?!\x01\x06\x16Ist det hú du trét dín\x01\x06=older sister?\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6053, "text": "\x08\x066Wir sin twins! \x01\x06&Hú kan du vesen older?\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6054, "text": "\x08\x06?Keeeyaaah!!\x09\x01\x08\x06 Hú hértless du sin!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6055, "text": "\x08\x06\x12Hú kan du vesen so ungrateful?\x09\x0E\x0A\x02", "box_type": 0},
    {"id": 0x6056, "text": "\x08\x065Du sin hértless!!\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6057, "text": "\x08\x063Du ungrateful...\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6058, "text": "\x08\x06!Ik skal komen zurück til haunt du!\x09\x0E(\x02", "box_type": 5},
    {"id": 0x6059, "text": "\x08OK, lat uns kregen seriús nú, Kotake!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x605A, "text": "\x067\x08Ó, OK, Koume.\x09\x0C\x14\x060\x08Kotake\x09 und \x08Koumes\x09\x01\x06\x1C\x08Double\x09 Dynamite \x08Angrepen!\x09\x0E(\x02", "box_type": 0},
    {"id": 0x605B, "text": "\x1ADóde du komen hér til redden mik? \x01Ó, det ist bara swell! Ik am \x05AIchiro\x01 karpenter\x05@.\x04\x1AWir varen sannlig interested in \x01joining ser alle-female grúp, aber \x01sei loked uns op als þet bara\x01bekabruk wir sin men!\x04\x1AWir ne kare om Gerudo \x01animore! Þei're so rude!\x04\x1A\x05AÞri de mís fellós\x05@ have ok \x01gevesen kaptured, so bitte helpen \x01sen eskape, ok!\x02", "box_type": 0},
    {"id": 0x605C, "text": "\x1ADu sin ain söt kind! Dank dir für\x01koming til redden mik! Ik am \x05AJiro,  \x01karpenter\x05@.\x04\x1AÞese women sin so skari! Ik vold\x01raþer verk als ain karpenter dan\x01join sen!\x04\x1AIk ne kan warten til sagen gut-farvel til\x01þet setzen! \x05ATwei de mís buddies \x05@\x01sin still vesend held prisoner. Skal\x01du bitte kregen sen út, ok?\x02", "box_type": 0},
    {"id": 0x605D, "text": "\x1AThanks, dreng! Du sin fantastik!\x01Ik am \x05ASabooro, karpenter\x05@.\x04\x1AHave du gesehen unser herre, dreng?\x01er ist probabli worried om mik!\x01Ik have til kregen zurück til en \x01\x08immediateli!\x09\x04\x1A\x05AAin meir de unser workers \x05@ist still\x01ain prisoner. Bitte redde en!\x02", "box_type": 0},
    {"id": 0x605E, "text": "\x1AIk var afréd du varen sker til \x01vergessen om mik! Nú Ik am frí!\x01Thanks! Ik am \x05AShiro karpenter\x05@.\x04\x1AFür reskuing mik, Ik skal sagen du\x01einwat interesting om \x01desert det Ik overhérd \x01Gerudoar talking om.\x04\x1ASei sagde, \"In order til kross \x01Haunted Wasteland, du skal mos \x01'\x05Aaug de sannheit\x05@.' Colossus ist auf\x01 fjarr side de wasteland...\"\x04\x1AOK, nú Ik am sker zurück til mís\x01\x05Atent nér Gerudo Valley\x05@, so, \x01drop af sometime. Du möge vinden \x01einwat helpful þar! Byeee!\x02", "box_type": 0},
    {"id": 0x605F, "text": "léder de gang de þieves\x01ist \x05ANabooru\x05@. Ela ist experimenting \x01in brénwaşing manig folk an \x01 ruins in desert.\x02", "box_type": 0},
    {"id": 0x6060, "text": "Ó, et var Ganondorf Ond\x01Kong wer var bak gang de \x01þieves...\x02", "box_type": 0},
    {"id": 0x6061, "text": "\x1AWenn \x05ANabooru\x05@ var ain lone wolf \x01þief, ela aldrei stole frá \x01 wék, aber...\x07`b\x02", "box_type": 0},
    {"id": 0x6062, "text": "Nú, Naboorus gang de þieves \x01stát für kruelti und brutaliti.\x01Ela kravar til vesen ain kivalrús \x01robber, aber...non veg!\x02", "box_type": 0},
    {"id": 0x6063, "text": "Als Ik suspekted, Nabooru var \x01brénwaşed af Ganondorfs \x01follóers...\x02", "box_type": 0},
    {"id": 0x6064, "text": "\x1AIn Gerudo sokieti, de wer have\x01stór skill in horsebak riding und\x01arkeri sin vel respekted.\x07`e\x02", "box_type": 0},
    {"id": 0x6065, "text": "Hú om triing horsebak \x01arkeri an Gerudos Fortress?\x04Wenn du havst ain hest, ain Gerudo \x01frá fortress skal sette op \x01dín kallenge.\x02", "box_type": 0},
    {"id": 0x6066, "text": "Du dóde so stór, ung mar!\x02", "box_type": 0},
    {"id": 0x6067, "text": "Building ain bridge yfir vallei\x01ist ain simple task für fér\x01karpenters.\x02", "box_type": 0},
    {"id": 0x6068, "text": "Óne alt witkes, gang\x01de þieves ist ne alle det skari!\x02", "box_type": 0},
    {"id": 0x6069, "text": "\x05AGerudos Fortress \x05@ist lokated \x01beiond þet port. Ain kind als du \x01havt non business þar.\x02", "box_type": 0},
    {"id": 0x606A, "text": "\x1A\x12hui am ain \x05Ameister kraftsman\x05@. De\x01Gerudo þieves...sei brak \x01bridge.\x04\x1AIk vollen til fix et, aber alle de mís \x01workers sin gangen!\x04\x1ASei sagde working als karpenters\x01ist ne kúl, und sei ging til \x01\x05AGerudos Fortress \x05@til werden \x01þieves...\x07`k\x02", "box_type": 0},
    {"id": 0x606B, "text": "Hé, du! Wenn du sin sker til  \x01fortress, vold du hug vinden\x01út wat mís workers sin dóend\x01yfir þar?\x02", "box_type": 0},
    {"id": 0x606C, "text": "Hé, Ik hérd du gereddet mís men.\x01Wenn sei teruggav, wir built þet\x01bridge.\x04Sé þet! \x01Ist ne et ain gut bridge?\x04Sei möge vesen wimpi karpenters, \x01aber aingång sei alle kreeg togeþer,\x01sei kreeg job ferdig.\x02", "box_type": 0},
    {"id": 0x606D, "text": "\x1A\x12huhei, det sag! Et ist mís!\x04\x1AAber... Ik þúght Ik lét det sag\x01mit mís alt fraua... Ó vel...\x07`n\x02", "box_type": 0},
    {"id": 0x606E, "text": "Mís Biggoron túl brak, so Ik var\x01sker til Goron City til kregen et\x01reparért.\x04Dín koming hér ist stór timing.\x01Skal du geven mik mís sag?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x606F, "text": "\x06G\x08Wat?!\x01\x06\x14Du sin ain dirti, rotten þief!\x09\x02", "box_type": 0},
    {"id": 0x6070, "text": "Þet ist Gerudos \x05ATraining \x01Ground\x05@. Unqualified marar sin \x01ne allóed.\x02", "box_type": 0},
    {"id": 0x6071, "text": "Þet ist Gerudos\x05A Training\x01Ground\x05@. Du sin qalified...\x01K'mon in und hone dín skills\x01als meir als du vollen.\x0B\x02", "box_type": 0},
    {"id": 0x6072, "text": "Þet ist Gerudos\x05A Training \x01Ground\x05@. Ok þótt du sin \x01qalified, ne hog alle  \x01skatt hér für dikself!\x02", "box_type": 0},
    {"id": 0x6074, "text": "Ó, det ist ok mal.\x04 mark det skal léd du til \x01Ande Tempel ist \x05Aflag auf\x01 lét \x05@útan búð.\x04Wenn du kange dín hug, bitte\x01komen zurück aftur!\x02", "box_type": 0},
    {"id": 0x6075, "text": "Ohh, ne enúgh Rubinar.\x01Non diskúnts, ok ain Rubin.\x02", "box_type": 0},
    {"id": 0x6076, "text": "Heh heh.\x01Du sin alrédi in mid de \x01einwat, sin ne du.\x04Wenn du vollen til kallenge mik, du\x01have til komen hér mit ain klér\x01hug. Non ander distrakçions!\x02", "box_type": 0},
    {"id": 0x6077, "text": "\x06AVel Komen!\x04Ik am selling stuff, strange und \x01rare, frá alle yfir verden til \x01alle.\x01Todays spekial ist...\x04Ain dangerús, rennend objekt! \x01Terrifying! \x01Ik skal ne sagen du wat et ist bis \x01Ik séen monei....\x04Hú om \x05A200 Rubinar\x05@?\x01\x01\x1B\x05BKaup\x01Ne Kaup\x05@\x02", "box_type": 0},
    {"id": 0x6078, "text": "Dank dir meir meir!\x04Wat Ik am selling ist...\x14\x02\x05ABombchu \x05@!\x14\x00\x04 mark det skal léd du til\x01 Ande Tempel ist \x05Aflag auf\x01 lét \x05@útan búð.\x01Vesen séend du!\x02", "box_type": 0},
    {"id": 0x6079, "text": "\x1AHé, wat ist op, \x0F?\x01Surprised til séen mik?\x04\x1AAin lang tid in þet verden ist\x01nästum keinwat til du, ist et?\x01Hú mistisk!\x04\x1AOk Ik þúght det tales de ain\x01dreng wer konde travel zurück und\x01forþ dur tid var mereli ain\x01legend.\x04\x1A\x0F, du havst fulli \x01matured als ain voksen.\x07`z\x02", "box_type": 0},
    {"id": 0x607A, "text": "Frá nú auf, future de alle \x01folk in Hyrule ist auf dín \x01şúlders.\x04Kannski et ist ne mís tid animore. \x01Hér ist mís last advike.\x04Twei witkes inhabit þet tempel. In \x01order til zerstöten sen, \x05Aturn ser \x01ón Magikkraft agénst sen\x05@.\x01Hú hút!\x07`{\x02", "box_type": 0},
    {"id": 0x607B, "text": "Dó du vollen til hören wat Ik sagde\x01aftur?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x607C, "text": "\x1AIk skal kontinue til watk du...\x01Hú hú hú hút!\x02", "box_type": 0},
    {"id": 0x607D, "text": "\x1AIk am wandering rennend mar!\x01Ik have rennen alle yfir þet land in\x01sérk de true kompetitive ande.\x04\x1AIk bét alle mís kallengers, mar und\x01bést.\x04\x1ADu sin ain aþletik mar, und du\x01sé als du might have ain true\x01killer instinkt, ok.\x04\x1ANú det bridge yfir Gerudo\x01Valley ist enden, Ik am séend für\x01ain kallenger til have ain \x01kommemorative rake agénst.\x07`~\x02", "box_type": 0},
    {"id": 0x607E, "text": "best tid til Gáe frá hér til \x01 \x05Bbridge in Verloren Skogar \x05@var\x01\x05A\x1E\x04\x05@. Det ist mís rekord.\x04Skal du kallenge mís rekord?\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x607F, "text": "Excellent!\x01Dan...\x04Du Gáe fyrst.\x01Ik skal geven du ain hédstart.\x04Nú! \x14\x02Gáe ahéd.\x14\x00\x02", "box_type": 0},
    {"id": 0x6080, "text": "Heh heh heh.\x01Du skal aldrei diskover dín\x01killer instinkt mit det\x01kind de attitude.\x02", "box_type": 0},
    {"id": 0x6081, "text": "Vel, ne perfekt, aber du\x01have sum Gutar! Unfortunately,\x01du aldrei kan bét mik. Dín\x01rekord ist ain ting de past.\x04Dín tid var \x05A\x1E\x04\x05@, wasn't et?\x01Det var klose, aber Ik bét du\x01af ain sekond!\x0B\x02", "box_type": 0},
    {"id": 0x6082, "text": "Heh heh heh.\x01Bitte. \x14\x02Gáe ahéd.\x14\x00\x02", "box_type": 0},
    {"id": 0x6083, "text": "Ó, sýnt als du qit rake.\x01Heh heh heh. Ik bet du hadde nästum \x01rediskovered dín killer instinkt!\x0E<\x02", "box_type": 0},
    {"id": 0x6084, "text": "Heh heh.\x01Du ne have enúgh killer\x01instinkt iet.\x04Bara trén harder.\x01\x08Gut-farvel, dan!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6085, "text": "\x14\x01\x08Huff...\x09\x08puff...\x09\x08huff...\x09\x14\x00\x04Huff...huff...whew!\x01Du dóde qite vel!\x04Aber du kúldn't bét mik!\x01Dín tid var \x05A\x16\x05@, aber Ik\x01bara bét du af ain sekond!\x04Huff...huff... \x01Du skal have til kallenge mik\x01aftur sometime!\x04Huff...huff...\x01\x08Gut-farvel, dan!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6086, "text": "Ik am wandering rennend mar!\x01Ik have rennen alle yfir þet land in \x01sérk de kompetitors wer have ain\x01true killer instinkt!\x04Ik kom hér til rennen dur  \x01Haunted Wasteland, aber et dót ne\x01sé als gut timing für det.\x04Þótt Ik vollen til Gáe zurück til \x01Hyrule Field, bridge ist...vel,\x01du kan séen et frá hér. So Ik am\x01stuk hér, innan þet tent.\x04Ik ne denken Ik kan akkept dín\x01kallenge rétt nú.\x01Heh heh!\x02", "box_type": 0},
    {"id": 0x7000, "text": "Ik ne kan katk det Kukko!\x02", "box_type": 0},
    {"id": 0x7001, "text": "Huff huff! \x01Ik am late! Ik am late!\x01gegn ain meir important date!\x02", "box_type": 0},
    {"id": 0x7002, "text": "Velkom til Hyrule Kastel Stad.\x01Et ist ain pékeful, prosperús stad.\x02", "box_type": 0},
    {"id": 0x7003, "text": "Kinder şúldn't vesen wandering kring\x01stad an nighttime! Stay indúrs\x01bis morgn!\x02", "box_type": 0},
    {"id": 0x7004, "text": "Mar, Ik am SO bored...\x01Tingar vold viss vesen meir\x01interesting wenn þar varen meir...\x01trúbles in verden...\x04Hé, det ist bara millum du und\x01mik, OK?\x04Anyway, kannski wir kan lat fram \x01sum stém af bréking þese \x01jars.\x04Stá nér ain jar und druk \x05C\x9F\x05@ til \x01lyften et. Drukk \x05C\x9F\x05@ aftur til toss et!\x02", "box_type": 0},
    {"id": 0x7005, "text": "\x1ADet ist stór!\x04\x1AIk vergat til sagen du...\x0B\x02", "box_type": 0},
    {"id": 0x7006, "text": "\x08Þars ain mengd sker auf in  \x01kastel rétt nú. Ik ne kan alló\x01ok ain dog til kregen inn  \x01kastel!\x09\x02", "box_type": 0},
    {"id": 0x7007, "text": "\x1AUnnngh...sin du dreng frá \x01 skog...?\x04\x1AIk-Ik-Ik have finalli met du...\x01Ik-Ik-Ik have einwat til t-t-sagen\x01du...\x04\x1A\x05AGanondorf\x05@, Gerudo Kong de\x01Thieves, betréed unser Kong...\x04\x1AZeldas nanni, \x05AImpa\x05@, sensed danger\x01und eskaped frá kastel mit\x01unser Prinsess...\x04\x1AIk tried til stoppen Ganondorfs men\x01frá kasing sen...aber...\x04\x1A Prinsess var...wéting gegn ain\x01dreng frá skog...det ist du...\x01Ela vold til geven \x05Aeinwat \x05@til \x01 dreng...\x04\x1Awenn du kreeg et frá  \x01Prinsess, \x14\x03\x08Snelt\x09...\x08til \x09 \x08\x05DTem\x09\x08ple\x09 \x08de\x09\x01Tid\x05@....\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x7008, "text": "er ist ne moving animore....\x02", "box_type": 2},
    {"id": 0x7009, "text": "\x1AKan Du séest mar mit  \x01ond augar?\x04\x1ADet ist \x05AGanondorf\x05@, léder de \x01 Gerudoar. Sei hél frá  \x01desert fjarr til west.\x04\x1AÞótt er swérs allegianke til mís \x01faþer, Ik am viss er ist ne \x01sinkere.\x04\x1A dark klúds det kovered \x01Hyrule in mís drém...\x01Sei mos simbolize det mar!\x02", "box_type": 0},
    {"id": 0x700A, "text": "\x06\x0EGeh heh heh! Excellent verk!\x0C<\x06\x08Als Ik þúght, du held lyklar\x01\x06&til Dyr de Tid!\x0CZ\x06\x05Du havst led mik til portar de\x01\x06- Hélag Rike...\x0CP\x06\x10Ja, Ik óe et alle til du, kind!\x0E2\x02", "box_type": 0},
    {"id": 0x700B, "text": "\x1ABitte! Wenn du ne Snelt,\x01he'll vesen gangen!\x0B\x02", "box_type": 0},
    {"id": 0x700C, "text": "Bitte...mit \x05F¡\x05@...\x01Bitte seljen mik \x05Akontents\x05@ de ain\x01flaska...\x01Bitte...mit \x05F¡\x05@...\x02", "box_type": 0},
    {"id": 0x700D, "text": "Wat ain strange búð! \x01Ik wonder wenn it'll vesen opnen für\x01business. Ik réd sign þar, \x01aber et still síms weird!\x02", "box_type": 0},
    {"id": 0x700E, "text": "Et síms als et ist taking forever\x01für dawn til komen...\x04 view de Hyrule Kastel in \x01 morgn sun ist so fantastik!\x02", "box_type": 0},
    {"id": 0x700F, "text": "Til redden skog fraua, Du mos haven\x01\x05Aander skill\x05@... \x01Hövd til Kakariko By!\x02", "box_type": 0},
    {"id": 0x7010, "text": "Et sýnt als du havst \x01skills Du mos haven... \x01 \x05Bskog fraua\x05@ ist wéting für dín\x01helpen....\x02", "box_type": 0},
    {"id": 0x7011, "text": "Wenn du vollen trankar, du vold beter \x01bring ain Tom Flaska. Understand,\x01ung mar?\x0A\x02", "box_type": 0},
    {"id": 0x7012, "text": "Ik am sorri, aber þet ist bara ain model. \x01Bekabruk de krisis in Goron \x01City, wir haven't kreeg ein \x01şipments lateli und wir sin út.\x0A\x02", "box_type": 2},
    {"id": 0x7013, "text": "Wenn du plan auf skaling Dauð\x01Fjall, Kaup ain \x05DHylia-Skjold\x05@.\x01Du kan defend dikself agénst\x01falling roks mit det skjold.\x04Aber et might vesen ain klein bit \x01grós gegn ain kind....\x0A\x02", "box_type": 0},
    {"id": 0x7014, "text": "Ik am ne danking, du weten...\x01Mís zurück itkes! \x01Ooh! Aaah! Ooh!\x02", "box_type": 0},
    {"id": 0x7015, "text": "Sei sagen wir \x05DHylians \x05@have grós órar\x01in order til hören voikes de  \x01gods...aber Ik have aldrei hérd sen!\x02", "box_type": 0},
    {"id": 0x7016, "text": "\x1AKind, have du gevesen til \x01\x05FLon Lon Hestgarð\x05@?\x04\x1ASer mjolk ist delikiús!\x01Þar sin manig hestar þar, und\x01 ung daughter de hestgarð\x01óner ist söt!\x07p\x17\x02", "box_type": 0},
    {"id": 0x7017, "text": "Til kregen til \x05FLon Lon Hestgarð\x05@, eftir\x01du laten stad, hövd due súþ\x01akross field. Du skold Besoek\x01 hestgarð an lést aingång!\x02", "box_type": 0},
    {"id": 0x7018, "text": "\x1AIk vold til séen \x05APrinsess Zelda\x05@!\x04\x1AIk avoided vaktar...\x04\x1ASwam dur moat...\x04\x1AIk var nästum þar wenn sei\x01kaught mik!\x07p\x19\x02", "box_type": 0},
    {"id": 0x7019, "text": "Ik fand ain \x05Aklein drén hol \x05@auf \x01rétt side de kastel det Ik\x01þúght Ik konde snék inn, aber Ik\x01kreeg stuk þar.\x02", "box_type": 0},
    {"id": 0x701A, "text": "\x067Ahem! \x08Hrrrm!\x09\x04\x06\x05Þet bérd ist mís pride und joi!\x01\x06\x07Dót ne et sé luxuriant, kind?!\x02", "box_type": 0},
    {"id": 0x701B, "text": "\x1A\x067Ahem! \x08Hrrrm!\x09\x04\x1A\x06\x05Þet bérd ist mís pride und joi!\x01\x06\x07Dót ne et sé luxuriant, kind?!\x04\x1A\x08\x06QWat?!\x09\x04\x1ADu sin séend gegn mar frá\x01Lon Lon Hestgarð?\x04\x1AHmm, kannski...\x07p\x1C\x02", "box_type": 0},
    {"id": 0x701C, "text": "Ik sag ain \x05Amar mit ain şabbi-séend\x01bérd \x05@delivering sum boxes til \x01 kastel.\x02", "box_type": 0},
    {"id": 0x701D, "text": "\x1ADó du weten om \x05DTempel \x01de Tid \x05@det wir have in  \x01norþést part de stad?\x07p\x1E\x02", "box_type": 0},
    {"id": 0x701E, "text": "Legends sagen det Tempel de\x01Tid ist entranke til  \x01Hélag Rike...\x04Dóde du weten det?\x02", "box_type": 0},
    {"id": 0x701F, "text": "\x1AWha-ha-ha! Wat ain krazi mar!\x04\x1AKan du believe þet mar var \x01krazi enúgh til forsöken til snék inn\x01 kastel til séen \x05APrinsess Zelda\x05@?\x07p \x02", "box_type": 0},
    {"id": 0x7020, "text": "Alle bekabruk de þet idiot, þei've \x01tightened sekuriti an kastel.\x01Wha-ha-hah!\x02", "box_type": 0},
    {"id": 0x7021, "text": "\x1AIk gemakt ain mengd de monei!\x04\x1AKannski Ik skold Gáe sé für\x01meir tingar til seljen!\x07p\"\x02", "box_type": 0},
    {"id": 0x7022, "text": "Ik weten! Ik skold Gáe til \x05CHylia-Sjó\x05@!\x01Manig tingar float ned river\x01und end op þar!\x01Hah hah!\x02", "box_type": 0},
    {"id": 0x7023, "text": "\x1AHé, skog dreng! Þet ist \x05Dkiti\x01de Hyrule\x05@! Nim dín tid und\x01enjoi sights!\x07p$\x02", "box_type": 0},
    {"id": 0x7024, "text": "Wenn du kom hér til séen \x05DHyrule\x01Kastel\x05@, nim strít auf dín\x01rétt.\x04Wenn du vollen til séen \x05Czurück \x01alleis\x05@ de stad, nim \x01strít til lét.\x02", "box_type": 0},
    {"id": 0x7025, "text": "Ohh...\x04Du sin...so handsome...\x04Bara als Kong de Hyrule...\x04Hí hí...\x02", "box_type": 0},
    {"id": 0x7026, "text": "Ohh...\x04Du sin...\x04meir béutiful...\x04dan Prinsess Zelda...\x04Ohh...\x02", "box_type": 0},
    {"id": 0x7027, "text": "\x1AHave du hérd legend de \x01\"Skugg Folk\"?\x04\x1ASei sin \x05CSheikah\x05@... skuggar\x01de Hylians.\x04\x1ASei sagen sei swore allegianke til\x01 Kong de Hyrule und guarded\x01 Konglig Família.\x04\x1AAber mit lang péke, non ain\x01havt gesehen ain Sheikah kring hér \x01gegn ain lang tid.\x04\x1AHowever...\x07p(\x02", "box_type": 0},
    {"id": 0x7028, "text": "Ik hérd þar ist ain \x05CSheikah \x01\x05@fraua living in kastel...\x02", "box_type": 0},
    {"id": 0x7029, "text": "So du sagen du vollen til séen\x01\x05APrinsess Zelda\x05@, eh?\x04Du probabli hérd om elar in\x01stad und dekided du hadde til mít\x01elar... Vel...\x04\x08Gáe home!\x09 \x08Kregen út de hér!\x09\x01 Prinsess vold aldrei grant ain\x01audienke til alsar de du!\x02", "box_type": 0},
    {"id": 0x702A, "text": "Z Z Z Z Z....\x04Mumble mumble...\x04Welcome...unser hestgarð ist so fun...\x04K'mon und sé kring...\x02", "box_type": 0},
    {"id": 0x702B, "text": "\x1A\x08\x06-Wat in tarnaçion?\x09\x04\x1ANe kan ain mar kregen ain klein şut-\x01aug kring hér?\x02", "box_type": 0},
    {"id": 0x702C, "text": "\x1AHello, und wer might du vesen?\x04\x1AYep, Ik am \x05ATalon\x05@, óner de Lon \x01Lon Hestgarð.\x04\x1AIk ging til kastel til deliver\x01sum mjolk, aber Ik sat ned hér til\x01rest, und Ik guess Ik fell aslíp...\x04\x1A\x06L\x12hrwhat?!\x01Malon var séend für mik?\x01Ik am gonna katk et frá elar nú!\x04\x1AIk messed op mal, léving Malon\x01bak til warten für mik!\x04\x1AElas sannlig gonna lat mik have et!\x0B\x02", "box_type": 0},
    {"id": 0x702D, "text": "\x08\x067Hé du! Stoppen!\x01\x06(Du, kind, yfir þar!\x09\x0B\x02", "box_type": 0},
    {"id": 0x702E, "text": "\x1A\x06_!\x0C\x0A\x1A\x06N\x08Wer?!\x09\x0B\x02", "box_type": 0},
    {"id": 0x702F, "text": "\x1A\x06:Wer sin du?\x04\x1AHú dóde Du havst past vaktar?\x0B\x02", "box_type": 0},
    {"id": 0x7030, "text": "Dó du havst et? \x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x7031, "text": "Vel, det ist fremd...\x01Ik þúght du might vesen ain\x01frá mís drém...\x01Du sannlig ne have et?\x04Sagen mik sannheit...\x0B\x02", "box_type": 0},
    {"id": 0x7032, "text": "\x1A\x06-Bara als Ik þúght!\x0B\x02", "box_type": 0},
    {"id": 0x7033, "text": "Bitte halten þet ain geheimnis frá\x01alle...\x01\x1B\x05BOK\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x7034, "text": "K'mon...ne vesen ain blabber-múþ!\x0B\x02", "box_type": 0},
    {"id": 0x7035, "text": "\x1A legend gáet als þet...\x0B\x02", "box_type": 0},
    {"id": 0x7036, "text": "\x1A\x06\x12 þri goddesses hid \x01\x06\x07\x05ATriforce \x05@konténing kraft de\x01\x06\x0D gods somewhere in Hyrule.\x0CP\x1A\x06E kraft\x01\x06\x03til grant wiş de ain wer\x01\x06\x0Ahalt Triforce in es hender.\x0CP\x1A\x06\x03Wenn einwer mit ain righteús hert\x01\x06\x07makt ain wiş, et skal léd Hyrule\x01\x06\x09til ain golden age de prosperiti....\x0C<\x1A\x06\x06Wenn einwer mit ain ond hug havt\x01\x06\x0Aes wiş granted, verden skal\x01\x06\x02vesen konsumed af ond...Det ist wat\x01\x065havt gevesen sagde....\x0CP\x1A\x06\x16So, ankient Vísmen built\x01\x06\x02 \x05DTempel de Tid\x05@ til protekt \x01\x06 Triforce frá ond ainar.\x0EZ\x02", "box_type": 2},
    {"id": 0x7037, "text": "Det ist rétt... Tempel de Tid\x01ist entranke dur welk du\x01kan enter Hélag Rike frá\x01unser verden.\x04Aber entranke ist séled mit\x01ain stein vegg kalled  \x01\x05DDyr de Tid\x05@.\x04Und, in order til opnen dyr,\x01et ist sagde det Du mos haven til samlen\x01þri \x05AAndlig Steinar\x05@.\x04Und ander ting Du mos haven...ist\x01 skatt det Konglig Família\x01haltenar along mit þet legend...\x0B\x02", "box_type": 0},
    {"id": 0x7038, "text": "Ó, Ik am sorri. \x01Ik am ne meir gut an storitelling...\x0B\x02", "box_type": 0},
    {"id": 0x7039, "text": "\x1A\x08Wat happened?\x09 Dóde er séen du?\x04\x1ANe sorg.\x04\x1AEr dót ne have ein idé wat\x01wir sin planning...iet!\x0B\x02", "box_type": 0},
    {"id": 0x703A, "text": "\x1ABitte!\x01\x01\x1B\x05BOK\x01Ik ne believe du.\x05@\x02", "box_type": 0},
    {"id": 0x703B, "text": "\x1A\x06BDank dir!\x0B\x02", "box_type": 0},
    {"id": 0x703C, "text": "Mís attendant skal guide du út de\x01 kastel. Ne vesen afréd til talen\x01til elar.\x02", "box_type": 0},
    {"id": 0x703D, "text": "Andlig Stein...\x01Du finalli fand et!\x04Et ist sagde det rakes det halten\x01 Andlig Steinar opnen ser\x01hugar nur til ain wer wet \x01\x05Cmelodi de Konglig Família\x05@.\x04Aber du alrédi weten det, ne\x01du?\x02", "box_type": 0},
    {"id": 0x703E, "text": "Hé, have du hérd det\x01Prinsess Zelda séet profetik \x01viçions in elar dréms?\x02", "box_type": 0},
    {"id": 0x703F, "text": "Huh? Wat? Shoo, kind! Shoo!\x02", "box_type": 0},
    {"id": 0x7040, "text": "Þar sin þri hollós und \x01ain inskripçion hér....\x04\x08Ye wer óns 3 Andlig Steinar \x05C\x01\x05@Stá mit \x05DOkarina de Tids\x05C\x01\x05@Und spelen \x05DSang de Tids\x05@\x09\x04Det ist hú inskripçion réds.\x0B\x02", "box_type": 2},
    {"id": 0x7041, "text": "K'mon, ne kan du maken et ein\x01képer?\x02", "box_type": 0},
    {"id": 0x7042, "text": "Hé, lat Gáe! Et ist mís!\x01Ik fand et fyrst!\x02", "box_type": 0},
    {"id": 0x7043, "text": "Hé, wer bumped mik?!\x02", "box_type": 0},
    {"id": 0x7044, "text": "Wir ne séen ain mengd de Gerudoar in\x01þese parts...\x01Einwat Fisky ist sker auf!\x02", "box_type": 0},
    {"id": 0x7045, "text": "Wasn't det Prinsess Zelda riding\x01auf white hest?!\x02", "box_type": 0},
    {"id": 0x7046, "text": "Ik nästum kreeg kiked af det\x01blak hest!\x02", "box_type": 0},
    {"id": 0x7047, "text": "Det mar riding auf blak hest\x01mos have gevesen Ganondorf, wer ist\x01renóned als Gerudo Kong de \x01Thieves.\x02", "box_type": 0},
    {"id": 0x7048, "text": "Wat happened?!\x02", "box_type": 0},
    {"id": 0x7049, "text": "Sé an det mar--er ist so skared!\x01Wat ain wimp!\x01Ha ha hah!\x02", "box_type": 0},
    {"id": 0x704A, "text": "Ik have ain fíling einwat\x01terrible ist sker til happen...\x01Kannski Ik skold laten stad sún.\x02", "box_type": 0},
    {"id": 0x704B, "text": "Einwat happened in kastel!\x01Kind, du vold beter vesen vár!\x02", "box_type": 0},
    {"id": 0x704C, "text": "Mit det \x05Alykl\x05@, prokíd til  \x01rúm ahéd. Gáe, Gáe!\x02", "box_type": 0},
    {"id": 0x704D, "text": "ain riding auf white hest\x01haltend klein fraua...\x01Wasn't det ain legendari Sheikah?\x02", "box_type": 0},
    {"id": 0x704E, "text": "\x1A\x06-\x0F...\x04\x1A\x06EWake op...\x01\x06\x05\x0F, kosen ain...\x02", "box_type": 5},
    {"id": 0x704F, "text": "\x1AIk am \x05ARauru\x05@, ain de ankient\x01Vísmen...\x04\x1AAges ago, wir ankient Vísmen\x01built Tempel de Tid til \x01protekt entranke til \x01Hélag Rike...\x04\x1AÞet ist \x05AChamber de Vísmen\x05@,\x05A \x01\x05@innan Tempel de Ljós...\x04\x1A Tempel de Ljós, situated in\x01 meir mid de Hélag \x01Rike, ist last stronghold \x01agénst Ganondorfs ond forkes.\x04\x1A \x05AMeister Sverd\x05@-- ond-\x01destroiing sverd det du pulled\x01út de Pedestal de Tid--var \x01 final lykl til Hélag Rike.\x04\x1A\x0F...\x01Ne vesen alarmed...\x01Sé an dikself...!\x02", "box_type": 0},
    {"id": 0x7050, "text": "\x1A\x06#\x05DSé \x0F!\x01\x05@\x062\x05DDu sin grós nú!!\x01\x05@\x061\x05DDu havst grón op!\x05@\x02", "box_type": 0},
    {"id": 0x7051, "text": "\x1A Meister Sverd ist ain hélag\x01kling welk ond ainar möge aldrei\x01túk....\x04\x1ANur ain worþi de title de\x01\"\x05AHeld de Tid\x05@\"\x05A \x05@kan trekken et frá \x01 Pedestal de Tid....\x04\x1AHowever, du varen ok ung til \x01vesen Held de Tid....\x04\x1ATherefore, dín ande var \x01séled hér für sevin ár.\x04\x1AUnd nú det du sin alt enúgh,\x01 tid havt komen für du til\x01awaken\x05A \x05@als Held de Tid!\x04Vel, dó du understand dín \x01destini?\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x7052, "text": "Rétt, et sýnt als du sin \x01konfused... lat mik sagen du \x01aftur, frá beginning.\x07pQ\x02", "box_type": 0},
    {"id": 0x7053, "text": "\x1AAber, erinnern...\x04\x1AÞótt du opened Dyr de \x01Tid in namn de péke...\x04\x1A\x05AGanondorf\x05@, Gerudo Kong de\x01Thieves, brukte et til enter þet \x01forbidden Hélag Rike!\x04\x1AEr obténed Triforce frá\x01 Tempel de Ljós, und mit es \x01kraft, er vard \x05AKong de Ond\x05@...\x04\x1AEs ond kraft radiated frá \x01tempelar de Hyrule, und in sevin\x01şort ár, et transformed Hyrule\x01inn ain verden de monsterar.\x04\x1AMís kraft nú havt nur klein \x01influenke, ok in þet Hélag\x01Rike...\x04\x1ANamely, þet Chamber de Vísmen.\x04\x1AAber þar ist still hope...\x04\x1A kraft de Vísmen reméns.\x04\x1AWenn kraft de alle \x05AVísmen\x01\x05@ist awakened...\x04\x1A \x05AVísmen' Seals\x05@ skal kontén\x01alle ond kraft in void de \x01 Rike...\x04\x1AIk, Rauru, am ain de Vísmen...\x01Und...\x04\x1ADín kraft til fight togeþer mit\x01 Vísmen makt du  \x01\x05AHeld de Tid\x05@!\x04\x1A Held de Tid, kosen af \x01Meister Sverd!\x04\x1AHalten mís ande mit du...\x01Und, vinden kraft de ander\x01Vísmen und add ser might til dín\x01ón!\x02", "box_type": 0},
    {"id": 0x7054, "text": "\x1A\x05D\x0F...wir sin zurück in \x01\x05@Tempel de Tid\x05D...\x01Aber have \x05@sevin ár\x05D sannlig\x01passed?\x05@\x04\x1A\x05DEt sýnt als du skal ne vesen\x01able til Bruk sum de \x05@vápnar\x05D\x01Du fand als ain kind animore...\x04\x05@\x1A\x05Dlat uns kregen út de hér!\x05@\x02", "box_type": 0},
    {"id": 0x7055, "text": "Heyyy, wat...? \x01Wat ist wrong mit loitering\x01kring alle dé?\x04Huh, kind?\x02", "box_type": 0},
    {"id": 0x7056, "text": "\x1AIk have gevesen wéting für du, \x01Held de Tid...\x02", "box_type": 0},
    {"id": 0x7057, "text": "\x1AWenn ond rules alle, ain awakening\x01voike frá Hélag Rike skal\x01kall de destined til vesen Vísmen,\x01wer dwell in \x05Afim tempelar\x05@.\x04\x1AAin in ain \x05Bdíp skog\x05@...\x04\x1AAin auf ain \x05Ahigh fjall\x05@...\x04\x1AAin under ain \x05Cvast sjó\x05@...\x04\x1AAin wiþin \x05Ehobruk de déd\x05@...\x04\x1AAin innan ain \x05Fgoddess de sand\x05@...\x04\x1ATogether mit Held de Tid, \x01 awakened ainar skal bind \x01ond und teruggeven ljós de péke\x01til verden...\x04\x1AÞet ist legend de tempelar\x01passed ned af mís folk, \x01\x05CSheikah\x05@.\x02", "box_type": 0},
    {"id": 0x7058, "text": "Ó, Ik am sorri.\x01Wir sin ne opnen für business iet.\x01Bitte komen zurück sún!\x0B\x02", "box_type": 0},
    {"id": 0x7059, "text": "\x1ABruk \x05AMeister Sverd\x05@!\x01Zerstöten Ganon mit hélag\x01sverd!\x02", "box_type": 0},
    {"id": 0x705A, "text": "\x1AIk have gevesen wéting für du,\x01\x0F.\x02", "box_type": 0},
    {"id": 0x705B, "text": "\x1A\x0F, Held de Tid...\x04\x1ADu havst overkome manig \x01hardşips und awakened sex Vísmen.\x04\x1AUnd nú du havst ain final\x01kallenge, ain şódón mit \x01Ganondorf, Kong de Ond....\x02", "box_type": 0},
    {"id": 0x705C, "text": "\x1A\x06\x10Wenn du vold sík hélag\x01\x06(triangle, hlusten vel...\x0C<\x1A\x06\x09 resting setzen de hélag\x01\x06\x09triangle, Hélag Rike, ist ain\x01\x06\x14mirror det reflekts wat ist\x01\x06;in hert...\x0CF\x1A\x06\x05 hert de ain wer enters et...\x01\x06\x0CWenn ain ond hert, Rike skal\x01\x06\x14werden full de ond; wenn pure,\x01\x06\x04 Rike skal werden ain paradise.\x0CZ\x1A\x06\x02 Triforce... hélag triangle...\x01\x06\x0Aet ist ain balanke det weighs \x01\x06<þri forkes:\x01\x06\x13Kraft, Wisdom und Courage.\x0CZ\x1A\x06\x02Wenn hert de ain wer halt\x01\x06\x06 hélag triangle havt alle þri\x01\x06\x0Aforkes in balanke, det ain skal\x01\x06\x03gén True Force til govern alle.\x0CP\x1A\x06\x06Aber, wenn det ains hert ist ne in\x01\x06\x02balanke, Triforce skal separate\x01\x062inn þri parts:\x01\x06\x13Kraft, Wisdom und Courage.\x0CP\x1A\x06\x04Nur ain part skal remén gegn\x01\x06\x02ain wer túked Triforce...\x01\x06\x07part representing forke det\x01\x06'ain most believes in.\x0CZ\x1A\x06\x04Wenn det ain síks True Force,\x01\x06\x0Cdet ain mos akqire twei\x01\x06Dverloren parts.\x0CP\x1A\x06\x12De twei parts skal vesen held\x01\x06\x07wiþin anderar kosen af destini,\x01\x06\x0Awer skal bér Triforce mark\x01\x06\x11auf zurückar de ser hender.\x0EZ\x02", "box_type": 2},
    {"id": 0x705D, "text": "\x1ASevin ár ago, Ganondorf,  \x01Kong de Thieves, brukte dyr \x01du opened in Tempel de Tid\x01und entered Hélag Rike.\x04\x1AAber wenn er léd es hender auf \x01Triforce, legend kom true.\x02", "box_type": 0},
    {"id": 0x705E, "text": "\x1A ain wer halt \x05ATriforce \x01de Courage \x05@ist...\x01Du, \x0F!\x02", "box_type": 0},
    {"id": 0x705F, "text": "\x1AUnd ander, wer halt  \x01\x05ATriforce de Wisdom\x05@...\x04\x1Aist sevenþ Sage, wer ist\x01destined til vesen léder de\x01sen alle...\x02", "box_type": 0},
    {"id": 0x7060, "text": "\x1AEt ist Ik, Prinsess de Hyrule,\x01\x05AZelda\x05@.\x02", "box_type": 0},
    {"id": 0x7061, "text": "\x1AIk apologize für míting du in \x01disguise, aber et var nekessari til\x01hide frá Kong de Ond. \x01Bitte forgive mik...\x02", "box_type": 0},
    {"id": 0x7062, "text": "Ik sag du als Ik var eskaping \x01frá kastel mit mís \x01attendant, Impa.\x0EP\x02", "box_type": 2},
    {"id": 0x7063, "text": "\x1AAls lang als du hadde Okarina \x01in dín possesçion, Ik þúght \x01Ganondorf konde aldrei enter \x01Hélag Rike, aber...\x04\x1Aeinwat Ik konde aldrei expekt\x01happened...\x02", "box_type": 0},
    {"id": 0x7064, "text": "\x1A\x06$Det rumbling...Et ne kan vesen!?\x02", "box_type": 0},
    {"id": 0x7065, "text": "\x1APrinsess Zelda...du fúliş \x01trétor!\x04\x1AIk kommend du für avoiding mís \x01pursuit für sevin lang ár.\x02", "box_type": 2},
    {"id": 0x7066, "text": "\x1AWenn du vollen til reskue Zelda,\x01komen til mís kastel!\x02", "box_type": 2},
    {"id": 0x7067, "text": "\x1A\x0F...kan du hören mik?\x01Et ist Rauru, Sage.\x04\x1AWir sex skal gaþer unser kraft til\x01kréte ain bridge til kastel\x01var Ganondorf dwells...\x04\x1A kastels halten, welk ist \x01knón als Ganons Tower, ist \x01protekted af \x05Asex ond barriers\x05@.\x04\x1ABring ned sex barriers und\x01redden Prinsess Zelda!!\x02", "box_type": 2},
    {"id": 0x706C, "text": "Ancient Creators de Hyrule!\x0C<Nú, opnen séled dyr\x01und send Ond Incarnation de\x01Darkness inn void de \x01Ond Rike!!\x0EZ\x02", "box_type": 0},
    {"id": 0x706D, "text": "\x1A\x0F!\x01Finish en fram mit sverd de\x01tid, Meister Sverd!\x02", "box_type": 0},
    {"id": 0x706E, "text": "\x1AÓ séled dyr opened af  \x01Vísmen... Close forever mit \x01 Ond Incarnation de Darkness\x01wiþin!!\x02", "box_type": 0},
    {"id": 0x706F, "text": "\x1ADank dir, \x0F...\x04\x1AThanks til du, Ganondorf havt\x01gevesen séled innan Ond Rike!\x04\x1AThus, péke skal aingång aftur\x01reign in þet verden...gegn ain tid.\x02", "box_type": 0},
    {"id": 0x7070, "text": "\x1A\x06<Dank dir...\x01\x062\x0F...\x0C(\x1A\x062Gut-farvel....\x0E<\x02", "box_type": 2},
    {"id": 0x7071, "text": "Dó du sannlig vollen til Gáe dur\x01þet port det meir? lat mik denken\x01om et... OK, aber darfür...\x07pr\x02", "box_type": 0},
    {"id": 0x7072, "text": "Geven mik 10 Rubinar...\x01\x01\x1B\x05BJa\x01Non\x05@\x02", "box_type": 0},
    {"id": 0x7073, "text": "Bitte believe mik....\x01Mís profekies have aldrei gevesen\x01wrong!\x0B\x02", "box_type": 0},
    {"id": 0x7074, "text": "\x1ADu zerstört wiked\x01krétures det haunted tempel\x01und awakened Sage...\x04\x1AAber þar sin still ander Vísmen\x01wer mos dín helpen.\x04\x1AIn order til awaken alle ander\x01Vísmen, du mos werden ok\x01meir póerful.\x04\x1ADu mos travel yfir\x01fjallar...\x04\x1Aunder vatn...\x04\x1Aund ok dur tid...\x02", "box_type": 0},
    {"id": 0x7075, "text": "\x1AAls lang Meðan Du haltst \x05DOkarina\x01de Tid\x05@ und \x05DMeister Sverd\x05@,\x04\x1Adu halten tid itself in dín\x01hender...\x04\x1A\x0F, wir skal mít \x01aftur!\x02", "box_type": 0},
    {"id": 0x7076, "text": "Þet ist ain nüv art de bomb!\x01Et ist avélable nur in limited\x01qantities, und wenn Ik am sold \x01út, det ist et!\x0B\x02", "box_type": 0},
    {"id": 0x7077, "text": "\x1AIk am \x05ASheik\x05@.\x01Survivor de Sheikahs...\x02", "box_type": 0},
    {"id": 0x7078, "text": "\x1AAls Ik séen du standing þar\x01haltend miþikal \x05AMeister \x01Sverd\x05@, du sannlig dó sé als  \x01legendari Held de Tid...\x02", "box_type": 0},
    {"id": 0x7079, "text": "\x1AWenn du believe legend, du\x01have non koike. Du mos sé für\x01 fim tempelar und awaken \x01\x05Afim Vísmen\x05@....\x02", "box_type": 0},
    {"id": 0x707A, "text": "\x1AAin Sage ist wéting gegn tid\x01de awakening in \x05BSkogtempel\x05@.\x01 Sage ist ain fraua Ik am viss du\x01weten...\x04\x1ABekabruk de ond kraft in \x01tempel, ela ne kan hören \x01awakening kall frá Hélag\x01Rike...\x04\x1AUnfortunately, eqipped als du \x01kurrentli sin, du ne kan ok\x01enter tempel...\x04\x1AAber, wenn du believe wat Ik am séing,\x01du skold hövd til \x05AKakariko \x01By\x05@...\x04\x1ADó du understand, \x01\x0F?\x02", "box_type": 0},
    {"id": 0x707B, "text": "Ik þúght Ik skold entrust \x01Okarina til du... Ik þúght det \x01vold vesen unser best kanke...\x0EP\x02", "box_type": 2},
    {"id": 0x707C, "text": "\x1AFör det...Ik have tingar Ik vollen \x01til sagen nur til du. Bitte hlusten.\x04\x1AAnder unknón legend de  \x01Triforce passed ned af  \x01skugg folk, Sheikahs....\x02", "box_type": 0},
    {"id": 0x707D, "text": "\x1A Triforce separated inn þri \x01parts. Nur \x05ATriforce de Kraft\x05@\x01reméned in Ganondorfs hand.\x02", "box_type": 0},
    {"id": 0x707E, "text": "\x1A strengþ de Triforce de\x01Kraft enabled en til werden ain\x01mighti, ond kong, aber es dark\x01ambiçions varen ne satisfied.\x02", "box_type": 0},
    {"id": 0x707F, "text": "\x1ATil gén enden masteri de  \x01verden, Ganondorf started séend\x01für \x05Ade kosen af destini\x05@ til  \x01halten twei ander Triforce parts.\x02", "box_type": 0},
    {"id": 0x7080, "text": "\x1AAuf det dé, sevin ár ago,\x01Ganondorf attaked Hyrule Kastel.\x02", "box_type": 0},
    {"id": 0x7081, "text": "\x1AEftir du opened dyr de \x01tid, Meister Sverd séled du\x01bort in Hélag Rike...\x02", "box_type": 0},
    {"id": 0x7082, "text": "\x1ADín ande reméned in Hélag\x01Rike...und dan Triforce fell \x01inn Ganondorfs hender. Er ging\x01auf til invade Hélag Rike...\x04\x1AGanondorf hadde werden Ond\x01Kong, und Hélag Rike\x01vard ain verden de ond. Alle de\x01þet ist ain unfortunate koinkidenke.\x04\x1AIk passed miself fram als ain Sheikah\x01und hoped det du vold teruggeven.\x01Ik wéted für sevin ár...\x02", "box_type": 0},
    {"id": 0x7083, "text": "\x1AUnd...nú du sin zurück.  \x01dark age ruled af Ganondorf \x01Ond Kong skal end!\x02", "box_type": 0},
    {"id": 0x7084, "text": "\x1A sex Vísmen skal opnen séled\x01dyr und lure Ganondorf zurück inn\x01 Hélag Rike.\x04\x1AIk skal dan sél dyr til  \x01Hélag Rike frá þet verden.\x04\x1AThus, Ganondorf Ond Kong skal\x01vaniş frá Hyrule.\x04\x1A\x0F...\x01In order til dó þet, Ik mos dín \x01kúrage aftur. Bitte protekt mik\x01meðan Ik dó mís part.\x04\x1AUnd hér ist ain vápn det kan \x01penetrate Ond Kongs defenses...\x01 kraft given til kosen \x01ainar...\x04\x1A\x06\x0F hélag \x05Dpil de Ljós\x05@!!!\x02", "box_type": 0},
    {"id": 0x7085, "text": "\x1AAber du lat dín vakt ned...\x01Ik viss du vold skinen wenn Ik lat\x01þet kind wander kring!\x02", "box_type": 0},
    {"id": 0x7086, "text": "\x1AMís nur mistake var til slightli\x01underestimate kraft de þet\x01kind...\x02", "box_type": 0},
    {"id": 0x7087, "text": "\x1ANon...\x01Et var ne kinds kraft Ik\x01misjudged, et var kraft de\x01 Triforce de Courage!\x04\x1AAber, mit Triforce de Wisdom\x01det Zelda havt...\x01Wenn Ik obtén þese twei Triforcear...\x04\x1ADan, Ik skal werden true\x01ruler de verden!!\x02", "box_type": 0},
    {"id": 0x7088, "text": "\x08 Okarina de Tids opened \x01dyr. Held de Tid, mit \x01Meister Sverd, deskended hér.\x09\x02", "box_type": 2},
    {"id": 0x7089, "text": "Et síms strange det paks de\x01dogs roam unser stríts an naht...\x01Dót ne det sím weird til du?\x02", "box_type": 0},
    {"id": 0x708A, "text": "Hé, sonni, Ik skal sagen du einwat\x01helpful...\x04Ik hérd þar ist ain \x05Amistisk \x01fúntén\x05@ somewhere nér  \x01kastel...\x02", "box_type": 0},
    {"id": 0x708B, "text": "\x1AWenn du vollen til teruggeven til dín\x01original tid, teruggeven Meister \x01Sverd til \x05APedestal de Tid\x05@.\x04\x1AAf dóend þet, du skal travel zurück\x01in tid sevin ár....\x02", "box_type": 0},
    {"id": 0x708C, "text": "\x1A tid skal komen wenn du skal\x01have til teruggeven hér snellig...\x01Ik skal ték þet til du für wenn \x01det tid komt...\x04\x1A sang til teruggeven du til  \x01Tempel de Tid...\x01\x05D Prelude de Ljóss\x05@...\x02", "box_type": 0},
    {"id": 0x708D, "text": "\x1AIk am \x05AImpa \x05@de Sheikahs.\x01Ik am responsible für protekting\x01Prinsess Zelda. Everything ist \x01exaktli als Prinsess foretold.\x02", "box_type": 0},
    {"id": 0x708E, "text": "Wenn kastel soldiers vinden du,\x01þar skal vesen trúble. lat mik \x01léd du út de kastel.\x02", "box_type": 0},
    {"id": 0x708F, "text": "\x08Hé du! Ne kabruk ein trúble!\x09\x0B\x02", "box_type": 0},
    {"id": 0x7090, "text": "\x1ADu sin ain kúrageús dreng...\x01Du sin héding út auf ain grós, nüv \x01adventure, sin ne du?\x04\x1AMís role in Prinsesss drém\x01var til ték ain melodi\x05A \x05@til ain\x01frá skog.\x04\x1AÞet ist ain ankient \x05Cmelodi passed \x01ned af Konglig Família\x05@.\x04\x1AIk have pléed þet sang für \x01Prinsess Zelda als ain lullabi ever\x01weil ela var ain babi...\x04\x1AÞar ist mistisk kraft in \x01þese notes.\x04\x1ANú hlusten karefulli...\x02", "box_type": 0},
    {"id": 0x7091, "text": "\x1AAlle tragedi det havt befallen\x01Hyrule var mís dóend...\x04\x1AIk var so ung...Ik konde ne\x01komprehend konseqenkes de \x01triing til kontrol Hélag Rike.\x04\x1AIk dragged du inn et, ok.\x04\x1ANú et ist tid für mik til maken op \x01für mís mistakes...\x04\x1ADu mos lé Meister Sverd til \x01rest und klose Dyr de Tid...\x02", "box_type": 0},
    {"id": 0x7092, "text": "\x1AHowever, af dóend þet, road\x01millum tidar skal vesen klosed...\x02", "box_type": 0},
    {"id": 0x7093, "text": "\x1A\x0F,\x01geven Okarina til mik...\x04\x1AAls ain Sage, Ik kan teruggeven du\x01til dín original tid mit et.\x02", "box_type": 0},
    {"id": 0x7094, "text": "\x1AWenn péke teruggevenar til Hyrule...\x04\x1AEt skal vesen tid für uns til sagen \x01gut-farvel...\x02", "box_type": 0},
    {"id": 0x7095, "text": "\x1ANú, Gáe home, \x0F.\x01Regain dín verloren tid!\x04\x1AHome... \x01var du sin supposed til vesen...\x01 veg du sin supposed til vesen...\x02", "box_type": 0},
    {"id": 0x7096, "text": "\x06F\x08Tsk\x09 \x08Tsk.\x09\x0B\x02", "box_type": 0},
    {"id": 0x7097, "text": "Vel, kannski det ist ok meir\x01gegn ain kind til betalen.\x0B\x02", "box_type": 0},
    {"id": 0x7098, "text": "OK, Ik skal lat du pasar,\x01snellig!\x0B\x02", "box_type": 0},
    {"id": 0x7099, "text": "HALTEN ET Ain GEHEIMNIS \x01FRÁ ALLE.\x02", "box_type": 0},
    {"id": 0x709A, "text": "Mar, Ik am SO tired!\x04 naht watk ist so boring!\x01Ik wiş sum ghosts vold komen \x01út oder einwat...\x04Hé, Ik am sannlig interested in \x01ghosts!\x04Studying sen ist ain hobbi de mís,\x01aber du aldrei weten... tid\x01might komen wenn det kind de\x01knóledge might vesen useful!\x02", "box_type": 0},
    {"id": 0x709B, "text": "Mís prekiús klein puppis fur koat\x01ist meir spekial kompared til  \x01ander mutts kring hér!\x02", "box_type": 0},
    {"id": 0x709C, "text": "Mís prekiús puppi kan rennen faster\x01dan ein de ander mutts\x01kring hér!\x02", "box_type": 0},
    {"id": 0x709D, "text": "Ik ne kan vinden mís puppi aniwhere!\x01Ik mos du til sé für et! Bitte!\x02", "box_type": 0},
    {"id": 0x709E, "text": "\x06L\x08Arrrgh!\x09\x01Det ist ne mís dog! \x01Hú konde du mix op mís puppi\x01mit ain mutt als det?!\x02", "box_type": 0},
    {"id": 0x709F, "text": "\x06F\x08Richard!\x09\x04Þet ist mís klein Richard!\x01Dank dir! Dank dir!\x01Ik skal geven þet til du als ain\x01belónung!\x02", "box_type": 0},
    {"id": 0x70A0, "text": "An naht et ist dangerús til Gáe út\x01mit alle wild dogs kring...\x01Non, Ik wasn't warning du! \x01Ik am worried om mís puppi!\x02", "box_type": 0},
    {"id": 0x70A1, "text": "Hiyeee!\x01Velkom til \x05AGlad Mask Búð\x05@!\x01Wir handel in maskar det bring \x01happiness til alle!\x04Hú vold du als til vesen ain \x01happiness salesman? Ik skal lend du\x01ain mask. Du seljen mask und \x01bring \x05Amonei \x05@zurück hér.\x04Wenn du vollen til réd gut \x01print, nim ain sé an \x05Asign \x01\x05@rétt yfir þar.\x04Eftir du havst sold alle maskar,\x01du skal werden glad\x05A \x05@dikself!\x04\x06@Have féþ...\x0B\x02", "box_type": 0},
    {"id": 0x70A2, "text": "\x08Val ain mask mit lét oder rétt\x01auf \x05Dª\x05@.\x01\x1B\x05BTalen til búð óner.\x01Ne línen\x05@\x09\x02", "box_type": 0},
    {"id": 0x70A3, "text": "Ain \x05Amask \x05@ist ain \x05F¡ Knopp \x05@ting. Sette\x01et til \x05F¡\x05@ und druk \x05F¡\x05@ til drage et.\x04Wenn du talen til einwer mit ain \x01mask auf, du might kregen ain rékçion.\x04Wenn anione ist interested in \x01mask, er oder ela skal ask du \x01om et. Einwer möge vollen  \x01mask.\x04Somewhere in verden, einwer\x01ist wéting für þese maskar.\x04\x062Bara have féþ...\x0B\x02", "box_type": 0},
    {"id": 0x70A4, "text": "Ik might have gesehen ain söt klein\x01fraua kring hér...\x01Kannski ela ging til kastel?\x01Wer wet?\x02", "box_type": 0},
    {"id": 0x70A5, "text": "Ó, stór! Du sold et!\x01Bitte betalen zurück \x05A10 Rubinar \x05@für\x01 Keatonmask nú.\x0B\x02", "box_type": 0},
    {"id": 0x70A6, "text": "Ó! Du havstn't sold newest\x01mask iet. Bara have féþ... Halten\x01triing ain wenig leng.\x0B\x02", "box_type": 0},
    {"id": 0x70A7, "text": "Payment kreeg!\x0B\x02", "box_type": 0},
    {"id": 0x70A8, "text": "\x08Wat?!\x09\x01Du ne have mís monei?!\x04\x08Hú dare du!\x09\x04Du vold beter bring mik mís monei...\x01oder else!\x0B\x02", "box_type": 0},
    {"id": 0x70A9, "text": "Ó iéh!\x04Meir vel ferdig!\x01Alle maskar sin sold út.\x04Ik viss Ik konde trust du!\x0B\x02", "box_type": 0},
    {"id": 0x70AA, "text": "\x1AAls ain belónung...\x01Ik skal lend du þet spekial mask.\x04\x1AÞet ist \x05ASannheitsmask\x05@. Et ist ain\x01mistisk mask passed ned af \x01 Sheikah.\x04\x1AMit þet mask du kan séen inn \x01ander folks hugar...\x01Et ist useful, aber skari!\x04\x1AWarüm ist et skari?\x04\x1ADu möge vinden út als du gró\x01older und diskover true \x01méning de líf...\x04\x1AHó hó hó!\x0B\x02", "box_type": 0},
    {"id": 0x70AB, "text": "Frá nú auf du kan línen ein\x01mask du vollen.\x01Bara have féþ...\x0B\x02", "box_type": 0},
    {"id": 0x70AC, "text": "Welcome!\x01Welk mask kan Ik lend til du?\x0B\x02", "box_type": 0},
    {"id": 0x70AD, "text": "\x08Choose ain mask mit lét oder rétt \x01auf \x05Dª\x05@.\x01\x1B\x05BAsk om Sannheitsmask\x01Ne línen ain mask\x05@\x09\x02", "box_type": 0},
    {"id": 0x70AE, "text": "Þet ist \x05ASannheitsmask\x05@. Et ist ain\x01mistisk mask passed ned af \x01 Sheikah.\x04Mit þet mask du kan séen inn \x01ander folks hugar. Et ist useful,\x01aber skari!\x04Warüm ist et skari?\x04Du skal vinden út als du gró older!\x04Hó hó hó!\x0B\x02", "box_type": 0},
    {"id": 0x70AF, "text": "\x08\x05ASannheitsmask -- Ne für Sale\x05@\x01Þet mask havt spekial kraftar.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B0, "text": "\x08\x05ASkallmask -- Price 20 Rubinar\x05@\x01Ain horned Skallmask.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B1, "text": "\x08\x05AAndemask -- Price 30 Rubinar\x01\x05@Ain sad, wúden mask.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B2, "text": "\x08\x05AKeatonmask -- Price 10 Rubinar\x01\x05@Keaton stuff ist hot, hot, hot!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B3, "text": "\x08\x05AKaninhuv -- Price 50 Rubinar\x01\x05@Mit swinging rabbit órar!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B4, "text": "\x08\x05ASkallmask -- Free til Línen\x05@\x01Ain horned Skallmask.\x09\x0A\x02", "box_type": 0},
